window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0191", [{"word":"totalitarian","ipa_uk":"/ˌtəʊtəˈlɪtəriən/","ipa_us":"/ˌtoʊtəˈlɪtəriən/","definition_zh":"极权主义的；（政权）试图控制社会与私人生活全部领域的","definition_en":"of or relating to a system of government that claims control over every part of public and private life and allows no rival political power","core_image":"一张巨网罩住整座城市，从工厂到厨房，每一扇窗都连着同一根线","scene":"城市里每块布告栏都印着同一张面孔，广播从早到晚只有一种声音。The totalitarian state demanded that every family report on its neighbours.","sceneCN":"句中这个词形容一种把公共与私人生活都纳入控制的政权（第 1 个义项：主张国家权力覆盖社会全部领域、不容对立政治力量存在的）；句意为极权国家要求每个家庭举报邻居。图中可辨识物件：布告栏、同一张面孔、广播喇叭、紧闭的家门、举报表格。","pos":[{"tag":"adj.","zh":"极权主义的；全面控制社会与私人生活的"},{"tag":"n.","zh":"极权主义者；极权政权的支持者"}],"collocations":[{"phrase":"totalitarian state","zh":"极权国家"},{"phrase":"totalitarian regime","zh":"极权政权"},{"phrase":"totalitarian rule","zh":"极权统治"},{"phrase":"totalitarian system","zh":"极权制度"},{"phrase":"totalitarian ideology","zh":"极权意识形态"},{"phrase":"totalitarian control","zh":"极权控制"}],"forms":[{"label":"比较级","form":"more totalitarian"},{"label":"最高级","form":"most totalitarian"},{"label":"名词（制度）","form":"totalitarianism"},{"label":"名词（支持者，复数）","form":"totalitarians"},{"label":"形容词（倾向极权的）","form":"totalitarianizing"}],"derivatives":[{"word":"totalitarianism","pos":"n.","zh":"极权主义；极权制度"},{"word":"totalist","pos":"n./adj.","zh":"整体主义者 / 整体主义的"},{"word":"totalistic","pos":"adj.","zh":"把事物当作不可分割整体的"},{"word":"totalize","pos":"v.","zh":"使总体化；把各部分合成整体"},{"word":"total","pos":"adj./n.","zh":"全部的；总数"}],"senses":[{"no":"01","title":"State control over every sphere","titleCN":"国家权力覆盖社会全部领域","definition":"describing a regime that claims authority over industry, media, education, family life and private belief alike","definitionCN":"形容一种政权声称对工业、媒体、教育、家庭生活与个人信念都拥有支配权","example":"The totalitarian state demanded that every family report on its neighbours.","exampleCN":"这个极权国家要求每个家庭举报邻居。","why":"The word was coined in English in the nineteen-twenties on the Italian model totalitario, from total, because such a regime claims the whole of life and not merely the machinery of government.","whyCN":"这个词在二十世纪二十年代按意大利语 totalitario 的样式在英语中造出，词干是「全部」，因为这类政权声称要管的是整个生活，而不只是政府机构。"},{"no":"02","title":"No tolerated opposition","titleCN":"不容许任何对立政治力量","definition":"allowing only one party and treating organised criticism as a crime","definitionCN":"只允许一个政党存在，把任何有组织的批评都当作犯罪","example":"Opposition parties were banned outright under the totalitarian system.","exampleCN":"在极权制度下，反对党被彻底取缔。","why":"If the state owns the whole, a rival centre of loyalty is by definition a crack in that whole.","whyCN":"如果国家声称拥有一切，那么另一个忠诚中心在定义上就是那个整体上的一道裂缝。"},{"no":"03","title":"One official ideology","titleCN":"只承认一种官方意识形态","definition":"requiring public adherence to a single doctrine and presenting it as the settled truth about society","definitionCN":"要求公众信奉唯一一套学说，并把它说成关于社会的定论","example":"Schoolbooks taught the totalitarian doctrine in every grade.","exampleCN":"教科书在每个年级都讲授这套极权学说。","why":"A single party needs a single story about the past and the future, so doctrine becomes part of the state apparatus.","whyCN":"一党统治需要唯一一套关于过去与未来的叙述，于是学说本身成了国家机器的一部分。"},{"no":"04","title":"Demanding total obedience from a person","titleCN":"要求个人无条件服从","definition":"describing a leader, party or rule that requires unqualified obedience from each individual","definitionCN":"形容某个领袖、政党或规则要求每个人无条件服从","example":"The party's totalitarian demand reached even into the choice of a career.","exampleCN":"这个政党的极权要求甚至伸进了职业选择。","why":"The adjective attaches to the agent as well as to the system: a ruler is called totalitarian when he asks for the whole person.","whyCN":"这个形容词既能形容制度，也能形容施动者：当一个统治者索要整个人时，他就被称为极权的。"},{"no":"05","title":"Control extended to non-state institutions","titleCN":"把控制延伸到非国家机构","definition":"used of a workplace, school or family that regulates every detail of its members' lives","definitionCN":"用于形容把成员生活每个细节都管起来的单位、学校或家庭","example":"Critics called the company's totalitarian rules a parody of government.","exampleCN":"批评者说这家公司的极权规章是对政府的一次戏仿。","why":"The word travels: any body that claims the whole of a person's life can take the label once reserved for the state.","whyCN":"这个词会转移：任何索要一个人全部生活的团体，都能用上这个原属国家的标签。"},{"no":"06","title":"Uniform style in art and building","titleCN":"艺术与建筑上的整齐划一","definition":"describing an aesthetic that suppresses individual variation in favour of one approved style","definitionCN":"形容压抑个体差异、只留一种被批准风格的美学","example":"The regime's totalitarian architecture left no room for ornament.","exampleCN":"这个政权的极权建筑不留任何装饰的余地。","why":"Art follows politics here: a style that admits only one form is the visible face of one-party rule.","whyCN":"在这里艺术跟着政治走：只容一种形式的风格，就是一党统治看得见的脸。"},{"no":"07","title":"A supporter of such a system","titleCN":"支持极权制度的人（可数名词）","definition":"a person who advocates or serves a totalitarian regime","definitionCN":"主张或服务于极权政权的人","example":"The memoir describes how a young totalitarian rose through the party.","exampleCN":"这本回忆录写到一个年轻的极权主义者如何在党内攀升。","why":"The noun arrived later than the adjective and always names a person, never a doctrine.","whyCN":"名词义晚于形容词出现，而且始终指人，不指学说。"},{"no":"08","title":"The historical label for twentieth-century regimes","titleCN":"二十世纪特定政权的历史标签","definition":"the term historians use for Fascist Italy, Nazi Germany and the Soviet system, and debate as a comparative category","definitionCN":"历史学家用于法西斯意大利、纳粹德国与苏联体制的说法，并作为比较范畴加以争论","example":"Historians still argue about how far the totalitarian label fits each case.","exampleCN":"历史学家至今仍在争论这个极权标签在多大程度上适用于各个个案。","why":"The word was born as a description of one regime and later became a category that scholars test against others.","whyCN":"这个词最初只是对某一个政权的描述，后来变成学者用来检验其他政权的范畴。"}],"etymology":{"intro":{"en":"Totalitarian was formed in English in 1926 as a description of Italian fascism, on the model of Italian totalitario and with an ending borrowed from authoritarian. The root totus is Latin, but its deeper origin is not settled.","cn":"totalitarian 于 1926 年在英语中造出，用来描述意大利法西斯主义，仿意大利语 totalitario 而成，词尾借自 authoritarian。词干 totus 是拉丁语，但其更深来源未有定论。"},"items":[{"era":"LATIN TOTUS","en":"Totus meant 'all, whole, entire'. Its deeper origin is unknown, so any Indo-European form proposed for it is a reconstruction rather than a demonstrated source.","cn":"totus 意为「全部、整个」。其更深来源不明，凡为其提出的印欧语形式都属重构，并非已证实的来源。"},{"era":"MEDIEVAL LATIN TOTALIS","en":"Totalis 'entire' was built on totus and passed through Old French as total; the same stem yields totality and totalize.","cn":"totalis「整个的」由 totus 构成，经古法语进入英语作 total；同一词干还产生 totality 与 totalize。"},{"era":"ITALIAN TOTALITARIO","en":"In the nineteen-twenties Italian political writing used totalitario for a state that claimed the whole of society; the exact first user is disputed.","cn":"二十世纪二十年代意大利政治写作使用 totalitario 指声称拥有整个社会的国家；最早使用者为谁仍有争议。"},{"era":"ENGLISH 1926","en":"English totalitarian is recorded in 1926 in reference to Italian fascism. It was framed on total with the ending of authoritarian rather than on a Latin base.","cn":"英语 totalitarian 于 1926 年见于记录，指意大利法西斯主义。它以 total 为干、取 authoritarian 的词尾构成，并非来自某个拉丁词形。"},{"era":"NOUN AND CATEGORY","en":"The noun for a member of such a party is recorded from 1938. After the war the term widened into a comparative category applied to several regimes.","cn":"指这类政党成员的 noun 义自 1938 年见于记录。战后这个词扩大为一个用于多个政权的比较范畴。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain for the pre-Latin origin of totus and for the identity of the first Italian coiner; the date 1926 itself is firm.","cn":"来源不确定之处在于 totus 在拉丁语之前的来源，以及首位意大利造词者是谁；1926 这个年代本身是确定的。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin stem total-, which are easy to mix up in form; group two holds political adjectives that overlap in meaning but differ in what they claim.","cn":"第一组是同出拉丁词干 total- 的词，形式上极易混淆；第二组是语义重叠但主张内容不同的政治形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"total","ipa":"/ˈtəʊtəl/","tag":"same stem, plain adjective","definition":"Complete in extent or number; it counts or measures a quantity and makes no political claim.","definitionCN":"指范围或数量上的完整；它只是计数或计量，不作政治主张。"},{"word":"totality","ipa":"/təʊˈtæləti/","tag":"the whole as a noun","definition":"The whole of something taken together, as in the totality of the evidence; a noun of quantity, not of rule.","definitionCN":"指某物合起来的整体，如证据的整体；是数量的名词，不是统治的名词。"},{"word":"totalize","ipa":"/ˈtəʊtəlaɪz/","tag":"verb of gathering","definition":"To gather parts into one whole or to state something as a single total; it describes a way of counting, not of governing.","definitionCN":"指把各部分合成整体，或把某物说成一个总数；说的是计数方式，不是统治方式。"},{"word":"totalism","ipa":"/ˈtəʊtəlɪzəm/","tag":"rare doctrinal noun","definition":"A rare term for the doctrine that society should be treated as one indivisible unit; it names a belief rather than the apparatus of a state.","definitionCN":"罕见说法，指社会应被视为不可分割整体的信念；它命名一种信念，而非国家机器。"}]},{"heading":"NEAR MEANING","entries":[{"word":"authoritarian","ipa":"/ˌɔːˈθɒrɪteəriən/","tag":"order over freedom","definition":"Favouring imposed order and obedience; it can describe a strong government without claiming control of every private detail.","definitionCN":"偏爱强加秩序与服从；可形容强势政府，但不必然声称控制每个私人细节。"},{"word":"dictatorial","ipa":"/ˌdɪktəˈtɔːriəl/","tag":"one ruler's will","definition":"Marked by the unchecked will of a single ruler; the emphasis is on who decides, not on how far the state reaches.","definitionCN":"以单一统治者不受制约的意志为特征；重点在谁作决定，而非国家伸手多远。"},{"word":"despotic","ipa":"/dɪˈspɒtɪk/","tag":"arbitrary power","definition":"Of a ruler who exercises power arbitrarily and harshly; it stresses cruelty and caprice rather than total organisation.","definitionCN":"指统治者专断而严酷地行使权力；强调残暴与任性，而非全面组织社会。"},{"word":"absolutist","ipa":"/æbˈsuːlətɪst/","tag":"unlimited legal claim","definition":"Of a doctrine that the sovereign holds unlimited legal authority; it is a claim about law, while totalitarian is a claim about social life.","definitionCN":"指君主拥有无限法律权威的学说；它主张的是法律权限，而 totalitarian 主张的是社会生活。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin pieces, real derived words and real fixed phrases.","cn":"正常联想：真实的拉丁语构件、真实的派生词与真实的固定搭配。"},"normal":[{"en":"total plus the ending of authoritarian: the whole of life, enforced by authority.","cn":"total 加上 authoritarian 的词尾：生活的全部，由权威来执行。"},{"en":"The family runs total, totality, totalize, totalitarian and totalitarianism.","cn":"同族词包括 total、totality、totalize、totalitarian 与 totalitarianism。"},{"en":"Latin totus 'whole' is the root, and its own earlier origin is unknown.","cn":"词根是拉丁 totus「全部」，它更早的来源不明。"},{"en":"Fixed phrases mark the political use: totalitarian state, totalitarian regime, totalitarian control.","cn":"固定搭配标出政治用法：极权国家、极权政权、极权控制。"},{"en":"The ending matches authoritarian and egalitarian, both nineteenth-century political coinages.","cn":"词尾与 authoritarian、egalitarian 一致，这两个词都是十九世纪的政治造词。"}],"abstract":[{"en":"Picture a single key that opens every door on one street, so no door can be locked from inside.","cn":"想象一把钥匙能开一条街上所有的门，于是没有一扇门能从里面反锁。"},{"en":"Picture a map with one colour only, so no border can be told from another border.","cn":"想象一张只有一种颜色的地图，于是任何边界都分不出彼此。"},{"en":"Picture a choir where every voice is tuned to the same note, leaving no second line to hear.","cn":"想象一个合唱团把每个声音都调到同一个音，于是听不到第二条声部。"}]},"examples":[{"en":"The totalitarian regime censored newspapers, schools and private letters alike.","cn":"这个极权政权把报纸、学校与私人信件一并审查。"},{"en":"Scholars debate whether the totalitarian label describes a type or only a period.","cn":"学者在争论极权这个标签描述的是一个类型，还是仅仅一个时期。"},{"en":"Her novel shows how a totalitarian demand can enter an ordinary family.","cn":"她的小说展示极权的要求如何进入一个普通家庭。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「透头-他立」——把每个人的「头」都透过管起来，只许「立」一种声音 → 极权的","word":"totalitarian"},"root":"拉丁 totus「全部、整个」+ 英语形容词词尾（借自 authoritarian）；totus 更深来源不明，凡提出的印欧形式均为重构。","sensesIntro":{"en":"Eight senses fan out from one claim: the whole of life belongs to the state, and that claim is then read as a party monopoly, a doctrine, a demand on persons, an extension into other institutions, a style, a person and a historical label.","cn":"八个义项都从同一个主张展开：整个生活属于国家；这一主张再依次读作一党垄断、一套学说、对个人的索求、向其他机构的延伸、一种风格、一个人、一个历史标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: one net over the whole city, every window tied to the same wire.","cn":"核心意象：一张巨网罩住整座城市，每一扇窗都连着同一根线。"},"chain":["WHOLE SOCIETY","ONE PARTY","ONE DOCTRINE","TOTAL OBEDIENCE","EXTENDED REACH","UNIFORM STYLE"],"branches":[{"senses":"01 · 08","en":"DOCTRINE AND LABEL: the claim about the whole of life begins as a description and later becomes a category historians test.","cn":"主张与标签：关于整个生活的主张先是描述，后来成为历史学家检验的范畴。"},{"senses":"02 · 03","en":"PARTY AND CREED: one party needs one story, so the monopoly of power and the monopoly of truth are the same institution seen twice.","cn":"政党与信条：一党需要一套叙述，于是权力的垄断与真理的垄断是同一机构的两种看法。"},{"senses":"04 · 07","en":"PERSON AND SYSTEM: a ruler can be called totalitarian for demanding the whole person, and the noun names whoever serves that demand.","cn":"人与制度：统治者因索要整个人而被称为极权的，名词则指服务于这一索要的人。"},{"senses":"05","en":"BEYOND THE STATE: the same demand appears in a firm or a family, which shows the claim is about control rather than about office.","cn":"越过国家：同样的索求出现在公司或家庭里，说明这一主张关乎控制，而非关乎公职。"},{"senses":"06","en":"VISIBLE FORM: a style admitting one shape only is the aesthetic mirror of one-party rule.","cn":"可见形态：只容一种形状的风格，是一党统治在美学上的镜像。"}]},"affixes":{"intro":{"en":"Totalitarian is an English coinage assembled from a Latin root and two productive endings, so its parts can be read separately from its politics.","cn":"totalitarian 是英语造词，由一个拉丁词根与两个能产词尾拼成，因此其构件可以脱离政治含义单独读出。"},"latinIntro":{"en":"Latin totus gives totalis and, through French, total; the endings -arian and -ism came into English from Latin and Greek patterns and now build many modern labels.","cn":"拉丁 totus 产生 totalis，并经法语产生 total；词尾 -arian 与 -ism 由拉丁与希腊的模式进入英语，如今构成许多现代标签。"},"items":[{"word":"totus","structure":"totus (Latin adjective, 'all, whole')","meaning":"whole, entire, all","meaningCN":"全部；整个","example":"The root carries the idea of a whole with no part left outside.","exampleCN":"这个词根带着「整体，无一部分在外」的意思。"},{"word":"totalis","structure":"totalis (Medieval Latin adjective, from totus)","meaning":"entire, total","meaningCN":"整个的；总体的","example":"The medieval form supplied the everyday adjective total.","exampleCN":"这个中世纪词形提供了日常形容词 total。"},{"word":"total","structure":"total (English adjective and noun, from Old French)","meaning":"complete; the whole amount","meaningCN":"完整的；总数","example":"The total cost was never published.","exampleCN":"总成本从未公布。"},{"word":"totality","structure":"total + -ity (state or quality)","meaning":"the whole taken together","meaningCN":"整体；全部","example":"The totality of the records was sealed.","exampleCN":"全部记录被封存。"},{"word":"totalitarian","structure":"total + -arian (one who, or of a kind)","meaning":"of a state claiming the whole of life","meaningCN":"主张掌控整个生活的；极权的","example":"The totalitarian state claimed the whole of life.","exampleCN":"这个极权国家声称拥有整个生活。"},{"word":"totalitarianism","structure":"totalitarian + -ism (system or doctrine)","meaning":"the system or doctrine of such rule","meaningCN":"极权制度或学说","example":"Totalitarianism reduces citizens to subjects.","exampleCN":"极权制度把公民降为臣民。"},{"word":"-arian","structure":"-arian (English suffix, from Latin -arius)","meaning":"belonging to, or one who follows","meaningCN":"属于……的；信奉……的人","example":"The ending also builds authoritarian and egalitarian.","exampleCN":"这个词尾还构成 authoritarian 与 egalitarian。"},{"word":"-ism","structure":"-ism (English suffix, from Greek -ismos)","meaning":"a practice, system or doctrine","meaningCN":"实践、制度或学说","example":"The ending turns an adjective into the name of a system.","exampleCN":"这个词尾把形容词变成一种制度的名称。"},{"word":"totalize","structure":"total + -ize (to make or cause)","meaning":"to gather into one whole","meaningCN":"使成为整体","example":"The survey totalizes scattered local figures.","exampleCN":"这份调查把分散的地方数字汇成整体。"}],"latinEntries":[{"word":"totus","structure":"totus, tota, totum (adjective)","meaning":"all, whole, entire","meaningCN":"全部；整个"},{"word":"totalis","structure":"totalis, totale (adjective, Medieval Latin)","meaning":"entire, total","meaningCN":"整个的；总体的"},{"word":"totalitas","structure":"totalitas, totalitatis (f., third declension, Medieval Latin)","meaning":"wholeness, entirety","meaningCN":"整体性；全部"}],"derivatives":[{"word":"totalitarianism","pos":"n.","zh":"极权主义；极权制度"},{"word":"totalism","pos":"n.","zh":"整体主义（罕见）"},{"word":"totalistic","pos":"adj.","zh":"整体主义的"},{"word":"totalize","pos":"v.","zh":"使总体化"},{"word":"totality","pos":"n.","zh":"整体；全部"}]}},{"word":"totalitarianism","ipa_uk":"/ˌtəʊtəˈlɪtəriənɪzəm/","ipa_us":"/ˌtoʊtəˈlɪtəriənɪzəm/","definition_zh":"极权主义；极权制度；全面控制社会与私人生活的政治体系","definition_en":"a political system or doctrine in which the state claims control over every part of public and private life and permits no rival power","core_image":"整座城市被画进同一张表格：每一户、每一班、每一场集会都填在同一格里","scene":"会议室的墙上挂着一幅城市平面图，每个街区旁都贴着同一份名单。The party defended totalitarianism as the only way to unite a divided country.","sceneCN":"句中这个词指把社会全部领域收归一个中心的制度（第 1 个义项：国家声称掌控公共与私人生活、不容对立权力的政治体系）；句意为该党为极权制度辩护，称它是团结分裂国家的唯一办法。图中可辨识物件：城市平面图、名单、盖章的表格、单排座椅、紧闭的百叶窗。","pos":[{"tag":"n.","zh":"极权主义；极权制度（不可数）"},{"tag":"n.","zh":"一种极权做法或极权性质（可数，较少用）"}],"collocations":[{"phrase":"rise of totalitarianism","zh":"极权主义的兴起"},{"phrase":"against totalitarianism","zh":"反对极权主义"},{"phrase":"totalitarianism of the party","zh":"政党的极权统治"},{"phrase":"theories of totalitarianism","zh":"极权主义理论"},{"phrase":"escape from totalitarianism","zh":"逃离极权统治"},{"phrase":"totalitarianism in the workplace","zh":"职场中的极权式管理"}],"forms":[{"label":"复数（指多种类型或实例）","form":"totalitarianisms"},{"label":"形容词","form":"totalitarian"},{"label":"名词（支持者）","form":"totalitarian"},{"label":"形容词（倾向该制度的）","form":"totalitarianizing"},{"label":"相关抽象名词","form":"totality"}],"derivatives":[{"word":"totalitarian","pos":"adj./n.","zh":"极权主义的 / 极权主义者"},{"word":"totalism","pos":"n.","zh":"整体主义（罕见）"},{"word":"totalist","pos":"n.","zh":"整体主义者"},{"word":"totalistic","pos":"adj.","zh":"整体主义的"},{"word":"totalize","pos":"v.","zh":"使总体化"}],"senses":[{"no":"01","title":"The system of total control","titleCN":"全面控制的政治制度","definition":"a system in which the state claims authority over every sphere of public and private life","definitionCN":"国家声称对公共与私人生活每个领域都拥有支配权的制度","example":"The party defended totalitarianism as the only way to unite a divided country.","exampleCN":"该党为极权制度辩护，称它是团结分裂国家的唯一办法。","why":"The noun names the system that the adjective describes, so what is claimed is the whole of life rather than a set of policies.","whyCN":"这个名词命名形容词所描述的制度，因此它主张的是整个生活，而不是一套政策。"},{"no":"02","title":"The doctrine behind the system","titleCN":"支撑这一制度的学说","definition":"the body of ideas that justifies one party's rule over all social activity","definitionCN":"为一党统治全部社会活动提供理由的那套观念","example":"His lectures treated totalitarianism as a theory before it was a government.","exampleCN":"他的讲座把极权主义当作一种先于政府的理论来处理。","why":"A system needs a justification, and the same word covers that justification when the emphasis shifts from practice to belief.","whyCN":"制度需要理由，当重心从实践转到信念时，同一个词也覆盖那套理由。"},{"no":"03","title":"One-party rule in practice","titleCN":"实践中的一党统治","definition":"the working arrangement of a single party holding all legal power and suppressing organised rivals","definitionCN":"一个政党掌握全部合法权力、压制有组织对手的实际安排","example":"Totalitarianism in practice meant a single ballot with a single name.","exampleCN":"实践中的极权统治意味着只有一张选票、一个名字。","why":"The doctrine becomes visible in a ballot paper, and at that point the word names an arrangement rather than an idea.","whyCN":"学说在一张选票上变得可见，此时这个词命名的是一种安排，而非一种观念。"},{"no":"04","title":"State penetration of daily life","titleCN":"国家权力深入日常生活","definition":"the extension of official supervision into housing, work, schooling and family routine","definitionCN":"把官方监督延伸进住房、工作、上学与家庭日常","example":"Totalitarianism reached the kitchen through ration books and inspection visits.","exampleCN":"极权统治借着配给簿与上门检查伸进了厨房。","why":"The claim to the whole of life is tested where life is lived, so the household becomes part of the system.","whyCN":"「整个生活」这一主张要在生活发生的地方受检验，于是家庭也成了制度的一部分。"},{"no":"05","title":"A category in political science","titleCN":"政治学中的比较范畴","definition":"an analytic label used to compare several twentieth-century regimes and to test how far they resemble one another","definitionCN":"用于比较若干二十世纪政权、检验它们相似程度的分析标签","example":"The seminar questioned whether totalitarianism is one category or several.","exampleCN":"研讨会在追问极权主义究竟是一个范畴还是几个范畴。","why":"Once used for more than one regime, the word becomes a tool of comparison rather than a name for one country.","whyCN":"一旦用于不止一个政权，这个词就变成比较工具，而不再是一国的名称。"},{"no":"06","title":"Extended use for an all-demanding group","titleCN":"延伸到要求全部忠诚的团体","definition":"the tendency of a firm, sect or club to regulate every part of a member's life","definitionCN":"公司、教派或社团管起成员生活每一部分的倾向","example":"Critics spoke of the totalitarianism of the modern office.","exampleCN":"批评者谈到现代办公室里的极权式管理。","why":"The word leaves the state when any organisation asks for the whole person, and the metaphor keeps its original demand.","whyCN":"当任何组织索要整个人时，这个词就离开国家，而这个比喻仍保留最初那种索求。"},{"no":"07","title":"The historical phenomenon of the 1930s","titleCN":"二十世纪三十年代的历史现象","definition":"the cluster of interwar regimes that historians group under this label","definitionCN":"历史学家归在这一标签下的两次大战之间的那批政权","example":"Courses on the nineteen-thirties begin with the study of totalitarianism.","exampleCN":"关于二十世纪三十年代的课程从研究极权主义开始。","why":"A period gives the word a concrete cast: it stops being a tendency and becomes a set of dated governments.","whyCN":"一个时期给了这个词具体轮廓：它不再是一种倾向，而成为一批有年代可查的政府。"},{"no":"08","title":"The quality of a policy or measure","titleCN":"某项政策或措施的极权性质","definition":"the abstract quality of a rule or practice that treats people as objects to be administered","definitionCN":"某项规则或做法把人当作被管理对象的抽象性质","example":"They objected to the totalitarianism of a rule that monitored every email.","exampleCN":"他们反对那条监控每封邮件的规则所含的极权性质。","why":"The abstract use drops the state and keeps only the mark of a claim without limits.","whyCN":"抽象用法抛开了国家，只留下「无边索求」这一特征。"}],"etymology":{"intro":{"en":"Totalitarianism is totalitarian plus -ism, recorded in 1926 alongside the adjective, first in reference to Italian fascism. The root is Latin totus 'whole', whose own origin is unknown.","cn":"totalitarianism 是 totalitarian 加 -ism，与形容词同在 1926 年见于记录，最初指意大利法西斯主义。词根是拉丁 totus「全部」，其自身来源不明。"},"items":[{"era":"LATIN TOTUS","en":"Totus 'whole, entire' is the base. Its deeper origin is not established, and any Indo-European form offered for it is a reconstruction.","cn":"totus「整个、全部」是词干。其更深来源未获证明，凡为其提出的印欧语形式都属重构。"},{"era":"TOTAL AND TOTALITARIAN","en":"Medieval Latin totalis and Old French total supplied the everyday adjective. English totalitarian was formed in 1926 on the Italian model totalitario, with the ending of authoritarian.","cn":"中世纪拉丁 totalis 与古法语 total 提供了日常形容词。英语 totalitarian 于 1926 年仿意大利语 totalitario 造出，词尾取自 authoritarian。"},{"era":"THE SUFFIX -ISM","en":"The ending -ism came into English through French and Latin from Greek -ismos, which names a practice or a doctrine rather than a single act.","cn":"词尾 -ism 经法语与拉丁语来自希腊语 -ismos，命名一种实践或学说，而非一次行动。"},{"era":"FIRST RECORD 1926","en":"The word appears in 1926 in English writing about Italy, where a totalitarian state was described as one in which everything is valued for its part in the state's power.","cn":"这个词 1926 年出现在关于意大利的英语写作中，当时把极权国家描述为一切事物都按其对国家权力的作用来估价的国家。"},{"era":"POSTWAR GENERALISATION","en":"After 1945 the term was applied to Nazi Germany and the Soviet Union, and it also served as an imprecise synonym for authoritarianism.","cn":"1945 年之后，这个词被用于纳粹德国与苏联，也被当作 authoritarianism 的不精确同义词使用。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain for the earlier origin of totus and for the first Italian coiner; the English record from 1926 is not in doubt.","cn":"来源不确定之处是 totus 的更早来源与首位意大利造词者；1926 年的英语书证本身并无争议。"}]},"similar":{"note":{"en":"Group one holds the -ism nouns that surround this word and are often swapped in writing; group two holds systems of rule that are weaker or narrower in what they claim.","cn":"第一组是围绕这个词、写作中常被互换的 -ism 名词；第二组是主张更弱或范围更窄的统治体制。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"totalitarian","ipa":"/ˌtəʊtəˈlɪtəriən/","tag":"the adjective and person","definition":"The adjective describes such a state, and as a noun it names a supporter; it is not the name of the system itself.","definitionCN":"作形容词描述这样的国家，作名词则指支持者；它不是制度本身的名称。"},{"word":"totalism","ipa":"/ˈtəʊtəlɪzəm/","tag":"doctrine of the whole","definition":"A rare word for the belief that a society should be treated as one indivisible unit; it lacks the specific party apparatus implied by totalitarianism.","definitionCN":"罕见说法，指社会应被视为不可分割整体的信念；它不含极权主义所暗示的特定政党机器。"},{"word":"absolutism","ipa":"/æbˈsuːluːtɪzəm/","tag":"unlimited legal power","definition":"The doctrine that the sovereign holds unlimited legal authority; it is a claim about law, not about the whole of social life.","definitionCN":"指君主拥有无限法律权威的学说；它主张的是法律权限，而非整个社会生活。"},{"word":"authoritarianism","ipa":"/ˌɔːθɒrɪˈteəriənɪzəm/","tag":"order without total reach","definition":"Rule that imposes order and obedience but need not claim control of every private detail; dictionaries often treat it as the looser term.","definitionCN":"强加秩序与服从的统治，但不必然声称控制每个私人细节；词典常把它视为更宽泛的说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dictatorship","ipa":"/dɪkˈteɪtəʃɪp/","tag":"one ruler's power","definition":"A system in which one person or small group holds unchecked power; it names the location of decision rather than the reach of the state.","definitionCN":"由一人或小集团掌握不受制约权力的制度；它命名决定权所在，而非国家伸手的范围。"},{"word":"despotism","ipa":"/dɪˈspɒtɪzəm/","tag":"arbitrary harsh rule","definition":"Rule by arbitrary and often cruel will; it stresses caprice and severity rather than total organisation.","definitionCN":"以专断、往往残酷的意志进行统治；强调任性严厉，而非全面组织社会。"},{"word":"autocracy","ipa":"/ɔːˈtɒkrəsi/","tag":"rule by one","definition":"Government by one person with unrestricted authority; the emphasis is on the number of rulers, not on how far control extends.","definitionCN":"由一人掌握无限权威的统治；重点在统治者的人数，而不在控制延伸多远。"},{"word":"police state","ipa":"/pəˈliːs steɪt/","tag":"apparatus of surveillance","definition":"A state controlled through police surveillance and repression; it names the instrument, while totalitarianism names the claim.","definitionCN":"靠警察监视与镇压控制的国家；命名的是手段，而极权主义命名的是主张。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real -ism ending, the real family of total words and the real political phrases.","cn":"正常联想：真实的 -ism 词尾、真实的 total 词族与真实的政论搭配。"},"normal":[{"en":"total plus -arian plus -ism: the doctrine that the whole of life belongs to one authority.","cn":"total 加 -arian 再加 -ism：整个生活属于一个权威的学说。"},{"en":"The family runs total, totality, totalize, totalitarian and totalitarianism.","cn":"同族词包括 total、totality、totalize、totalitarian 与 totalitarianism。"},{"en":"The ending -ism names systems, as in absolutism and authoritarianism.","cn":"词尾 -ism 命名制度，如 absolutism 与 authoritarianism。"},{"en":"Fixed phrases mark the debate: rise of totalitarianism, theories of totalitarianism, escape from totalitarianism.","cn":"固定搭配标出讨论语境：极权主义的兴起、极权主义理论、逃离极权统治。"},{"en":"Historians pair it with fascism and Stalinism as a comparative category.","cn":"历史学家把它与法西斯主义、斯大林主义并列为比较范畴。"}],"abstract":[{"en":"Picture a form long enough to hold a whole life, with one box for every hour.","cn":"想象一张长到能装下一生的表格，每个小时都有一格。"},{"en":"Picture a building with one entrance and no exit sign.","cn":"想象一栋只有一个入口、却没有出口指示的建筑。"},{"en":"Picture a story told in one voice and repeated until it sounds like memory.","cn":"想象一个故事只用一种声音讲述，重复到听起来像记忆。"}]},"examples":[{"en":"The book traces the rise of totalitarianism between the two world wars.","cn":"这本书追溯两次世界大战之间极权主义的兴起。"},{"en":"Survivors wrote about daily life under totalitarianism.","cn":"幸存者写下了极权统治下的日常生活。"},{"en":"Some analysts warn against a totalitarianism of data collection.","cn":"一些分析者警告数据采集可能带来的极权性质。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「透头-他立-他瑞安-尼森」——把所有人的「头」都收进一个「立」字里，还要把它说成一门「主义」→ 极权主义","word":"totalitarianism"},"root":"totalitarian + -ism；totalitarian 由拉丁 totus「全部」构成的 total 加 authoritarian 词尾在 1926 年造出；totus 更深来源不明。","sensesIntro":{"en":"Eight senses move from the system to its doctrine, then to practice, daily life, scholarly category, metaphor, historical period and finally the bare quality of a measure.","cn":"八个义项从制度移到学说，再到实践、日常生活、学术范畴、隐喻、历史时期，最后落到一项措施本身的抽象性质。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole city drawn onto one form, one box for every household.","cn":"核心意象：整座城市被画进同一张表格，每一户占一格。"},"chain":["WHOLE SOCIETY","ONE PARTY","OFFICIAL DOCTRINE","PRIVATE LIFE","COMPARATIVE LABEL","ALL-DEMANDING GROUP"],"branches":[{"senses":"01 · 08","en":"SYSTEM AND QUALITY: the name of a whole regime can shrink to the character of a single rule.","cn":"制度与性质：整个政权的名称可以缩到单条规则的性质上。"},{"senses":"02 · 03","en":"IDEA AND BALLOT: a doctrine is proved only when it appears on a ballot paper with one name.","cn":"观念与选票：一套学说只有在选票上只剩一个名字时才得到证明。"},{"senses":"04","en":"THE KITCHEN: the claim to the whole of life is tested at the stove and in the schoolroom.","cn":"厨房：对整个生活的主张要在灶台与教室里受检验。"},{"senses":"05 · 07","en":"CATEGORY AND PERIOD: a comparative tool and a dated phenomenon keep each other in check.","cn":"范畴与时期：比较工具与有年代的现象互相约束。"},{"senses":"06","en":"THE METAPHOR LEAVES HOME: when a firm asks for the whole person, the state word travels.","cn":"隐喻出走：当公司索要整个人时，这个国家词汇便转移过去。"}]},"affixes":{"intro":{"en":"This word stacks two endings on a Latin root, which makes it a compact model of how political labels are built in English.","cn":"这个词在一个拉丁词根上叠了两个词尾，是英语政治标签构词的紧凑样本。"},"latinIntro":{"en":"Totus supplies totalis and total; -arian marks a kind or a follower, and -ism marks a system or doctrine.","cn":"totus 提供 totalis 与 total；-arian 标记某类或追随者，-ism 标记制度或学说。"},"items":[{"word":"totus","structure":"totus (Latin adjective, 'all, whole')","meaning":"whole, entire","meaningCN":"全部；整个","example":"The root leaves nothing outside the whole.","exampleCN":"这个词根不许任何东西留在整体之外。"},{"word":"totalis","structure":"totalis (Medieval Latin, from totus)","meaning":"entire, total","meaningCN":"整个的；总体的","example":"Totalis gave the everyday adjective total.","exampleCN":"totalis 给出了日常形容词 total。"},{"word":"totalitarian","structure":"total + -arian (of a kind or follower)","meaning":"of a state claiming the whole of life","meaningCN":"主张掌控整个生活的","example":"The totalitarian claim covers work and worship.","exampleCN":"极权的主张覆盖工作与信仰。"},{"word":"totalitarianism","structure":"totalitarian + -ism (system or doctrine)","meaning":"the system or doctrine of such rule","meaningCN":"极权制度或学说","example":"Totalitarianism was analysed as a modern category.","exampleCN":"极权主义被当作一个现代范畴来分析。"},{"word":"-arian","structure":"-arian (English suffix, from Latin -arius)","meaning":"belonging to; one who follows","meaningCN":"属于……的；信奉……的人","example":"Authoritarian shares the ending.","exampleCN":"authoritarian 共用这个词尾。"},{"word":"-ism","structure":"-ism (English suffix, from Greek -ismos)","meaning":"a practice, system or doctrine","meaningCN":"实践、制度或学说","example":"The suffix turns descriptions into names of systems.","exampleCN":"这个词尾把描述变成制度的名称。"},{"word":"totalize","structure":"total + -ize (to make)","meaning":"to gather into a whole","meaningCN":"使成为整体","example":"The report totalizes local figures.","exampleCN":"报告把地方数字汇成整体。"},{"word":"totality","structure":"total + -ity (state)","meaning":"wholeness","meaningCN":"整体性","example":"The totality of the archive was sealed.","exampleCN":"全部档案被封存。"},{"word":"totalistic","structure":"total + -istic (characterised by)","meaning":"treating things as one whole","meaningCN":"把事物当作整体的","example":"A totalistic reading ignores internal detail.","exampleCN":"整体化的读法忽略内部细节。"}],"latinEntries":[{"word":"totus","structure":"totus, tota, totum (adjective)","meaning":"all, whole","meaningCN":"全部；整个"},{"word":"totalis","structure":"totalis, totale (adjective, Medieval Latin)","meaning":"entire, total","meaningCN":"整个的"},{"word":"totalitas","structure":"totalitas, totalitatis (f., third declension, Medieval Latin)","meaning":"wholeness","meaningCN":"整体性"}],"derivatives":[{"word":"totalitarian","pos":"adj./n.","zh":"极权主义的 / 极权主义者"},{"word":"totalistic","pos":"adj.","zh":"整体主义的"},{"word":"totalist","pos":"n./adj.","zh":"整体主义者 / 整体主义的"},{"word":"totalize","pos":"v.","zh":"使总体化"},{"word":"totalism","pos":"n.","zh":"整体主义（罕见）"},{"word":"totality","pos":"n.","zh":"整体；全部"}]}},{"word":"constitutionalism","ipa_uk":"/kənˌstɪtjuːʃəˈnælɪzəm/","ipa_us":"/kənˌstɪtjuːʃəˈnælɪzəm/","definition_zh":"立宪主义；宪政；主张以宪法限定政府权力并依宪治理的原则与制度","definition_en":"the principle or practice that a government's powers should be limited by a constitution and exercised according to its rules","core_image":"一本摊开的册子压住权杖的一角，权力的边被纸页框了出来","scene":"广场上的人群举着一本小册子，权杖的一端被一根细线牵住。The convention argued that constitutionalism protects citizens by dividing power.","sceneCN":"句中这个词指用宪法约束统治权、并把权力分开的制度主张（第 1 个义项：主张政府权力应由宪法限定、并依宪行使的原则）；句意为大会主张立宪主义通过分权保护公民。图中可辨识物件：小册子、权杖、细线、分格地图、签名栏。","pos":[{"tag":"n.","zh":"立宪主义；宪政（不可数）"},{"tag":"n.","zh":"某种立宪主张或做法（可数，较少用）"}],"collocations":[{"phrase":"tradition of constitutionalism","zh":"立宪传统"},{"phrase":"defend constitutionalism","zh":"维护宪政"},{"phrase":"liberal constitutionalism","zh":"自由主义立宪主张"},{"phrase":"constitutionalism and the rule of law","zh":"宪政与法治"},{"phrase":"erosion of constitutionalism","zh":"宪政的侵蚀"},{"phrase":"constitutionalism in practice","zh":"实践中的宪政"}],"forms":[{"label":"复数（指多种立宪传统）","form":"constitutionalisms"},{"label":"形容词","form":"constitutional"},{"label":"名词（拥护者）","form":"constitutionalist"},{"label":"副词","form":"constitutionally"},{"label":"相关名词（宪法）","form":"constitution"}],"derivatives":[{"word":"constitutional","pos":"adj.","zh":"宪法的；合宪的；体质的"},{"word":"constitutionalist","pos":"n.","zh":"宪政拥护者；宪法学者"},{"word":"constitutionality","pos":"n.","zh":"合宪性"},{"word":"constitution","pos":"n.","zh":"宪法；构成；体质"},{"word":"unconstitutional","pos":"adj.","zh":"违宪的"}],"senses":[{"no":"01","title":"Limiting power by a constitution","titleCN":"以宪法限定政府权力","definition":"the principle that a government may act only within limits set by a constitution","definitionCN":"政府只能在宪法设定的范围内行动的原则","example":"The convention argued that constitutionalism protects citizens by dividing power.","exampleCN":"大会主张立宪主义通过分权保护公民。","why":"A constitution fixes what a government may do, so the doctrine built on it is first of all a doctrine of limits.","whyCN":"宪法规定政府可以做什么，因此以宪法为基础的主张首先是一种关于限度的主张。"},{"no":"02","title":"A system governed under such limits","titleCN":"依宪治理的政治制度","definition":"an actual political order in which office-holders must answer to a constitution","definitionCN":"掌权者必须向宪法负责的实际政治秩序","example":"The country's constitutionalism survived two changes of government.","exampleCN":"这个国家的宪政经历了两届政府的更替仍延续下来。","why":"The principle becomes a system once courts and elections enforce it, so the same word names the practice as well as the idea.","whyCN":"一旦法院与选举使之生效，原则就变成制度，于是同一个词既指观念也指实践。"},{"no":"03","title":"Constitutional law and conventions","titleCN":"宪法法律与宪政惯例","definition":"the working body of written rules, court rulings and unwritten conventions that constrain office","definitionCN":"约束公职的成文规则、法院判决与不成文惯例所构成的运作体系","example":"British constitutionalism rests more on convention than on a single document.","exampleCN":"英国的宪政更多依靠惯例，而非一部单一文件。","why":"Not every constitution is one document, so the practice includes customs that carry the same limiting work.","whyCN":"并非每部宪法都是一份文件，因此这一实践也包含承担同样限权作用的习惯。"},{"no":"04","title":"The historical movement for written constitutions","titleCN":"争取成文宪法的历史运动","definition":"the nineteenth-century campaigns that demanded a written charter and an elected assembly","definitionCN":"十九世纪要求成文宪章与民选议会的那些运动","example":"Nineteenth-century constitutionalism produced charters across Europe.","exampleCN":"十九世纪的立宪运动在欧洲各地催生了宪章。","why":"Doctrine becomes a movement when crowds demand that limits be written down and displayed.","whyCN":"当人群要求把限度写下来并公之于众时，学说就变成了运动。"},{"no":"05","title":"Attachment to constitutional forms","titleCN":"对宪法形式与程序的坚持","definition":"insistence on proper constitutional forms even when the outcome would be easier without them","definitionCN":"即便绕过形式会更省事，仍坚持正当的宪法程序","example":"His constitutionalism showed in the small refusal to skip a hearing.","exampleCN":"他的宪政作风体现在一个小小的拒绝上：不肯跳过一场听证。","why":"Limits matter most at the moment when breaking them would be convenient, so the word also names a habit of respect.","whyCN":"限度恰在「破坏它更方便」的时刻最见分量，因此这个词也指一种尊重的习惯。"},{"no":"06","title":"Academic study of constitutional ordering","titleCN":"对宪政秩序的学术研究","definition":"the scholarly field that compares how constitutions limit and distribute power","definitionCN":"比较宪法如何限权与分权的学术领域","example":"She teaches constitutionalism alongside legal history.","exampleCN":"她把宪政研究与法律史一起讲授。","why":"A practice studied across countries turns into a subject with its own comparisons and disputes.","whyCN":"被跨国研究的实践会变成一个拥有自身比较与争论的学科。"},{"no":"07","title":"Rule-bound limits in any institution","titleCN":"任何机构内部的规则约束","definition":"the application of fixed rules to limit officers in a club, firm or university","definitionCN":"在社团、公司或大学里用固定规则限制管理者","example":"The club's constitutionalism kept one family from holding every post.","exampleCN":"这个社团的规则约束使一个家族无法占满所有职位。","why":"The same device works at any scale: write the rules down and make them bind the people in charge.","whyCN":"同一套办法在任何尺度上都有效：把规则写下来，并让它约束掌权的人。"},{"no":"08","title":"Excessive reliance on written rules","titleCN":"对成文规则的过度依赖（批评用法）","definition":"a critical use for legalism that trusts the text more than judgment or practice","definitionCN":"批评用法，指过分信任条文、忽视判断与实践的律条主义","example":"Critics warned that constitutionalism could freeze a living system.","exampleCN":"批评者警告，过度的条文崇拜可能冻住一个活的制度。","why":"The virtue of limits has a shadow: a text treated as complete can block the adjustments it was meant to allow.","whyCN":"限权的美德也有阴影：把文本当作完备，反而会堵住文本本想允许的调整。"}],"etymology":{"intro":{"en":"Constitutionalism is constitutional plus -ism, first recorded in 1832. The underlying Latin verb constituere means 'to set up', built on com- and statuere 'to set'. All dates below are approximate first citations.","cn":"constitutionalism 是 constitutional 加 -ism，最早见于 1832 年。其拉丁动词 constituere 意为「设立」，由 com- 与 statuere「放置」构成。以下年代均为首见书证的约数。"},"items":[{"era":"LATIN STATUERE","en":"Statuere 'to set, station, establish' is the causative of stare 'to stand'. The same root yields statute, statue and station.","cn":"statuere「放置、设立」是 stare「站立」的使动形式。同一词根还产生 statute、statue 与 station。"},{"era":"LATIN CONSTITUERE","en":"Com- added to statuere produced constituere 'to set up, establish, appoint', whose past participle is constitutus.","cn":"com- 加在 statuere 上构成 constituere「设立、建立、任命」，其过去分词为 constitutus。"},{"era":"LATIN CONSTITUTIO","en":"Constitutio named an act of settling or an ordinance, and passed through Old French into English as constitution in the fourteenth century.","cn":"constitutio 指「安顿、订立」的行为或法令，经古法语于十四世纪进入英语作 constitution。"},{"era":"POLITICAL SENSE","en":"The sense 'system of fundamental principles by which a community is governed' dates from the 1730s, and the written-document sense from the 1780s.","cn":"「治理共同体的根本原则体系」这一义项约起于十八世纪三十年代，成文文件义约起于十八世纪八十年代。"},{"era":"CONSTITUTIONALISM 1832","en":"The noun constitutionalism appeared in 1832 for the theory of constitutional government; constitutionalist is earlier, from 1766.","cn":"名词 constitutionalism 于 1832 年出现，指宪政政府的理论；constitutionalist 更早，见于 1766 年。"},{"era":"APPROXIMATE DATES","en":"The chain of forms is clear; only the first citation of each sense is approximate, so no part of the etymology is uncertain in source.","cn":"词形链条清楚，只有各义项的首见书证是约数；词源本身不存在来源不确定的部分。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin verb constituere; group two holds doctrines and phrases that also talk about limiting power.","cn":"第一组同出拉丁动词 constituere；第二组是同样谈论限权的学说与说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"constitution","ipa":"/ˌkɒnstɪˈtjuːʃən/","tag":"the document or make-up","definition":"The written or unwritten body of fundamental rules, or the make-up of a body or mind; it is the thing, not the doctrine about it.","definitionCN":"指成文或不成文的根本规则，也指身体或心性的构成；它是那个东西，而非关于它的学说。"},{"word":"constitutional","ipa":"/ˌkɒnstɪˈtjuːʃənəl/","tag":"the adjective","definition":"Allowed by or relating to a constitution; it describes a thing as lawful, while constitutionalism names the principle itself.","definitionCN":"指合宪的或与宪法有关的；它描述某物合法，而 constitutionalism 命名原则本身。"},{"word":"constitute","ipa":"/kənˈstɪtjuːt/","tag":"the verb","definition":"To form, set up or amount to; it is the action from which the whole family is built.","definitionCN":"指构成、设立或等于；它是整个词族所自出的动作。"},{"word":"constituent","ipa":"/kənˈstɪtjuənt/","tag":"part or voter","definition":"A part that makes up a whole, or a voter in a district; it is a piece or a person, never a doctrine.","definitionCN":"指构成整体的部分，或选区里的选民；它是部分或人，从不指学说。"},{"word":"statute","ipa":"/ˈstætʃuːt/","tag":"same root, other branch","definition":"A written law passed by a legislature, from statuere directly rather than through constituere; same root, different branch.","definitionCN":"指立法机关通过的成文法，直接出自 statuere 而非经 constituere；同根但不同支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rule of law","ipa":"/ˌruːl əv ˈlɔː/","tag":"law above persons","definition":"The principle that everyone, including officials, is subject to publicly known law; it overlaps with constitutionalism but stresses general law rather than a charter.","definitionCN":"指包括官员在内人人受公开法律约束的原则；与立宪主义重叠，但强调普遍法律而非宪章。"},{"word":"limited government","ipa":"/ˌlɪmɪtɪd ˈɡʌvənmənt/","tag":"the outcome","definition":"A government whose powers are restricted by law; it names the result, while constitutionalism names the means of securing it.","definitionCN":"指权力受法律限制的政府；它命名结果，而立宪主义命名取得该结果的手段。"},{"word":"legalism","ipa":"/ˈliːɡəlɪzəm/","tag":"rule for rule's sake","definition":"Over-attention to written rules and procedures; constitutionalism can shade into this, which is the critical sense of the word.","definitionCN":"指过分看重成文规则与程序；立宪主义可能滑向这种情形，这正是该词的批评义。"},{"word":"republicanism","ipa":"/rɪˈpʌblɪkənɪzəm/","tag":"republic and virtue","definition":"The doctrine that government should rest on elected representatives and civic virtue; it concerns who rules as much as how power is limited.","definitionCN":"指政府应基于民选代表与公民德性的学说；它既关心谁来统治，也关心权力如何受限。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the real family of constitution words and the real phrases of constitutional debate.","cn":"正常联想：真实的拉丁动词、真实的 constitution 词族与真实的宪政讨论搭配。"},"normal":[{"en":"con- 'together' plus statuere 'set': to set a state up on a fixed footing, then keep it within that footing.","cn":"con-「共同」加 statuere「放置」：把一个国家安放在固定的基座上，再让它守在这个基座里。"},{"en":"The family runs constitute, constitution, constitutional, constitutionalist and constitutionalism.","cn":"同族词包括 constitute、constitution、constitutional、constitutionalist 与 constitutionalism。"},{"en":"Fixed phrases mark the debate: rule of law, limited government, erosion of constitutionalism.","cn":"固定搭配标出讨论语境：法治、有限政府、宪政的侵蚀。"},{"en":"The same statuere root appears in statute, statue and station.","cn":"同一 statuere 词根还出现在 statute、statue 与 station 中。"},{"en":"The noun ends in -ism because it names a doctrine, not a document.","cn":"这个词以 -ism 结尾，因为它命名一种学说，而不是一份文件。"}],"abstract":[{"en":"Picture a crown whose height is cut to fit under a low ceiling of paper.","cn":"想象一顶王冠被削到刚好能待在纸做的低天花板之下。"},{"en":"Picture a key that works only inside a drawn rectangle.","cn":"想象一把只在画好的方框内起作用的钥匙。"},{"en":"Picture a game where the rulebook is older than every player and binds them all.","cn":"想象一场比赛，规则书比每个玩家都老，却约束所有人。"}]},"examples":[{"en":"The court described the new law as a breach of constitutionalism.","cn":"法院称这项新法律破坏了宪政。"},{"en":"Constitutionalism requires that emergency powers be written down and reviewed.","cn":"宪政要求紧急权力必须写成条文并接受审查。"},{"en":"Scholars compare American and British constitutionalism.","cn":"学者比较美国与英国的宪政传统。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「宪法-他-里-森」——把宪法放进「森」林般的条文里，让权力只能走在划好的路上 → 立宪主义","word":"constitutionalism"},"root":"拉丁 constituere「设立」= com-（共同、加强）+ statuere「放置」（stare「站立」的使动态）；constitutio「订立的条例」经古法语成 constitution，再加 -al 与 -ism。","sensesIntro":{"en":"Eight senses follow one device: a written limit placed on power, which then appears as a system, a body of practice, a movement, a habit, a field of study, a small-scale rule and finally its own excess.","cn":"八个义项围绕同一个装置展开：给权力加一道成文限度；这道限度再表现为制度、实践体系、运动、习惯、研究领域、小范围规则，最后是它自身的过度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a book pressed on a sceptre, cutting power to the size of a page.","cn":"核心意象：一本书压在权杖上，把权力压到一页纸的尺寸。"},"chain":["WRITTEN LIMIT","DIVIDED POWER","CONSTITUTIONAL ORDER","HISTORICAL MOVEMENT","RESPECT FOR FORM","LEGALISTIC EXCESS"],"branches":[{"senses":"01 · 08","en":"LIMIT AND EXCESS: the same written limit becomes a virtue when it binds power and a fault when it binds judgment.","cn":"限度与过度：同一条成文限度，用来约束权力是美德，用来捆住判断就成了毛病。"},{"senses":"02 · 07","en":"SCALES OF ORDER: a state and a club both use the device, which shows the principle is about office rather than about size.","cn":"秩序的尺度：国家与社团都用这套装置，说明原则关乎职位，而非规模。"},{"senses":"03 · 06","en":"PRACTICE AND STUDY: conventions enforced in court become the material that scholars later compare.","cn":"实践与研究：在法庭上生效的惯例，后来成为学者比较的材料。"},{"senses":"04","en":"THE CROWD: a doctrine becomes a movement when people demand that the limits be printed.","cn":"人群：当人们要求把限度印出来时，学说就变成运动。"},{"senses":"05","en":"THE HABIT: respect for form is tested on the day it would be easier to skip.","cn":"习惯：对形式的尊重，在「跳过更省事」的那天受检验。"}]},"affixes":{"intro":{"en":"The word is built from a Latin prefix, a Latin verb and two endings, and the same pieces recur across legal and everyday English.","cn":"这个词由一个拉丁前缀、一个拉丁动词和两个词尾构成，同样的构件在法律与日常英语中反复出现。"},"latinIntro":{"en":"Com- and statuere build constituere and constitutio; -al makes the adjective and -ism names the doctrine.","cn":"com- 与 statuere 构成 constituere 与 constitutio；-al 构成形容词，-ism 命名学说。"},"items":[{"word":"com-","structure":"com- (Latin prefix, 'together, thoroughly')","meaning":"together; completely","meaningCN":"共同；彻底","example":"The prefix binds the parts into one settled arrangement.","exampleCN":"这个前缀把各部分束成一个安顿好的安排。"},{"word":"statuere","structure":"statuere, statui, statutum (Latin verb, third conjugation)","meaning":"to set, station, establish","meaningCN":"放置；设立","example":"The verb is the causative of standing.","exampleCN":"这个动词是「站立」的使动形式。"},{"word":"constituere","structure":"com- + statuere","meaning":"to set up, establish","meaningCN":"设立；建立","example":"The assembly constituted a new council.","exampleCN":"大会设立了一个新委员会。"},{"word":"constitutio","structure":"constituere + -tio (action or result)","meaning":"a settling, an ordinance","meaningCN":"订立；条例","example":"The ordinance was read aloud in the square.","exampleCN":"这条法令在广场上被高声宣读。"},{"word":"constitution","structure":"constitutio through Old French","meaning":"fundamental rules; make-up","meaningCN":"根本规则；构成","example":"The constitution sets the terms of office.","exampleCN":"宪法规定任期。"},{"word":"constitutional","structure":"constitution + -al (relating to)","meaning":"relating to a constitution","meaningCN":"与宪法有关的","example":"The court reviewed the constitutional question.","exampleCN":"法院审查了这个宪法问题。"},{"word":"constitutionalism","structure":"constitutional + -ism (doctrine)","meaning":"the doctrine of limited government","meaningCN":"限权政府的学说","example":"Constitutionalism demands that limits be public.","exampleCN":"宪政要求限度公开。"},{"word":"constitutionalist","structure":"constitutional + -ist (person who follows)","meaning":"an advocate of constitutional rule","meaningCN":"宪政拥护者","example":"The constitutionalist opposed the emergency decree.","exampleCN":"这位宪政拥护者反对紧急法令。"},{"word":"-ism","structure":"-ism (English suffix, from Greek -ismos)","meaning":"a system or doctrine","meaningCN":"制度或学说","example":"The ending names beliefs rather than documents.","exampleCN":"这个词尾命名信念，而非文件。"}],"latinEntries":[{"word":"statuere","structure":"statuere, statui, statutum (verb, third conjugation)","meaning":"to set, establish","meaningCN":"放置；设立"},{"word":"constituere","structure":"constituere, constitui, constitutum (verb, third conjugation)","meaning":"to set up, establish","meaningCN":"设立；建立"},{"word":"constitutio","structure":"constitutio, constitutionis (f., third declension)","meaning":"a settling, ordinance","meaningCN":"订立；条例"},{"word":"statutum","structure":"statutum, statuti (n., second declension)","meaning":"a decree, statute","meaningCN":"法令；成文法"}],"derivatives":[{"word":"constitutional","pos":"adj.","zh":"宪法的；合宪的"},{"word":"constitutionalist","pos":"n.","zh":"宪政拥护者"},{"word":"constitutionality","pos":"n.","zh":"合宪性"},{"word":"unconstitutional","pos":"adj.","zh":"违宪的"},{"word":"constitution","pos":"n.","zh":"宪法；构成；体质"},{"word":"constitutive","pos":"adj.","zh":"构成性的；本质的"}]}},{"word":"legislature","ipa_uk":"/ˈleɡɪsleɪtʃə/","ipa_us":"/ˈleɡɪsleɪtʃər/","definition_zh":"立法机关；立法机构；（一国或一州的）议会","definition_en":"the body of people in a state who have the power to make, amend or repeal laws","core_image":"一张长桌旁坐满人，桌上摊着同一份待表决的条文，末页的签名栏还空着","scene":"长桌两侧的人逐条念着一份草案，最后一页的签名栏仍然空着。The state legislature passed the bill after a long night session.","sceneCN":"句中这个词指有权制定与修改法律的机构（第 1 个义项：由一批人组成、掌握立法权的机关）；句意为州立法机关经过一夜长会通过了该法案。图中可辨识物件：长桌、条文、空白签名栏、议席牌、表决灯。","pos":[{"tag":"n.","zh":"立法机关；立法机构（可数）"},{"tag":"n.","zh":"一国的立法部门（与行政、司法并列）"}],"collocations":[{"phrase":"state legislature","zh":"州立法机关"},{"phrase":"national legislature","zh":"国家立法机关"},{"phrase":"member of the legislature","zh":"立法机关成员"},{"phrase":"the legislature passed the bill","zh":"立法机关通过了该法案"},{"phrase":"dissolve the legislature","zh":"解散立法机关"},{"phrase":"legislature and executive","zh":"立法机关与行政机关"}],"forms":[{"label":"复数","form":"legislatures"},{"label":"形容词","form":"legislative"},{"label":"名词（立法；法规）","form":"legislation"},{"label":"名词（立法者）","form":"legislator"},{"label":"动词（立法）","form":"legislate"}],"derivatives":[{"word":"legislative","pos":"adj.","zh":"立法的；立法机关的"},{"word":"legislation","pos":"n.","zh":"立法；法规"},{"word":"legislator","pos":"n.","zh":"立法者；议员"},{"word":"legislate","pos":"v.","zh":"立法；制定法律"}],"senses":[{"no":"01","title":"Lawmaking institution","titleCN":"制定法律的机关","definition":"a body with legal authority to make, change or repeal statutes","definitionCN":"拥有制定、修改或废止成文法权的机构","example":"The state legislature passed the bill after a long night session.","exampleCN":"州立法机关经过一夜长会通过了该法案。","why":"The word is built on legislator plus -ure, so it names the body through the activity of its members: carrying a law.","whyCN":"这个词由 legislator 加 -ure 构成，因此它借成员的作为来命名机构：把法律搬运出去。"},{"no":"02","title":"A national assembly","titleCN":"国家层面的议会","definition":"the national lawmaking chamber of a country, often with a proper name","definitionCN":"一国的国家级立法议院，常有专名","example":"The national legislature meets for two sessions a year.","exampleCN":"国家立法机关每年开两次会。","why":"Once a body is named and housed, the general noun points to one particular chamber.","whyCN":"一旦机构有了名称与院址，这个普通名词就指向某一个特定议院。"},{"no":"03","title":"A subnational lawmaking body","titleCN":"地方层级的立法机关","definition":"the lawmaking body of a state, province or territory within a larger union","definitionCN":"联邦体制内州、省或地区的立法机构","example":"Education funding is decided by each provincial legislature.","exampleCN":"教育经费由各省立法机关决定。","why":"A federation distributes lawmaking downward, so the same noun appears at a lower level with a narrower jurisdiction.","whyCN":"联邦制把立法权向下分配，于是同一个名词出现在更低层级，管辖范围更窄。"},{"no":"04","title":"The legislative branch","titleCN":"三权中的立法部门","definition":"the branch of government that stands beside the executive and the judiciary","definitionCN":"与行政、司法并列的政府分支","example":"The constitution separates the legislature from the executive.","exampleCN":"宪法把立法部门与行政部门分开。","why":"Separation of powers turns an assembly into one of three branches, and the word takes on that structural meaning.","whyCN":"分权把议会变成三个分支之一，这个词就带上这一结构含义。"},{"no":"05","title":"The members collectively","titleCN":"全体议员","definition":"the assembled members regarded as a single group with a will of its own","definitionCN":"把全体成员当作一个有自身意志的群体","example":"The legislature rejected the amendment by a single vote.","exampleCN":"全体议员以一票之差否决了修正案。","why":"An institution acts through votes, so the noun slides from the chamber to the people inside it.","whyCN":"机构通过投票行动，于是这个名词从议院滑向里面的人。"},{"no":"06","title":"Colonial and territorial usage","titleCN":"殖民地与准州的历史用法","definition":"the lawmaking body of a colony or territory that had limited self-rule","definitionCN":"拥有有限自治权的殖民地或准州的立法机构","example":"The colonial legislature protested the new tax.","exampleCN":"殖民地立法机关抗议这项新税。","why":"English usage gave the noun to assemblies that could make local law but not sovereign law.","whyCN":"英语用法把这个名词给了能立地方法、却不能立主权法律的议会。"},{"no":"07","title":"A rule-setting body in any organisation","titleCN":"任何组织内部的规则制定机构","definition":"a committee or assembly that writes the binding rules of a club, union or company","definitionCN":"为社团、工会或公司制定约束性规则的委员会或大会","example":"The union's legislature meets to rewrite the bylaws.","exampleCN":"工会的规则制定机构开会改写章程。","why":"Making binding rules is the function, so any body doing it can borrow the name.","whyCN":"制定有约束力的规则是这项职能，任何做这件事的机构都能借用这个名称。"},{"no":"08","title":"Lawmaking authority itself","titleCN":"立法权本身（抽象）","definition":"the power to enact law, considered apart from the body that holds it","definitionCN":"与持有它的机构分开来看的立法权力","example":"The treaty left customs law to the domestic legislature.","exampleCN":"该条约把海关立法权留给本国立法机关。","why":"English often uses an institution's name for its power, so the word can name an authority rather than a room.","whyCN":"英语常用机构名代指其权力，因此这个词可以指一种权限，而非一间议事厅。"}],"etymology":{"intro":{"en":"Legislature is recorded from the 1670s as legislator plus -ure. The Latin base is legis lator 'proposer of a law', from lex 'law' and lator 'bearer', the latter tied to ferre 'to carry'.","cn":"legislature 自十七世纪七十年代见于记录，由 legislator 加 -ure 构成。其拉丁基础是 legis lator「提出法律的人」，来自 lex「法律」与 lator「搬运者」，后者与 ferre「搬运」相关。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, meant 'law, statute'. Its deeper origin is uncertain, and the often-suggested link to legere 'to gather, read' is a hypothesis rather than a demonstrated derivation.","cn":"lex（属格 legis）意为「法律、法令」。其更深来源不确定，常被提出的与 legere「收集、读」的联系只是假说，并非已证实的派生。"},{"era":"LATIN FERRE","en":"Ferre 'to carry' supplied the participle latus 'borne', which was used as its past participle and also appears in translate and relate.","cn":"ferre「搬运」提供分词 latus「被搬运的」，它被当作过去分词使用，也出现在 translate 与 relate 中。"},{"era":"LEGIS LATOR","en":"The phrase legis lator meant 'one who brings or proposes a law'; lator is the agent noun of the carried form, so a lawmaker is literally a law-bearer.","cn":"短语 legis lator 意为「把法律带来或提出的人」；lator 是「搬运」这一动作的施事名词，因此立法者字面上就是「搬运法律的人」。"},{"era":"ENGLISH LEGISLATOR","en":"English legislator is recorded about 1600, and in American usage it came to mean a member of a state or territorial body.","cn":"英语 legislator 约在 1600 年见于记录；在美式用法中，它指州或准州立法机关的成员。"},{"era":"LEGISLATURE 1670","en":"The noun legislature was formed with the suffix -ure, which names an office or a result, and was applied to the body rather than to one member.","cn":"名词 legislature 以 -ure 词尾构成，该词尾命名职务或结果，并用在机构而非单个成员上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain for the pre-Latin origin of lex; the link to legere is only a hypothesis, and the date 1670s is approximate.","cn":"来源不确定之处是 lex 在拉丁语之前的来源；与 legere 的联系仅为假说，1670 年代也是约数。"}]},"similar":{"note":{"en":"Group one holds words built on lex 'law' and on the look-alike legere 'to read or choose', which are constantly confused; group two holds bodies that also deliberate and decide.","cn":"第一组包括由 lex「法律」构成的词，以及形似而实出 legere「读、选」的词，二者极易混淆；第二组是同样议事并作决定的机构。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legislation","ipa":"/ˌleɡɪsˈleɪʃən/","tag":"the laws made","definition":"The statutes produced by a legislature, or the act of making them; it names output, not the body.","definitionCN":"指立法机关产出的法规，或立法这一行为；命名的是成果，不是机构。"},{"word":"legislative","ipa":"/ˈleɡɪsleɪtɪv/","tag":"the adjective","definition":"Relating to lawmaking or to a legislature; it describes a power or a session, not an institution.","definitionCN":"指与立法或立法机关有关的；它描述一种权力或一场会议，而非机构。"},{"word":"legislator","ipa":"/ˈleɡɪsleɪtə/","tag":"one member","definition":"A single person who helps make laws; the suffix -or marks the doer where -ure marks the body.","definitionCN":"指参与制定法律的单个人；词尾 -or 标记施事者，而 -ure 标记机构。"},{"word":"legible","ipa":"/ˈledʒəbəl/","tag":"different root","definition":"Able to be read, from legere 'to read'; it looks like the law family but has nothing to do with lex.","definitionCN":"指可读的，出自 legere「读」；它看起来像法律词族，但与 lex 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"parliament","ipa":"/ˈpɑːləmənt/","tag":"speaking assembly","definition":"A national legislature, especially in a system where the executive is drawn from it; the name comes from speaking, not from law.","definitionCN":"指国家立法机关，尤其在行政由其中产生的体制里；其名称来自「说话」，而非「法律」。"},{"word":"congress","ipa":"/ˈkɒŋɡres/","tag":"coming together","definition":"A national legislature, especially the American one; its name comes from walking together, not from law.","definitionCN":"指国家立法机关，尤指美国国会；其名称来自「走到一起」，而非「法律」。"},{"word":"assembly","ipa":"/əˈsembli/","tag":"general gathering","definition":"Any gathering of people for a purpose, including a lawmaking one; it is the broad word that legislature narrows.","definitionCN":"指为某种目的聚集的人，包括立法性集会；它是 legislature 所收窄的宽泛词。"},{"word":"council","ipa":"/ˈkaʊnsəl/","tag":"advising body","definition":"A body that advises or administers rather than makes statute law; it deliberates, but its decisions are usually not statutes.","definitionCN":"指提供建议或进行行政管理的机构，而非制定成文法的机构；它也议事，但决定通常不是法规。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin phrase, the real family of law words and the real political phrases.","cn":"正常联想：真实的拉丁短语、真实的法字词族与真实的政治搭配。"},"normal":[{"en":"legis 'of law' plus lator 'bearer': the body where laws are carried through.","cn":"legis「法律的」加 lator「搬运者」：法律在那里被搬运通过的机构。"},{"en":"The family runs legislate, legislation, legislative, legislator and legislature.","cn":"同族词包括 legislate、legislation、legislative、legislator 与 legislature。"},{"en":"Fixed phrases mark the institution: state legislature, national legislature, member of the legislature.","cn":"固定搭配标出机构用法：州立法机关、国家立法机关、立法机关成员。"},{"en":"The -ure ending marks a body or office, as in judicature and prefecture.","cn":"词尾 -ure 标记机构或职务，如 judicature 与 prefecture。"},{"en":"The law root lex is not the reading root legere: elect and legible belong elsewhere.","cn":"法律词根 lex 不是「读」的词根 legere：elect 与 legible 属于另一支。"}],"abstract":[{"en":"Picture a long table where a single sheet travels from hand to hand until every hand has touched it.","cn":"想象一张长桌，一张纸从一只手传到另一只手，直到每只手都碰过它。"},{"en":"Picture three doors in one wall, and only one of them opens onto a printing press.","cn":"想象一面墙上有三扇门，只有一扇通向印刷机。"},{"en":"Picture a rulebook that is rewritten by the players while the game is running.","cn":"想象一本规则书由球员在比赛进行时改写。"}]},"examples":[{"en":"The legislature voted to raise the minimum age for driving.","cn":"立法机关投票提高了驾驶的最低年龄。"},{"en":"A territorial legislature governed the region before statehood.","cn":"建州之前，这个地区由准州立法机关治理。"},{"en":"The governor can veto bills passed by the legislature.","cn":"州长可以否决立法机关通过的法案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「 legis-累-斯雷-车」——一群「累」在长桌旁的人把一条条法令「斯雷」地推上车送出去 → 立法机关","word":"legislature"},"root":"拉丁 legis lator「法律的提出者」= lex（属格 legis）「法律」+ lator「搬运者」（与 ferre「搬运」相关）；英语加 -ure 构成机构名。","sensesIntro":{"en":"Eight senses follow one room: a body carries a bill into law, then is seen as a national chamber, a local chamber, a branch, a group of people, a colonial body, any rule-setter and finally the bare authority to legislate.","cn":"八个义项围绕同一间议事厅展开：一个机构把草案搬运成法律；随后它被看作国家议院、地方议院、政府分支、一群议员、殖民地机构、任何规则制定者，最后只剩立法权限本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table with one sheet of clauses moving from hand to hand.","cn":"核心意象：一张长桌，一页条文从一只手传到另一只手。"},"chain":["LAW BEARING","NATIONAL CHAMBER","LOCAL CHAMBER","BRANCH OF POWER","MEMBERS AS ONE","RULE-SETTING BODY"],"branches":[{"senses":"01 · 08","en":"BODY AND POWER: the room and its authority are named by the same word, one concrete and one abstract.","cn":"机构与权限：议事厅与其权限由同一个词命名，一具体一抽象。"},{"senses":"02 · 03","en":"TWO LEVELS: a federation repeats the same chamber at national and provincial scale.","cn":"两个层级：联邦制在国家与省级重复同一个议院。"},{"senses":"04 · 05","en":"STRUCTURE AND PERSONS: a branch of government acts only through the votes of the people inside it.","cn":"结构与人员：政府分支只能通过里面那些人的投票来行动。"},{"senses":"06","en":"THE COLONY: limited self-rule produces a chamber that can make local law but not sovereign law.","cn":"殖民地：有限的自治产生一个能立地方法、不能立主权法律的议院。"},{"senses":"07","en":"THE BORROWED NAME: any body that writes binding rules can take the title.","cn":"借来的名称：任何制定约束性规则的机构都能取用这个称号。"}]},"affixes":{"intro":{"en":"Legislature joins a Latin law-noun, a Latin agent noun and an English suffix of office, so its family can be read piece by piece.","cn":"legislature 连接一个拉丁法律名词、一个拉丁施事名词和一个表职务的英语词尾，因此其词族可以逐块读出。"},"latinIntro":{"en":"Lex supplies legal and legislation; lator and its base ferre supply translate, relate and oblate; -ure marks an office or result.","cn":"lex 提供 legal 与 legislation；lator 及其基础 ferre 提供 translate、relate 与 oblate；-ure 标记职务或结果。"},"items":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令","example":"The root names the thing the body produces.","exampleCN":"这个词根命名机构所产出的东西。"},{"word":"lator","structure":"lator, latoris (m., third declension)","meaning":"bearer, proposer","meaningCN":"搬运者；提出者","example":"The agent noun names the person who brings the law.","exampleCN":"这个施事名词命名把法律带来的人。"},{"word":"legislator","structure":"legis + lator","meaning":"proposer of a law","meaningCN":"法律的提出者","example":"The legislator read the clause aloud.","exampleCN":"议员高声念出这一条。"},{"word":"legislate","structure":"legislator + -ate (to act)","meaning":"to make laws","meaningCN":"制定法律","example":"The chamber legislates for the whole province.","exampleCN":"该议院为全省立法。"},{"word":"legislation","structure":"legislate + -ion (action or result)","meaning":"the making of laws; the laws made","meaningCN":"立法；法规","example":"The legislation took effect in spring.","exampleCN":"这项法规在春季生效。"},{"word":"legislative","structure":"legislate + -ive (tending to)","meaning":"relating to lawmaking","meaningCN":"与立法有关的","example":"The committee holds legislative power.","exampleCN":"该委员会拥有立法权。"},{"word":"legislature","structure":"legislator + -ure (office or result)","meaning":"the body that makes laws","meaningCN":"制定法律的机构","example":"The legislature adjourned at midnight.","exampleCN":"立法机关午夜休会。"},{"word":"-ure","structure":"-ure (English suffix, from Latin -ura)","meaning":"office, body or result","meaningCN":"职务、机构或结果","example":"The same ending appears in judicature.","exampleCN":"同一词尾出现在 judicature 中。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The ending marks the person rather than the body.","exampleCN":"这个词尾标记人，而非机构。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"lator","structure":"lator, latoris (m., third declension)","meaning":"bearer, proposer","meaningCN":"搬运者；提出者"},{"word":"latus","structure":"latus, lata, latum (past participle of ferre)","meaning":"borne, carried","meaningCN":"被搬运的"},{"word":"legislator","structure":"legis + lator (Latin compound noun)","meaning":"proposer of a law","meaningCN":"法律的提出者"}],"derivatives":[{"word":"legislative","pos":"adj.","zh":"立法的；立法机关的"},{"word":"legislation","pos":"n.","zh":"立法；法规"},{"word":"legislator","pos":"n.","zh":"立法者；议员"},{"word":"legislate","pos":"v.","zh":"立法"},{"word":"legislatorial","pos":"adj.","zh":"立法者的；立法机关的"}]}},{"word":"legislator","ipa_uk":"/ˈleɡɪsleɪtə/","ipa_us":"/ˈleɡɪsleɪtər/","definition_zh":"立法者；议员；（州、准州或殖民地的）立法机关成员","definition_en":"a person who takes part in making laws, especially a member of a legislature","core_image":"一个人站在长桌前，手里举着一页写满条文的纸，把它递向表决的灯","scene":"长桌前一个人举起一页条文，向身后的同僚示意可以表决了。The legislator spent the morning explaining the bill to constituents.","sceneCN":"句中这个词指参与制定法律的个人，尤指立法机关成员（第 1 个义项：在立法机关中参与立法的成员）；句意为这位议员花了一上午向选民解释该法案。图中可辨识物件：长桌、条文纸页、表决灯、选区地图、记事本。","pos":[{"tag":"n.","zh":"立法者；议员（可数）"},{"tag":"n.","zh":"（美式）州、准州或殖民地立法机关成员"}],"collocations":[{"phrase":"state legislator","zh":"州议员"},{"phrase":"a senior legislator","zh":"资深议员"},{"phrase":"legislator for the district","zh":"该选区的议员"},{"phrase":"legislators and judges","zh":"立法者与法官"},{"phrase":"the legislator's duty","zh":"议员的职责"},{"phrase":"elected legislator","zh":"当选议员"}],"forms":[{"label":"复数","form":"legislators"},{"label":"阴性形式（较少用）","form":"legislatrix"},{"label":"形容词","form":"legislatorial"},{"label":"名词（机构）","form":"legislature"},{"label":"动词（立法）","form":"legislate"}],"derivatives":[{"word":"legislature","pos":"n.","zh":"立法机关"},{"word":"legislative","pos":"adj.","zh":"立法的"},{"word":"legislation","pos":"n.","zh":"立法；法规"},{"word":"legislate","pos":"v.","zh":"制定法律"},{"word":"legislatorial","pos":"adj.","zh":"立法者的"},{"word":"legislatorship","pos":"n.","zh":"议员身份"}],"senses":[{"no":"01","title":"A member of a legislature","titleCN":"立法机关的成员","definition":"a person who sits in a lawmaking body and votes on statutes","definitionCN":"在立法机关中任职并对法规投票的人","example":"The legislator spent the morning explaining the bill to constituents.","exampleCN":"这位议员花了一上午向选民解释该法案。","why":"The word is Latin legis lator, 'one who brings a law', so its first sense is simply the person who carries a bill through a chamber.","whyCN":"这个词是拉丁 legis lator「把法律带来的人」，因此第一义就是那个把草案在议院里推过去的人。"},{"no":"02","title":"One who drafts or proposes a law","titleCN":"起草或提出法律的人","definition":"a person who frames the text of a proposed law rather than merely voting on it","definitionCN":"拟定法律草案文本、而不只是投票的人","example":"As a legislator she drafted the clause on water rights.","exampleCN":"作为立法者，她起草了关于水权的条款。","why":"The Latin phrase stresses proposing rather than sitting, so the word keeps a drafting sense alongside the parliamentary one.","whyCN":"拉丁短语强调的是「提出」而非「坐席」，因此这个词在议会义之外还保留起草义。"},{"no":"03","title":"A state or provincial lawmaker","titleCN":"州或省级议员","definition":"in American usage, a member of a state, territorial or colonial legislature","definitionCN":"在美式用法中，指州、准州或殖民地立法机关的成员","example":"Every state legislator faces re-election within two years.","exampleCN":"每位州议员都要在两年内面对改选。","why":"American usage narrowed the word to the subnational chamber, where most lawmaking on local matters happens.","whyCN":"美式用法把这个词收窄到地方议院，因为关于本地事务的立法多在那里发生。"},{"no":"04","title":"An ancient lawgiver","titleCN":"古代的立法者","definition":"a historical figure credited with giving a people its code of law","definitionCN":"被认为为一个民族立下法典的历史人物","example":"Solon is remembered as a legislator of Athens.","exampleCN":"梭伦被铭记为雅典的立法者。","why":"The word is older than parliaments, so it naturally names the single founder of a code.","whyCN":"这个词比议会更老，因此它自然可以指一个法典的单一创立者。"},{"no":"05","title":"A rule-setter inside an organisation","titleCN":"组织内部的规则制定者","definition":"a person who writes the binding rules of a club, union or company","definitionCN":"为社团、工会或公司编写有约束力规则的人","example":"The union's constitution makes each delegate a legislator for two years.","exampleCN":"工会章程使每位代表在两年内成为规则制定者。","why":"Writing rules that bind others is the core function, so the title transfers to any body with rule-making power.","whyCN":"写出约束他人的规则是核心职能，因此这个称号可转移到任何拥有立规权的团体。"},{"no":"06","title":"An arbiter of taste or fashion","titleCN":"品味或时尚的裁定者","definition":"a figurative use for someone whose choices set the standard others copy","definitionCN":"比喻用法，指其选择为他人树立标准的人","example":"The designer was called a legislator of style.","exampleCN":"这位设计师被称为风格的立法者。","why":"A lawgiver fixes what is allowed; a taste-maker fixes what is admired, and the metaphor borrows that authority.","whyCN":"立法者定下什么被允许；品味制定者定下什么被赞赏，这个比喻借用了那种权威。"},{"no":"07","title":"One who codifies a profession's rules","titleCN":"为行业编定规则的人","definition":"a person who writes a professional code of conduct or standards","definitionCN":"编写行业行为准则或标准的人","example":"The physicians elected a legislator for their ethics code.","exampleCN":"医生们推举一人为他们编写伦理准则。","why":"Professional codes are statutes in miniature, so their authors take a name from public law.","whyCN":"行业准则像是缩小的法规，因此其作者借用了公法里的名称。"},{"no":"08","title":"A representative speaking for a district","titleCN":"代表选区发声的议员","definition":"a lawmaker regarded as the voice of the people who elected him or her","definitionCN":"被视为其选民代言人的立法者","example":"Voters expect their legislator to answer letters.","exampleCN":"选民期望自己的议员回复来信。","why":"Election turns a lawmaker into a delegate, so the word also carries the duty of speaking for others.","whyCN":"选举把立法者变成代表，因此这个词也带着替他人发声的职责。"}],"etymology":{"intro":{"en":"Legislator is English from about 1600, taken from Latin legis lator 'proposer of a law'. Lex means 'law' and lator means 'bearer', the latter built on latus, the carried form of ferre 'to carry'.","cn":"legislator 约在 1600 年进入英语，取自拉丁 legis lator「法律的提出者」。lex 意为「法律」，lator 意为「搬运者」，后者由 ferre「搬运」的被动态 latus 构成。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, meant 'law, statute'. Its deeper origin is unknown, and the link sometimes proposed to legere 'to read, gather' is a hypothesis, not a proof.","cn":"lex（属格 legis）意为「法律、法令」。其更深来源不明，有时被提出的与 legere「读、收集」的联系只是假说，不是证明。"},{"era":"LATIN LATUS","en":"Ferre 'to carry' had the participle latus 'borne', which served as its past participle and also lies behind translate and relate.","cn":"ferre「搬运」的分词 latus「被搬运的」，被当作它的过去分词使用，也是 translate 与 relate 的来源。"},{"era":"LEGIS LATOR","en":"The Latin phrase named the person who brought a proposed law before the assembly; lator is the agent noun of the carrying verb.","cn":"这个拉丁短语命名把法律草案带到大会前的人；lator 是「搬运」动词的施事名词。"},{"era":"ENGLISH 1600","en":"English legislator appears about 1600 with the general sense of lawgiver; the feminine legislatrix is recorded from the 1670s.","cn":"英语 legislator 约在 1600 年出现，泛指立法者；阴性形式 legislatrix 自十七世纪七十年代见于记录。"},{"era":"AMERICAN NARROWING","en":"In the United States the noun settled on a member of a state, territorial or colonial legislature, a sense still dominant there.","cn":"在美国，这个名词固定指州、准州或殖民地立法机关的成员，这一义项至今在美式用法中占主导。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain for the pre-Latin origin of lex; the date 1600 is approximate.","cn":"来源不确定之处是 lex 在拉丁语之前的来源；1600 年是约数。"}]},"similar":{"note":{"en":"Group one holds the law-family nouns and the look-alike reading-family words; group two holds people who also make or speak for laws.","cn":"第一组是法律词族的名词，以及形似的「读」词族词；第二组是同样立法或代言的其他人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legislature","ipa":"/ˈleɡɪsleɪtʃə/","tag":"the body","definition":"The institution, not one member; the -ure ending marks an office or body.","definitionCN":"指机构，不是单个成员；-ure 词尾标记职务或机构。"},{"word":"legislation","ipa":"/ˌleɡɪsˈleɪʃən/","tag":"the output","definition":"The laws produced or the act of producing them; it names a result, not a person.","definitionCN":"指产出的法规或立法行为；命名结果，不指人。"},{"word":"legislative","ipa":"/ˈleɡɪsleɪtɪv/","tag":"the adjective","definition":"Relating to lawmaking; it describes a power or session rather than a person.","definitionCN":"指与立法有关的；描述权力或会期，而非人。"},{"word":"legible","ipa":"/ˈledʒəbəl/","tag":"different root","definition":"Readable, from legere 'to read'; the shared letters do not make it a relative of lex.","definitionCN":"指可读的，出自 legere「读」；相同的字母并不使它成为 lex 的同族。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lawmaker","ipa":"/ˈlɔːmeɪkə/","tag":"plain synonym","definition":"The everyday word for a person who makes laws; legislator is its formal equivalent.","definitionCN":"指制定法律者的日常说法；legislator 是其正式对应词。"},{"word":"lawgiver","ipa":"/ˈlɔːɡɪvə/","tag":"founder of a code","definition":"A person who gives a whole code to a people, like Solon; it suits the historical sense better than the parliamentary one.","definitionCN":"指像梭伦那样把一个完整法典交给一个民族的人；更贴合历史义而非议会义。"},{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","tag":"speaks for a district","definition":"An elected person who acts for a constituency; the emphasis is on speaking for others, not on drafting text.","definitionCN":"指为选区行事的民选者；强调替他人发声，而非撰写条文。"},{"word":"parliamentarian","ipa":"/ˌpɑːləmenˈteəriən/","tag":"expert in procedure","definition":"A member skilled in parliamentary rules; the word stresses procedural knowledge rather than lawmaking itself.","definitionCN":"指精通议会规则的人；这个词强调程序知识，而非立法本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin compound, the real family and the real institutional phrases.","cn":"正常联想：真实的拉丁复合词、真实词族与真实的机构搭配。"},"normal":[{"en":"legis 'of law' plus lator 'bearer': the person who carries a bill.","cn":"legis「法律的」加 lator「搬运者」：把草案搬过去的那个人。"},{"en":"The family runs legislate, legislation, legislative, legislature and legislator.","cn":"同族词包括 legislate、legislation、legislative、legislature 与 legislator。"},{"en":"Fixed phrases mark the role: state legislator, elected legislator, the legislator's duty.","cn":"固定搭配标出角色：州议员、当选议员、议员的职责。"},{"en":"The -or ending marks the doer; the -ure ending marks the body.","cn":"词尾 -or 标记施事者，-ure 标记机构。"},{"en":"Latin lex is the law root; legere, the reading root, is a different family.","cn":"拉丁 lex 是法律词根；legere 是「读」的词根，属另一词族。"}],"abstract":[{"en":"Picture one hand raising a page so that a whole room can see it.","cn":"想象一只手举起一页纸，让整间屋子都看见。"},{"en":"Picture a single brick laid into a wall that will outlast the mason.","cn":"想象一块砖砌进一堵比砌砖人活得更久的墙。"},{"en":"Picture a pen that signs for people who never meet the writer.","cn":"想象一支笔替从未见过作者的人签名。"}]},"examples":[{"en":"The legislator introduced a bill on rural clinics.","cn":"这位议员提出了一项关于乡村诊所的法案。"},{"en":"A territorial legislator could not vote on national tariffs.","cn":"准州议员无权对国家关税投票。"},{"en":"Reformers praised her as a legislator who read every amendment.","cn":"改革者称赞她是一位逐条读修正案的立法者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「 legis-累-斯雷-特」——一位特别「累」的人，把一条条「斯雷」的法令搬进议场 → 立法者","word":"legislator"},"root":"拉丁 legis lator「法律的提出者」= lex（属格 legis）「法律」+ lator「搬运者」（ferre「搬运」的被动态 latus）；lex 更深来源不明。","sensesIntro":{"en":"Eight senses follow one person: a member voting in a chamber, a drafter of text, a state member, an ancient founder, a small-scale rule-setter, an arbiter of taste, a writer of professional codes and a voice for a district.","cn":"八个义项围绕同一个人展开：在议院投票的成员、条文的起草者、州议员、古代立法者、小范围规则制定者、品味裁定者、行业准则编写者、选区代言人。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand raising a page of clauses before a room.","cn":"核心意象：一只手在满屋人面前举起一页条文。"},"chain":["LAW BEARER","BILL DRAFTER","STATE MEMBER","ANCIENT LAWGIVER","RULE SETTER","VOICE FOR A DISTRICT"],"branches":[{"senses":"01 · 08","en":"SEAT AND VOICE: sitting in the chamber and speaking for a district are two halves of one mandate.","cn":"席位与声音：坐在议院里与替选区发声，是同一项授权的两半。"},{"senses":"02 · 07","en":"WRITING RULES: drafting a statute and codifying a profession both mean putting binding words on paper.","cn":"写下规则：起草法规与编定行业准则，都是把有约束力的话写到纸上。"},{"senses":"03","en":"THE LOWER CHAMBER: American usage keeps the word close to local lawmaking.","cn":"下级议院：美式用法让这个词贴近地方立法。"},{"senses":"04","en":"THE FOUNDER: before parliaments, the word named the single giver of a code.","cn":"创立者：在议会之前，这个词指单独给出法典的人。"},{"senses":"05 · 06","en":"BORROWED AUTHORITY: a club or a fashion world can borrow the lawgiver's authority for its own rules.","cn":"借来的权威：社团或时尚界都能借用立法者的权威来立自己的规矩。"}]},"affixes":{"intro":{"en":"The word is a Latin compound wrapped in an English agent ending, so each piece has its own English offspring.","cn":"这个词是一个外裹英语施事词尾的拉丁复合词，每一部分都有自己的英语后代。"},"latinIntro":{"en":"Lex gives legal and legislation; the carrying verb gives lator, translate and relate; -or marks the person.","cn":"lex 提供 legal 与 legislation；搬运动词提供 lator、translate 与 relate；-or 标记人。"},"items":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令","example":"The root names what the person carries.","exampleCN":"这个词根命名人所搬运之物。"},{"word":"lator","structure":"lator, latoris (m., third declension)","meaning":"bearer, proposer","meaningCN":"搬运者；提出者","example":"The noun names the carrier of the bill.","exampleCN":"这个名词命名草案的搬运者。"},{"word":"legislator","structure":"legis + lator","meaning":"proposer of a law","meaningCN":"法律的提出者","example":"The legislator rose to speak.","exampleCN":"这位议员起身发言。"},{"word":"legislate","structure":"legislator + -ate (to act)","meaning":"to make laws","meaningCN":"立法","example":"The chamber can legislate on health.","exampleCN":"该议院可就卫生立法。"},{"word":"legislation","structure":"legislate + -ion (action or result)","meaning":"lawmaking; the laws made","meaningCN":"立法；法规","example":"The legislation passed by one vote.","exampleCN":"这项法规以一票之差通过。"},{"word":"legislative","structure":"legislate + -ive (tending to)","meaning":"relating to lawmaking","meaningCN":"与立法有关的","example":"The legislative session opens in January.","exampleCN":"立法会期在一月开幕。"},{"word":"legislature","structure":"legislator + -ure (office or body)","meaning":"the lawmaking body","meaningCN":"立法机关","example":"The legislature has two houses.","exampleCN":"该立法机关有两院。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who acts","meaningCN":"施事者","example":"The ending marks a person, not a body.","exampleCN":"这个词尾标记人，不标记机构。"},{"word":"-ial","structure":"-ial (English adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The adjective legislatorial follows the same pattern.","exampleCN":"形容词 legislatorial 遵循同样的模式。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"lator","structure":"lator, latoris (m., third declension)","meaning":"bearer, proposer","meaningCN":"搬运者；提出者"},{"word":"latus","structure":"latus, lata, latum (past participle of ferre)","meaning":"borne, carried","meaningCN":"被搬运的"},{"word":"legislator","structure":"legis + lator (Latin compound)","meaning":"proposer of a law","meaningCN":"法律的提出者"}],"derivatives":[{"word":"legislature","pos":"n.","zh":"立法机关"},{"word":"legislative","pos":"adj.","zh":"立法的"},{"word":"legislation","pos":"n.","zh":"立法；法规"},{"word":"legislate","pos":"v.","zh":"立法"},{"word":"legislatorial","pos":"adj.","zh":"立法者的"},{"word":"legislatorship","pos":"n.","zh":"议员身份"}]}},{"word":"parliament","ipa_uk":"/ˈpɑːləmənt/","ipa_us":"/ˈpɑːrləmənt/","definition_zh":"议会；国会；（英国的）议会；（一届全国议会的）任期","definition_en":"the national lawmaking assembly of a country, especially one in which the government is drawn from its members","core_image":"一间圆形大厅里两排长凳相对而坐，中间的地毯上放着一份待辩的文件","scene":"圆形大厅里两排长凳相对，中间的地毯上摊着一份文件。Parliament debated the bill until midnight.","sceneCN":"句中这个词指一国的国家立法议会，尤其指政府由议员产生的体制（第 1 个义项：由民选代表组成、掌握立法权的国家议会）；句意为议会辩论该法案直到午夜。图中可辨识物件：两排长凳、中央地毯、文件、议长席位、表决通道。","pos":[{"tag":"n.","zh":"议会；国会（可数，常大写）"},{"tag":"n.","zh":"一届议会的任期；议会会议时期"}],"collocations":[{"phrase":"member of parliament","zh":"议会议员"},{"phrase":"dissolve parliament","zh":"解散议会"},{"phrase":"parliament passed the act","zh":"议会通过了该法案"},{"phrase":"the European Parliament","zh":"欧洲议会"},{"phrase":"a sitting of parliament","zh":"议会的一次会议"},{"phrase":"parliament and government","zh":"议会与政府"}],"forms":[{"label":"复数","form":"parliaments"},{"label":"形容词","form":"parliamentary"},{"label":"名词（议事规则专家）","form":"parliamentarian"},{"label":"名词（议员，英式）","form":"Member of Parliament"},{"label":"相关动词（谈判）","form":"parley"}],"derivatives":[{"word":"parliamentary","pos":"adj.","zh":"议会的；议会程序的"},{"word":"parliamentarian","pos":"n.","zh":"议员；议事规则专家"},{"word":"parley","pos":"n./v.","zh":"商谈；谈判"},{"word":"parlour","pos":"n.","zh":"客厅；会客室"},{"word":"parliamentarianism","pos":"n.","zh":"议会制主张"}],"senses":[{"no":"01","title":"A national lawmaking assembly","titleCN":"国家立法议会","definition":"the supreme lawmaking body of a state, especially where the executive answers to it","definitionCN":"一国的最高立法机构，尤指行政须向它负责的体制","example":"Parliament debated the bill until midnight.","exampleCN":"议会辩论该法案直到午夜。","why":"The word first meant a talking together, and the national assembly is the place where the talking decides law.","whyCN":"这个词最初指「一起说话」，而国家议会就是说话决定法律的地方。"},{"no":"02","title":"The building","titleCN":"议会大厦","definition":"the building or chamber where the assembly meets","definitionCN":"议会开会所在的建筑或议事厅","example":"A crowd gathered outside parliament.","exampleCN":"一群人聚集在议会大厦外。","why":"By metonymy the place takes the name of the body that meets in it.","whyCN":"借代作用使地点取得了在其中开会之机构的名字。"},{"no":"03","title":"The members collectively","titleCN":"全体议员","definition":"the assembled members considered as one actor","definitionCN":"把全体议员视为一个行动者","example":"Parliament was divided on the question.","exampleCN":"议会在这个问题上意见分裂。","why":"A body acts through votes, so the name passes from the institution to the people in it.","whyCN":"机构通过投票行动，于是名称从制度转到里面的人。"},{"no":"04","title":"A term or session","titleCN":"一届任期或会期","definition":"the period between one general election and the next, or a single session","definitionCN":"两次大选之间的一段时期，或一次会期","example":"The law was passed in the last parliament.","exampleCN":"这项法律在上一届议会任期内通过。","why":"Because the assembly is dissolved and reconstituted, the word also counts the periods of its life.","whyCN":"由于议会被解散又重新组成，这个词也用来数它生命的周期。"},{"no":"05","title":"A medieval council","titleCN":"中世纪由君主召集的会议","definition":"a conference of nobles and clergy summoned by a monarch to advise and consent","definitionCN":"由君主召集、由贵族与教士提供建议并同意的会议","example":"The medieval parliament began as a royal council.","exampleCN":"中世纪的议会起初是王室会议。","why":"Before it made law, the assembly was a speaking-together called by the king, and that is the oldest sense.","whyCN":"在制定法律之前，这个集会是由国王召集的「一起说话」，那是最老的义项。"},{"no":"06","title":"A regional or supranational parliament","titleCN":"地区或超国家议会","definition":"a lawmaking or deliberative assembly below or above the national level","definitionCN":"低于或高于国家层级的立法或议事议会","example":"The Scottish Parliament sits in Edinburgh.","exampleCN":"苏格兰议会设在爱丁堡。","why":"Once the model exists, it can be copied at any level, from a province to a continent.","whyCN":"一旦有了这个模式，它就能被复制到任何层级，从一省到一洲。"},{"no":"07","title":"Any deliberative assembly","titleCN":"任何议事性集会","definition":"an extended use for a meeting that argues out a decision","definitionCN":"引申用法，指通过争论作出决定的会议","example":"The students held a parliament on the library steps.","exampleCN":"学生们在图书馆台阶上开了一场议事会。","why":"Talking toward a decision is the original action, so the label travels to any group that does it.","whyCN":"为了决定而说话是原本的动作，因此这个标签能转到任何这样做的群体。"},{"no":"08","title":"A literary gathering","titleCN":"文学中的群鸟议事（典故）","definition":"the title word of medieval poems in which birds or beasts hold a council","definitionCN":"中世纪诗题中的用词，写群鸟或群兽开会","example":"Chaucer's poem is known as the Parliament of Fowls.","exampleCN":"乔叟那首诗被称为《百鸟议会》。","why":"The poem takes the assembly's name and applies it to birds, which is the word's most playful reach.","whyCN":"这首诗借用了议会的名字，把它用在鸟身上，是这个词汇最俏皮的延伸。"}],"etymology":{"intro":{"en":"Parliament comes from Old French parlement, first 'a speaking, talk' and then 'a conference'. The verb parler 'to speak' goes back through Late Latin parabolare to parabola 'speech, comparison', from Greek parabole.","cn":"parliament 来自古法语 parlement，最初意为「说话、谈话」，后指「会议」。动词 parler「说话」经晚期拉丁 parabolare 上溯到 parabola「言语、比较」，再上溯到希腊语 parabole。"},"items":[{"era":"GREEK PARABOLE","en":"Parabole meant a placing beside, hence a comparison and a story used as a comparison. It passed into Latin as parabola.","cn":"parabole 意为「放在旁边」，因此指比较，也指用作比较的故事。它进入拉丁语作 parabola。"},{"era":"LATE LATIN PARABOLARE","en":"The verb parabolare 'to speak, talk' grew out of parabola in late and vulgar Latin, and from it came French parler.","cn":"动词 parabolare「说话、谈话」在晚期与通俗拉丁语中由 parabola 长出，法语 parler 即由此而来。"},{"era":"OLD FRENCH PARLEMENT","en":"Parlement named a speaking or a conference before it named an institution; the Anglo-Latin form parliamentum is recorded from the early thirteenth century.","cn":"parlement 先指说话或会谈，后指机构；其盎格鲁拉丁形式 parliamentum 自十三世纪早期见于记录。"},{"era":"ENGLISH 1300","en":"English parliament is recorded about 1300 for a formal conference, and by the mid-fourteenth century for the representative assembly of England.","cn":"英语 parliament 约在 1300 年指正式会议，到十四世纪中期指英格兰的代表性议会。"},{"era":"SPELLING SHIFT","en":"The spelling was altered about 1400 to match Medieval Latin parliamentum, which is why the word has an i that the French form lacks.","cn":"拼写约在 1400 年按中世纪拉丁 parliamentum 改动，这就是为什么这个词有一个法语形式所无的 i。"},{"era":"APPROXIMATE DATES","en":"The chain from Greek parabole is clear. Only the earliest citation of each English sense is approximate, so no source is marked uncertain.","cn":"从希腊 parabole 以来的链条清楚。只有各英语义项的最早书证是约数，因此没有需要标为来源不确定的部分。"}]},"similar":{"note":{"en":"Group one holds words sharing the speaking root behind parliament; group two holds other assemblies that decide by debate.","cn":"第一组是同出 parliament 背后「说话」词根的词；第二组是同样以辩论作决定的其他集会。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parley","ipa":"/ˈpɑːli/","tag":"same speaking root","definition":"A conference with an enemy, from the same French verb; it is a talk, not an institution.","definitionCN":"指与敌方的会谈，出自同一个法语动词；它是一次谈话，不是机构。"},{"word":"parlour","ipa":"/ˈpɑːlə/","tag":"same root, a room","definition":"A sitting room for conversation; the old sense of a room set apart for talking survives here.","definitionCN":"指供谈话的起居室；「专门用于说话的房间」这一旧义在此留存。"},{"word":"parole","ipa":"/pəˈrəʊl/","tag":"same root, a promise","definition":"A prisoner's promise of good behaviour, literally a word given; it comes through the same speaking root.","definitionCN":"指囚犯作出的守规承诺，字面是「给出的话」；它经同一个「说话」词根而来。"},{"word":"parable","ipa":"/ˈpærəbəl/","tag":"the Greek source","definition":"A short story used to illustrate a moral point, directly from Greek parabole; parliament's root is a speaking verb grown from this noun.","definitionCN":"指用来说明道理的短故事，直接来自希腊 parabole；parliament 的词根是由这个名词长出的说话动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"congress","ipa":"/ˈkɒŋɡres/","tag":"walking together","definition":"A national legislature, especially the American one; its image is people coming together, not people speaking.","definitionCN":"指国家立法机关，尤指美国国会；其意象是人走到一起，而非人说话。"},{"word":"legislature","ipa":"/ˈleɡɪsleɪtʃə/","tag":"law-bearing body","definition":"The general term for a lawmaking body; parliament is the specific model in which the executive sits inside it.","definitionCN":"指立法机关的通用说法；parliament 是行政也坐在其中的特定模式。"},{"word":"assembly","ipa":"/əˈsembli/","tag":"gathering","definition":"Any gathering of people, including a lawmaking one; it is the broad noun that parliament narrows.","definitionCN":"指任何人群聚集，包括立法性集会；它是 parliament 所收窄的宽泛名词。"},{"word":"diet","ipa":"/ˈdaɪət/","tag":"historical assembly","definition":"The name of certain historical assemblies, as in the Diet of Worms; the word came from a day's appointed meeting.","definitionCN":"指某些历史性议会的名称，如沃尔姆斯议会；这个词来自约定的会面日。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real speaking root, the real family and the real institutional phrases.","cn":"正常联想：真实的「说话」词根、真实词族与真实的机构搭配。"},"normal":[{"en":"parler 'to speak': the place where a country talks its laws into being.","cn":"parler「说话」：一个国家通过说话把法律谈出来的地方。"},{"en":"The family runs parliament, parliamentary, parliamentarian, parley, parlour and parole.","cn":"同族词包括 parliament、parliamentary、parliamentarian、parley、parlour 与 parole。"},{"en":"Fixed phrases mark the institution: member of parliament, dissolve parliament, a sitting of parliament.","cn":"固定搭配标出机构用法：议会议员、解散议会、议会的一次会议。"},{"en":"The i in the spelling was restored from Medieval Latin, not taken from French.","cn":"拼写里的 i 是从中世纪拉丁语回补的，并非取自法语。"},{"en":"The root is Greek parabole, which also gave parable and parabola.","cn":"词根是希腊 parabole，它还给了 parable 与 parabola。"}],"abstract":[{"en":"Picture two benches facing each other, with all the distance between them measured by a sheet of paper.","cn":"想象两条长凳相对，两人之间的距离用一张纸来丈量。"},{"en":"Picture a building that is empty half the year and loud the other half.","cn":"想象一栋建筑半年空着，另外半年很吵。"},{"en":"Picture a nest of birds arranged like a debating hall, each beak raised in turn.","cn":"想象一窝鸟排成议事厅的样子，每只轮流举喙。"}]},"examples":[{"en":"Parliament rejected the treaty by a narrow majority.","cn":"议会以微弱多数否决了该条约。"},{"en":"She was elected to parliament at twenty-nine.","cn":"她二十九岁当选议员。"},{"en":"The old parliament building is now a museum.","cn":"旧的议会大厦如今是博物馆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「怕了-门特」——议员在「门特」（门口）里吵得让人「怕了」，但吵完还是要表决 → 议会","word":"parliament"},"root":"古法语 parlement「说话、会谈」← parler「说话」← 晚期拉丁 parabolare ← 拉丁 parabola「言语、比较」← 希腊 parabole「放在旁边、比喻」。","sensesIntro":{"en":"Eight senses follow one act of talking: talk becomes a royal council, then a national assembly, then its building, its members, its term, its regional copies, any debating group and finally a poem about birds.","cn":"八个义项围绕同一个「说话」动作展开：说话先变成王室会议，再变成国家议会，然后是它的建筑、议员、任期、地区复制版、任何辩论团体，最后是一首写鸟的诗。"},"semanticMap":{"core":{"en":"CORE IMAGE: two facing benches with a sheet of paper lying between them.","cn":"核心意象：两排相对的长凳，中间放着一页纸。"},"chain":["TALKING TOGETHER","ROYAL COUNCIL","NATIONAL ASSEMBLY","THE BUILDING","MEMBERS AS ONE","DEBATING GROUP"],"branches":[{"senses":"01 · 05","en":"FROM TALK TO LAW: a council summoned to speak becomes an assembly whose speaking makes law.","cn":"从说话到法律：被召来说话的会议，变成说话即立法的议会。"},{"senses":"02 · 03","en":"PLACE AND PERSONS: the building and the members both take the institution's name.","cn":"地点与人：建筑与议员都取用了机构的名字。"},{"senses":"04","en":"COUNTING TIME: a body that is dissolved and re-formed can be counted by its terms.","cn":"数着时间：被解散又重新组成的机构，可以按任期来计数。"},{"senses":"06 · 07","en":"COPIED SCALE: a province and a student rally both reuse the model of arguing toward a decision.","cn":"复制的尺度：一个省与一场学生集会都复用了「争到决定」的模式。"},{"senses":"08","en":"THE BIRDS: the most playful reach applies the assembly's name to a flock in a poem.","cn":"群鸟：最俏皮的延伸把议会的名字用在诗中的一群鸟上。"}]},"affixes":{"intro":{"en":"Parliament is a French noun from a Latin-speaking verb that itself grew from a Greek noun, so its family spans three languages.","cn":"parliament 是一个法语名词，出自一个拉丁「说话」动词，而该动词又由希腊名词长出，因此这个词族横跨三种语言。"},"latinIntro":{"en":"Greek parabole gives Latin parabola, Late Latin parabolare and French parler, from which parliament, parley, parlour and parole all descend.","cn":"希腊 parabole 给出拉丁 parabola、晚期拉丁 parabolare 与法语 parler，parliament、parley、parlour 与 parole 都由后者传下。"},"items":[{"word":"parabole","structure":"parabole (Greek noun, 'a placing beside, comparison')","meaning":"comparison, illustration","meaningCN":"比较；比喻","example":"The Greek noun is the source of the whole family.","exampleCN":"这个希腊名词是整个词族的源头。"},{"word":"parabola","structure":"parabola (Latin noun, from Greek)","meaning":"speech, comparison","meaningCN":"言语；比较","example":"Latin parabola also gave the English parable.","exampleCN":"拉丁 parabola 还给了英语 parable。"},{"word":"parabolare","structure":"parabolare (Late Latin verb)","meaning":"to speak, talk","meaningCN":"说话；谈话","example":"The verb passed into French as parler.","exampleCN":"这个动词进入法语作 parler。"},{"word":"parlement","structure":"parlement (Old French noun)","meaning":"a speaking, a conference","meaningCN":"说话；会谈","example":"The French noun first meant talk, not a chamber.","exampleCN":"这个法语名词最初指谈话，不指议院。"},{"word":"parliament","structure":"parlement + spelling from Medieval Latin parliamentum","meaning":"a formal assembly","meaningCN":"正式议会","example":"Parliament meets after the election.","exampleCN":"议会在大选后开会。"},{"word":"parliamentary","structure":"parliament + -ary (relating to)","meaning":"relating to a parliament","meaningCN":"与议会有关的","example":"The bill cleared its parliamentary stages.","exampleCN":"该法案通过了各议会阶段。"},{"word":"parliamentarian","structure":"parliament + -arian (person concerned with)","meaning":"a member or rules expert","meaningCN":"议员；议事规则专家","example":"The parliamentarian knew every precedent.","exampleCN":"这位议事专家熟悉每一条先例。"},{"word":"parley","structure":"parler + -ee (a talk)","meaning":"a conference with an opponent","meaningCN":"与对手的会谈","example":"The two sides met for a parley.","exampleCN":"双方举行了一次会谈。"},{"word":"parlour","structure":"parler + -our (place of)","meaning":"a room for conversation","meaningCN":"谈话用的房间","example":"Guests waited in the parlour.","exampleCN":"客人在起居室等待。"},{"word":"-ment","structure":"-ment (French noun suffix, from Latin -mentum)","meaning":"result or means of an action","meaningCN":"动作的结果或手段","example":"The ending marks the outcome of speaking.","exampleCN":"这个词尾标记说话的结果。"}],"latinEntries":[{"word":"parabola","structure":"parabola, parabolae (f., first declension, from Greek)","meaning":"speech, comparison","meaningCN":"言语；比较"},{"word":"parabolare","structure":"parabolare (Late Latin verb, first conjugation)","meaning":"to speak, talk","meaningCN":"说话；谈话"},{"word":"parliamentum","structure":"parliamentum, parliamenti (n., second declension, Medieval Latin)","meaning":"a conference, assembly","meaningCN":"会议；议会"}],"derivatives":[{"word":"parliamentary","pos":"adj.","zh":"议会的；议会程序的"},{"word":"parliamentarian","pos":"n.","zh":"议员；议事规则专家"},{"word":"parliamentarianism","pos":"n.","zh":"议会制主张"},{"word":"parley","pos":"n./v.","zh":"会谈；谈判"},{"word":"parlour","pos":"n.","zh":"起居室"},{"word":"parole","pos":"n.","zh":"假释；承诺"}]}},{"word":"parliamentary","ipa_uk":"/ˌpɑːləˈmentəri/","ipa_us":"/ˌpɑːrləˈmentəri/","definition_zh":"议会的；议会制的；符合议会程序的","definition_en":"relating to a parliament, to a system governed through one, or to the rules by which it conducts business","core_image":"两排长凳之间一条笔直的通道，通道两侧的每一步都被同一套规矩量过","scene":"两排长凳之间留出一条笔直通道，走道上的每一步都按同一套规矩。The parliamentary debate followed rules that had not changed in a century.","sceneCN":"句中这个词指依照议会程序进行的（第 3 个义项：符合议会规则与惯例的）；句意为这场议会辩论遵循了一套百年未改的规则。图中可辨识物件：两排长凳、中央通道、议事规则册、计时沙漏、议长席位。","pos":[{"tag":"adj.","zh":"议会的；议会制的"},{"tag":"adj.","zh":"符合议会程序与惯例的"}],"collocations":[{"phrase":"parliamentary system","zh":"议会制"},{"phrase":"parliamentary majority","zh":"议会多数"},{"phrase":"parliamentary election","zh":"议会选举"},{"phrase":"parliamentary procedure","zh":"议会程序"},{"phrase":"parliamentary committee","zh":"议会委员会"},{"phrase":"parliamentary language","zh":"议会用语（得体措辞）"}],"forms":[{"label":"原级","form":"parliamentary"},{"label":"比较级","form":"more parliamentary"},{"label":"最高级","form":"most parliamentary"},{"label":"名词（议会）","form":"parliament"},{"label":"名词（议员）","form":"parliamentarian"}],"derivatives":[{"word":"parliament","pos":"n.","zh":"议会"},{"word":"parliamentarian","pos":"n.","zh":"议员；议事规则专家"},{"word":"parliamentarianism","pos":"n.","zh":"议会制主张"},{"word":"unparliamentary","pos":"adj.","zh":"不合议会礼节的"},{"word":"parley","pos":"n./v.","zh":"会谈；谈判"}],"senses":[{"no":"01","title":"Relating to a parliament","titleCN":"与议会有关的","definition":"concerning a parliament, its members or its business","definitionCN":"与议会、议员或议会事务有关的","example":"The parliamentary year begins with a ceremonial opening.","exampleCN":"议会年度以一场仪式性开幕开始。","why":"The adjective is simply parliament plus the Latin ending -ary, which means 'belonging to', so its first sense is bare relation.","whyCN":"这个形容词就是 parliament 加拉丁词尾 -ary（意为「属于」），因此第一义只是表示归属关系。"},{"no":"02","title":"Of a parliamentary system","titleCN":"议会制体制的","definition":"describing a system in which the government is formed from and answerable to the assembly","definitionCN":"形容政府由议会组成并向议会负责的体制","example":"Canada has a parliamentary system rather than a presidential one.","exampleCN":"加拿大实行议会制，而非总统制。","why":"The adjective distinguishes a whole constitutional model, not just a building or a session.","whyCN":"这个形容词区分的是一整套宪制模式，而不只是建筑或会期。"},{"no":"03","title":"According to parliamentary rules","titleCN":"依照议会规则与惯例","definition":"done in the manner required by the standing orders and customs of an assembly","definitionCN":"按议会的议事规则与惯例所要求的方式进行的","example":"The parliamentary debate followed rules that had not changed in a century.","exampleCN":"这场议会辩论遵循了一套百年未改的规则。","why":"The dictionary sense 'in accordance with the rules and usages of legislatures' comes straight from the noun's business.","whyCN":"词典中「符合立法机构规则与惯例」这一义项，直接来自这个名词所办的事务。"},{"no":"04","title":"Of a majority or a seat","titleCN":"议会多数或席位的","definition":"used of the number of seats that gives one party control, or of a seat itself","definitionCN":"用于指使某党取得控制权的席位数，或指一个席位本身","example":"The party won a parliamentary majority of twelve.","exampleCN":"该党赢得了十二席的议会多数。","why":"Counting seats is how a chamber decides who governs, so the adjective attaches to numbers.","whyCN":"数席位是议院决定由谁执政的方式，因此这个形容词会附着在数字上。"},{"no":"05","title":"Of elections and constituencies","titleCN":"议会选举与选区的","definition":"relating to the vote that fills the chamber or to the district that returns a member","definitionCN":"与填补议席的投票有关，或与推举议员的选区有关","example":"Boundaries for parliamentary seats were redrawn last year.","exampleCN":"议会席位边界去年被重新划定。","why":"An assembly needs a way to be filled, and the adjective names that electoral machinery.","whyCN":"议院需要一种被填补的方式，这个形容词命名的就是那套选举机器。"},{"no":"06","title":"Polite or allowable in the chamber","titleCN":"议会中得体的（用语）","definition":"used of language judged acceptable in debate, often in the phrase unparliamentary language","definitionCN":"用于辩论中被认为可接受的语言，常见于「不合议会礼节的语言」这一说法","example":"The speaker ruled the remark parliamentary only after a pause.","exampleCN":"议长停顿之后才裁定这句话合乎议会礼节。","why":"A chamber polices its own words, so the adjective can describe whether a phrase is fit to be said there.","whyCN":"议院会管自己的言辞，因此这个形容词可以描述一句话是否适合在那里说。"},{"no":"07","title":"The Parliament side in the civil war","titleCN":"英国内战中议会一方的","definition":"historical use for the forces and party that supported Parliament against the crown","definitionCN":"历史用法，指英国内战中支持议会、对抗王室的军队与党派","example":"Parliamentary troops held the river crossing.","exampleCN":"议会军守住了那条渡口。","why":"When the assembly became a warring party, its name turned into a side in a conflict.","whyCN":"当议会成为一个交战方时，它的名字就变成冲突中的一派。"},{"no":"08","title":"Procedural in any meeting","titleCN":"任何会议中的程序性做法","definition":"an extended use for strict adherence to formal rules in a club or society","definitionCN":"引申用法，指在社团或学会里严格遵守正式规则","example":"Their parliamentary habits slowed every decision.","exampleCN":"他们那套议会式的习惯拖慢了每项决定。","why":"The rules of a chamber can be copied by any group, and the adjective follows the practice.","whyCN":"议院的规则可被任何团体照搬，这个形容词也就跟着这一做法走。"}],"etymology":{"intro":{"en":"Parliamentary is parliament plus -ary, recorded from the 1610s with the sense 'in accordance with the rules and usages of legislatures'. Parliament itself comes from French parler 'to speak'.","cn":"parliamentary 是 parliament 加 -ary，自十七世纪一十年代见于记录，意为「符合立法机构的规则与惯例」。parliament 本身来自法语 parler「说话」。"},"items":[{"era":"GREEK PARABOLE TO FRENCH","en":"Greek parabole gave Latin parabola and Late Latin parabolare 'to speak', which became Old French parler and the noun parlement 'a speaking, a conference'.","cn":"希腊 parabole 给出拉丁 parabola 与晚期拉丁 parabolare「说话」，后者变成古法语 parler 以及名词 parlement「说话、会谈」。"},{"era":"ENGLISH PARLIAMENT","en":"English parliament is recorded about 1300 for a conference, and by the mid-fourteenth century for the representative assembly of England.","cn":"英语 parliament 约在 1300 年指会议，到十四世纪中期指英格兰的代表性议会。"},{"era":"THE SUFFIX -ARY","en":"The ending -ary came through French from Latin -arius, meaning 'belonging to or connected with', and it also builds military, honorary and customary.","cn":"词尾 -ary 经法语来自拉丁 -arius，意为「属于或与……有关」，它还构成 military、honorary 与 customary。"},{"era":"PARLIAMENTARY 1610","en":"The adjective appears in the 1610s, first for what pertains to a parliament and very soon for what conforms to its rules.","cn":"这个形容词在十七世纪一十年代出现，先指与议会有关的，很快也指符合其规则的。"},{"era":"MODERN EXTENSIONS","en":"The parliamentary system, parliamentary majority and parliamentary language all belong to later constitutional writing and reporting.","cn":"议会制、议会多数与议会用语这些说法，都属于后来的宪制写作与新闻报道。"},{"era":"APPROXIMATE DATES","en":"The word chain is fully documented; only the earliest citation of each sense is approximate, so nothing here is marked source uncertain.","cn":"词形链条有完整记录，只有各义项的最早书证是约数，因此此处没有需要标为来源不确定的部分。"}]},"similar":{"note":{"en":"Group one holds words formed on parliament and on the speaking root; group two holds adjectives describing systems or procedures of rule.","cn":"第一组是由 parliament 与「说话」词根构成的词；第二组是描述统治体制或程序的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parliament","ipa":"/ˈpɑːləmənt/","tag":"the noun","definition":"The assembly itself, or its building or term; the adjective only describes something related to it.","definitionCN":"指议会本身，或其建筑、任期；形容词只描述与之相关的事物。"},{"word":"parliamentarian","ipa":"/ˌpɑːləmenˈteəriən/","tag":"a person","definition":"A member of a parliament, or one expert in its procedure; it names a person, not a quality.","definitionCN":"指议员，或精通议会程序的人；它命名人，不命名性质。"},{"word":"parley","ipa":"/ˈpɑːli/","tag":"a talk, not a body","definition":"A discussion with an opponent, from the same speaking verb; it has no institutional sense at all.","definitionCN":"指与对手的商谈，出自同一个「说话」动词；完全没有机构义。"},{"word":"parliamentary","ipa":"/ˌpɑːləˈmentəri/","tag":"this adjective","definition":"The adjective for what belongs to or follows a parliament; it is the entry you are reading.","definitionCN":"指属于议会或遵循议会规则的形容词；本词条即此词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"legislative","ipa":"/ˈleɡɪsleɪtɪv/","tag":"lawmaking in general","definition":"Relating to lawmaking or to a legislature; it fits any lawmaking body, while parliamentary points to the parliament model.","definitionCN":"指与立法或立法机关有关的；适用于任何立法机构，而 parliamentary 指向议会这一模式。"},{"word":"congressional","ipa":"/kɒŋˈɡresənəl/","tag":"American model","definition":"Relating to the United States Congress; it is the American counterpart of parliamentary in institutional use.","definitionCN":"指与美国国会有关的；在机构用法上是 parliamentary 的美国对应词。"},{"word":"procedural","ipa":"/prəˈsiːdərəl/","tag":"about process","definition":"Concerned with the steps by which a decision is reached; parliamentary rules are a species of procedural rules.","definitionCN":"指与作出决定的步骤有关的；议会规则是程序规则的一个种类。"},{"word":"constitutional","ipa":"/ˌkɒnstɪˈtjuːʃənəl/","tag":"about the charter","definition":"Relating to a constitution or allowed by it; it concerns the framework of power rather than the chamber's daily rules.","definitionCN":"指与宪法有关或合宪的；它关乎权力框架，而非议院的日常规则。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffix, the real speaking root and the real constitutional phrases.","cn":"正常联想：真实词尾、真实的「说话」词根与真实的宪制搭配。"},"normal":[{"en":"parliament plus -ary 'belonging to': everything that belongs to the talking chamber.","cn":"parliament 加 -ary「属于」：一切属于那个「说话议事厅」的东西。"},{"en":"The family runs parliament, parliamentary, parliamentarian and parley.","cn":"同族词包括 parliament、parliamentary、parliamentarian 与 parley。"},{"en":"Fixed phrases mark the model: parliamentary system, parliamentary majority, parliamentary procedure.","cn":"固定搭配标出模式：议会制、议会多数、议会程序。"},{"en":"The same -ary ending appears in military, honorary and customary.","cn":"同一 -ary 词尾还出现在 military、honorary 与 customary 中。"},{"en":"The root chain runs from Greek parabole to French parler.","cn":"词根链从希腊 parabole 一直通到法语 parler。"}],"abstract":[{"en":"Picture a corridor whose width is fixed by a very old book.","cn":"想象一条通道，它的宽度由一本很老的书规定。"},{"en":"Picture a clock that stops debate rather than measuring it.","cn":"想象一只时钟不是用来量辩论，而是用来中止辩论。"},{"en":"Picture a room where even an insult has to be phrased in a permitted shape.","cn":"想象一间屋子，连一句侮辱都必须说成被允许的形状。"}]},"examples":[{"en":"The country moved from a presidential to a parliamentary system.","cn":"这个国家从总统制转向议会制。"},{"en":"A parliamentary inquiry heard evidence for six weeks.","cn":"一项议会调查听取了六周证词。"},{"en":"The chair ruled the phrase unparliamentary.","cn":"主席裁定这句话不合议会礼节。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「怕了-门-特-瑞」——议会里吵得让人「怕了」，但每句话都要按「瑞」正的规矩说 → 议会的","word":"parliamentary"},"root":"parliament「议会」+ -ary「属于……的」；parliament 来自古法语 parlement「说话、会谈」，再上溯晚期拉丁 parabolare 与希腊 parabole。","sensesIntro":{"en":"Eight senses radiate from one chamber: what belongs to it, the system built on it, its procedure, its seat count, its elections, its allowable words, its civil-war side and finally any group copying its rules.","cn":"八个义项从一个议院向外辐射：属于它的、以它为基础的体制、它的程序、它的席位数、它的选举、它允许的措辞、它在内战中的一方，最后是任何照搬其规则的团体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straight corridor between two benches, its width fixed by old rules.","cn":"核心意象：两排长凳间的笔直通道，宽度由旧规则定死。"},"chain":["BELONGING TO PARLIAMENT","PARLIAMENTARY SYSTEM","CHAMBER PROCEDURE","SEAT COUNT","ELECTORAL MACHINERY","ALLOWED LANGUAGE"],"branches":[{"senses":"01 · 02","en":"RELATION AND MODEL: describing a thing as belonging to a parliament shades into naming a whole constitutional model.","cn":"关系与模式：把某物说成属于议会，会滑向命名一整套宪制模式。"},{"senses":"03 · 08","en":"RULES AT TWO SCALES: a chamber's standing orders can be copied by a small club.","cn":"两种尺度的规则：议院的议事规则可被小社团照搬。"},{"senses":"04 · 05","en":"SEATS AND VOTES: seats are won by elections, so counting and contesting belong to the same machinery.","cn":"席位与选票：席位靠选举赢得，因此计数与争夺属于同一套机器。"},{"senses":"06","en":"POLICED SPEECH: the chamber judges which words may be spoken inside it.","cn":"被管束的言辞：议院裁定哪些话能在它里面说。"},{"senses":"07","en":"THE WAR SIDE: when the assembly takes up arms, its name becomes a faction.","cn":"战事一方：当议会拿起武器，它的名字就变成一派。"}]},"affixes":{"intro":{"en":"Parliamentary is a French-rooted noun with a Latin adjective ending, so its pieces explain both its form and its range.","cn":"parliamentary 是一个法语词根的名词加拉丁形容词词尾，其构件同时解释了它的形式与用法范围。"},"latinIntro":{"en":"The speaking root runs from Greek parabole through Latin parabola and Late Latin parabolare to French parler; -arius gives the English ending -ary.","cn":"「说话」词根从希腊 parabole 经拉丁 parabola 与晚期拉丁 parabolare 到法语 parler；-arius 给出英语词尾 -ary。"},"items":[{"word":"parlement","structure":"parlement (Old French noun, 'a speaking, a conference')","meaning":"talk, conference","meaningCN":"谈话；会谈","example":"The French noun named talk before it named an assembly.","exampleCN":"这个法语名词先指谈话，后指议会。"},{"word":"parliament","structure":"parlement + Medieval Latin spelling","meaning":"a formal assembly","meaningCN":"正式议会","example":"Parliament opens in the autumn.","exampleCN":"议会秋季开议。"},{"word":"parliamentary","structure":"parliament + -ary (belonging to)","meaning":"relating to a parliament","meaningCN":"与议会有关的","example":"The parliamentary session ran late.","exampleCN":"议会会期开到很晚。"},{"word":"parliamentarian","structure":"parliament + -arian (person concerned with)","meaning":"a member or rules expert","meaningCN":"议员；议事专家","example":"The parliamentarian cited an old ruling.","exampleCN":"这位议事专家引用了一条旧裁定。"},{"word":"-ary","structure":"-ary (English adjective suffix, from Latin -arius)","meaning":"belonging to, connected with","meaningCN":"属于……的；与……有关的","example":"Military is built with the same ending.","exampleCN":"military 用同一词尾构成。"},{"word":"unparliamentary","structure":"un- + parliamentary","meaning":"not fit for the chamber","meaningCN":"不合议会礼节的","example":"The chair called the word unparliamentary.","exampleCN":"主席称这个词不合议会礼节。"},{"word":"parley","structure":"parler + -ee (a talk)","meaning":"a conference with an opponent","meaningCN":"与对手的会谈","example":"They met for a parley at dawn.","exampleCN":"他们在黎明时会谈。"},{"word":"parlour","structure":"parler + -our (place of)","meaning":"a room for conversation","meaningCN":"谈话用的房间","example":"The guests sat in the parlour.","exampleCN":"客人坐在起居室。"},{"word":"parole","structure":"parole (French, 'word, promise')","meaning":"a promise; release on such a promise","meaningCN":"诺言；以诺言为条件的释放","example":"He was released on parole.","exampleCN":"他获假释出狱。"}],"latinEntries":[{"word":"parabola","structure":"parabola, parabolae (f., first declension, from Greek)","meaning":"speech, comparison","meaningCN":"言语；比较"},{"word":"parabolare","structure":"parabolare (Late Latin verb, first conjugation)","meaning":"to speak","meaningCN":"说话"},{"word":"parliamentum","structure":"parliamentum, parliamenti (n., second declension, Medieval Latin)","meaning":"conference, assembly","meaningCN":"会议；议会"}],"derivatives":[{"word":"parliament","pos":"n.","zh":"议会"},{"word":"parliamentarian","pos":"n.","zh":"议员；议事规则专家"},{"word":"parliamentarianism","pos":"n.","zh":"议会制主张"},{"word":"unparliamentary","pos":"adj.","zh":"不合议会礼节的"},{"word":"parley","pos":"n./v.","zh":"会谈；谈判"},{"word":"parlour","pos":"n.","zh":"起居室"}]}},{"word":"congress","ipa_uk":"/ˈkɒŋɡres/","ipa_us":"/ˈkɑːŋɡres/","definition_zh":"国会（尤指美国）；代表大会；大会；（正式）性交","definition_en":"the national legislature of a country, especially the United States, or a formal meeting of delegates","core_image":"许多人从不同方向走进同一座大厅，脚步最后汇成一条走廊","scene":"不同方向的代表沿着各自的走廊走进同一座大厅，脚步声在门口汇成一处。Congress voted to extend the programme for another year.","sceneCN":"句中这个词指一国的国家立法机关，尤指美国国会（第 1 个义项：由两院组成、掌握联邦立法权的国会）；句意为国会投票决定将该计划延长一年。图中可辨识物件：多条走廊、大厅门口、代表证件、表决牌、议程册。","pos":[{"tag":"n.","zh":"国会（尤指美国）；立法机关"},{"tag":"n.","zh":"代表大会；正式会议"},{"tag":"n.","zh":"（正式用语）性交"}],"collocations":[{"phrase":"the United States Congress","zh":"美国国会"},{"phrase":"member of Congress","zh":"国会议员"},{"phrase":"a party congress","zh":"党代表大会"},{"phrase":"an international congress","zh":"国际大会"},{"phrase":"the Congress of Vienna","zh":"维也纳会议"},{"phrase":"Congress passed the act","zh":"国会通过了该法案"}],"forms":[{"label":"复数","form":"congresses"},{"label":"形容词","form":"congressional"},{"label":"名词（议员）","form":"congressman"},{"label":"名词（女议员）","form":"congresswoman"},{"label":"名词（代表大会成员）","form":"congressperson"}],"derivatives":[{"word":"congressional","pos":"adj.","zh":"国会的；代表大会的"},{"word":"congressman","pos":"n.","zh":"（美国）国会议员"},{"word":"congresswoman","pos":"n.","zh":"（美国）女国会议员"},{"word":"congressperson","pos":"n.","zh":"国会议员（中性说法）"},{"word":"congressionally","pos":"adv.","zh":"由国会地；以国会方式"}],"senses":[{"no":"01","title":"The United States legislature","titleCN":"美国国会","definition":"the bicameral national legislature of the United States, made up of the Senate and the House","definitionCN":"由参议院与众议院两院组成的美国国家立法机关","example":"Congress voted to extend the programme for another year.","exampleCN":"国会投票决定把该计划再延长一年。","why":"The name was given to the American national assembly in 1775, when delegates came together from separate colonies.","whyCN":"这个名字于 1775 年给了美国的国家议会，当时代表们从各殖民地走到一起。"},{"no":"02","title":"A scholarly or professional conference","titleCN":"学术或专业大会","definition":"a large formal meeting of specialists who present and discuss work","definitionCN":"由专家参加、宣读并讨论工作的大型正式会议","example":"Three thousand doctors attended the cardiology congress.","exampleCN":"三千名医生参加了这次心脏病学大会。","why":"The oldest sense is people coming together, and a conference keeps exactly that sense without any lawmaking.","whyCN":"最老的意思是人们走到一起，学术会议保留的正是这个意思，而不含立法。"},{"no":"03","title":"A party assembly","titleCN":"政党代表大会","definition":"the periodic meeting at which a political party decides policy and chooses leaders","definitionCN":"政党定期开会决定政策并选出领导人的会议","example":"The party congress meets every four years.","exampleCN":"该党代表大会每四年召开一次。","why":"A party organises its own representation, so its delegate meeting borrows the general word for a coming together.","whyCN":"政党要组织自己的代表，于是其代表会议借用了「走到一起」这个通用词。"},{"no":"04","title":"A formal meeting of delegates","titleCN":"正式的代表会议","definition":"any organised meeting of representatives with an agenda and a mandate","definitionCN":"任何有议程与授权的代表集会","example":"A congress of mayors drafted the housing charter.","exampleCN":"一次市长会议起草了住房宪章。","why":"Representation is the common thread: those who come together speak for others.","whyCN":"代表制是共同线索：走到一起的人是在替别人说话。"},{"no":"05","title":"Sexual union","titleCN":"性交（正式委婉语）","definition":"the formal or euphemistic term for sexual intercourse","definitionCN":"对性交的正式或委婉说法","example":"The old legal text used congress for sexual union.","exampleCN":"那份古老的法律文本用 congress 指性结合。","why":"Latin congressus also meant a meeting, including a bodily one, and the euphemism survives in medical and legal English.","whyCN":"拉丁 congressus 也指会合，包括身体的会合，这一委婉用法在医学与法律英语中留存。"},{"no":"06","title":"The act of coming together","titleCN":"会合这一动作（古义）","definition":"archaic use for the physical act of meeting or assembling","definitionCN":"古旧用法，指相遇或聚集这一实际动作","example":"The chronicle describes the congress of the two armies.","exampleCN":"这部编年史写到两军的会合。","why":"The Latin noun names the meeting itself before English uses it for the body that meets.","whyCN":"拉丁名词先命名会合本身，英语后来才用它指会合的机构。"},{"no":"07","title":"A diplomatic gathering of states","titleCN":"国家间的外交会议","definition":"a congress of powers met to settle borders or treaties, as at Vienna in 1814","definitionCN":"列强为划定边界或订立条约而召开的会议，如 1814 年的维也纳会议","example":"The Congress of Vienna redrew the map of Europe.","exampleCN":"维也纳会议重画了欧洲地图。","why":"States also come together, and the word extends from delegates of parties to delegates of governments.","whyCN":"国家也会走到一起，于是这个词从党派代表延伸到政府代表。"},{"no":"08","title":"Another country's legislature","titleCN":"其他国家的同名立法机关","definition":"the name used for the national legislature of several other states","definitionCN":"若干其他国家用于国家立法机关的名称","example":"The Mexican Congress debated the energy reform.","exampleCN":"墨西哥国会辩论了能源改革。","why":"The American name became a model that other states copied for their own chambers.","whyCN":"美国的名称成了一个样板，其他国家照它命名自己的议院。"}],"etymology":{"intro":{"en":"Congress is from Latin congressus 'a meeting', from congredi 'to meet, go together', built on com- 'together' and gradi 'to walk, step'. English gave the name to the American legislature in 1775.","cn":"congress 来自拉丁 congressus「会合」，出自 congredi「相遇、同行」，由 com-「共同」与 gradi「走、迈步」构成。英语于 1775 年把这个名字给了美国立法机关。"},"items":[{"era":"LATIN GRADUS","en":"Gradus meant 'a step', and gradi meant 'to walk, to step'. The root, reconstructed as a Proto-Indo-European word for walking, also underlies progress, ingress and egress.","cn":"gradus 意为「一步」，gradi 意为「走、迈步」。这个可重构为印欧语「行走」的词根，也支撑着 progress、ingress 与 egress。"},{"era":"LATIN CONGREDI","en":"Com- 'together' plus gradi produced congredi 'to meet, to come together', used both of friendly meetings and of armies meeting in battle.","cn":"com-「共同」加 gradi 构成 congredi「相遇、走到一起」，既用于友好会面，也用于两军在战斗中相遇。"},{"era":"CONGRESSUS","en":"The noun congressus named a meeting or an encounter; its past-participle stem also gave the English adjective congressional.","cn":"名词 congressus 指会合或遭遇；其过去分词词干还给出英语形容词 congressional。"},{"era":"ENGLISH 1400","en":"English congress is recorded about 1400 for a body of attendants and by the fifteenth century for a meeting of armed forces; the sense of people coming together is from the 1520s.","cn":"英语 congress 约在 1400 年指随从队伍，十五世纪指军队会合；「人们走到一起」的义项自十六世纪二十年代起。"},{"era":"DELEGATES AND SEXUAL UNION","en":"The sense of a meeting of delegates is recorded by the 1670s, and the sense of sexual union from the 1580s.","cn":"代表会议的义项自十七世纪七十年代见于记录，性结合的义项自十六世纪八十年代。"},{"era":"AMERICAN NAME 1775","en":"Congress has named the American national legislature since 1775, after earlier use for the Continental Congress from 1774.","cn":"自 1775 年起，congress 成为美国国家立法机关的名称；更早则自 1774 年起用于大陆会议。"}]},"similar":{"note":{"en":"Group one holds words built on gradi 'to walk', which look close in form and share one root; group two holds other gatherings and legislatures.","cn":"第一组是由 gradi「走」构成的词，形式相近且同根；第二组是其他集会与立法机关。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"progress","ipa":"/ˈprəʊɡres/","tag":"step forward","definition":"Pro- 'forward' plus gradi: a stepping forward, or to move forward; the same walking root, a different prefix.","definitionCN":"pro-「向前」加 gradi：向前迈步，或向前推进；同一行走词根，不同前缀。"},{"word":"ingress","ipa":"/ˈɪnɡres/","tag":"step in","definition":"In- 'into' plus gradi: the act of entering, as of light or of a person; same root, inward direction.","definitionCN":"in-「进入」加 gradi：进入的动作，如光或人的进入；同根，方向向内。"},{"word":"egress","ipa":"/ˈiːɡres/","tag":"step out","definition":"E- 'out' plus gradi: the act of going out, or a way out; same root, outward direction.","definitionCN":"e-「出」加 gradi：出去的动作或出口；同根，方向向外。"},{"word":"gradient","ipa":"/ˈɡreɪdiənt/","tag":"step-based measure","definition":"Built on gradus 'step': the rate at which a quantity changes, literally a stepping measure.","definitionCN":"由 gradus「步」构成：某量变化的速率，字面上是「按步计量」的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"parliament","ipa":"/ˈpɑːləmənt/","tag":"talking assembly","definition":"A national legislature whose name comes from speaking; in such a system the executive is drawn from its members.","definitionCN":"名字来自「说话」的国家立法机关；在这种体制下，行政由议员产生。"},{"word":"legislature","ipa":"/ˈleɡɪsleɪtʃə/","tag":"generic term","definition":"The general word for a lawmaking body; congress names a particular kind of national one.","definitionCN":"立法机关的通用说法；congress 命名的是某类特定的国家立法机关。"},{"word":"convention","ipa":"/kənˈvenʃən/","tag":"political gathering","definition":"A large meeting of a party or trade, from Latin convenire 'to come together'; it is usually not permanent like a congress.","definitionCN":"指政党或行业的大型会议，出自拉丁 convenire「走到一起」；通常不像 congress 那样常设。"},{"word":"conference","ipa":"/ˈkɒnfərəns/","tag":"general meeting","definition":"Any organised meeting for discussion, often shorter and less formal than a congress.","definitionCN":"任何为讨论而组织的会议，通常比 congress 更短、更不正式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real walking root, the real family and the real institutional phrases.","cn":"正常联想：真实的「行走」词根、真实词族与真实的机构搭配。"},"normal":[{"en":"com- 'together' plus gradi 'walk': representatives walking together into one hall.","cn":"com-「共同」加 gradi「走」：代表们一起走进同一座大厅。"},{"en":"The family runs congress, congressional, congressman and congresswoman.","cn":"同族词包括 congress、congressional、congressman 与 congresswoman。"},{"en":"Fixed phrases mark the uses: member of Congress, a party congress, an international congress.","cn":"固定搭配标出用法：国会议员、党代表大会、国际大会。"},{"en":"The same root appears in progress, ingress, egress and gradient.","cn":"同一词根出现在 progress、ingress、egress 与 gradient 中。"},{"en":"The Congress of Vienna of 1815 shows the diplomatic sense of the word.","cn":"1815 年的维也纳会议显示了这个词的外交义。"}],"abstract":[{"en":"Picture many roads ending at one door, each road carrying a different district's voice.","cn":"想象许多条路都终结于一扇门，每条路都带来一个不同选区的声音。"},{"en":"Picture two armies arriving at the same field from opposite sides.","cn":"想象两支军队从相反方向抵达同一片原野。"},{"en":"Picture a room that empties and refills on a fixed calendar.","cn":"想象一间按固定日历清空又坐满的屋子。"}]},"examples":[{"en":"Congress controls federal spending through its committees.","cn":"国会通过其委员会控制联邦开支。"},{"en":"The medical congress drew researchers from forty countries.","cn":"这次医学大会吸引了四十个国家的研究者。"},{"en":"The Congress of Vienna tried to restore a balance of power.","cn":"维也纳会议试图恢复势力均衡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康-格瑞斯」——代表们「康」健地一起「格瑞斯」（迈步）走进大厅 → 国会","word":"congress"},"root":"拉丁 congressus「会合」← congredi「走到一起」= com-（共同）+ gradi「走、迈步」（gradus「步」）；同根有 progress、ingress、egress、gradient。","sensesIntro":{"en":"Eight senses follow one movement: people walk together, which yields a delegate meeting, a party meeting, a scholarly meeting, a diplomatic meeting, a sexual meeting, a national legislature, other legislatures and the bare act of meeting.","cn":"八个义项跟随同一个动作：人们走到一起；由此生出代表会议、党派会议、学术会议、外交会议、身体会合、国家立法机关、他国同名机关，以及会合这一动作本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: many roads ending at one door, footsteps joining into a single corridor.","cn":"核心意象：许多条路终结于一扇门，脚步声汇成一条走廊。"},"chain":["WALKING TOGETHER","DELEGATE MEETING","PARTY ASSEMBLY","SCHOLARLY MEETING","SEXUAL UNION","NATIONAL LEGISLATURE"],"branches":[{"senses":"08","en":"ONE NAME, MANY STATES: the American title became a model copied by other national chambers.","cn":"一个名字，多个国家：美国的称号成了被其他国家议院照搬的样板。"},{"senses":"02 · 04","en":"SPECIALISTS AND DELEGATES: a congress of doctors and a congress of mayors are the same form of meeting.","cn":"专家与代表：医生大会与市长会议是同一种会议形式。"},{"senses":"03 · 07","en":"PARTIES AND POWERS: a party congress and a congress of states both settle policy by assembled delegates.","cn":"党派与列强：党代表大会与列强会议都由聚在一起的代表定政策。"},{"senses":"05 · 06","en":"BODY AND ROOT: the euphemism for sexual union and the archaic act of meeting are the Latin noun's two oldest shadows.","cn":"身体与词根：性结合的委婉义与会合的古义，是拉丁名词最早的两道影子。"},{"senses":"01","en":"THE CAPITOL: the legislature is the sense that dominates everyday English.","cn":"国会山：立法机关义是日常英语中占主导的义项。"}]},"affixes":{"intro":{"en":"Congress is a Latin compound of a prefix and a walking root, and both pieces recur in dozens of English words.","cn":"congress 是一个由前缀与「行走」词根构成的拉丁复合词，两部分都反复出现在大量英语词中。"},"latinIntro":{"en":"Com- 'together' and gradi 'to walk' build congressus; gradus 'step' builds grade, gradual, gradient and degrade.","cn":"com-「共同」与 gradi「走」构成 congressus；gradus「步」构成 grade、gradual、gradient 与 degrade。"},"items":[{"word":"gradi","structure":"gradi, gressus sum (Latin deponent verb, third conjugation)","meaning":"to walk, to step","meaningCN":"走；迈步","example":"The root supplies the sense of movement.","exampleCN":"这个词根提供移动的意思。"},{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"a step, a degree","meaningCN":"一步；等级","example":"Gradus also gave the English word grade.","exampleCN":"gradus 还给了英语 grade。"},{"word":"congredi","structure":"com- + gradi","meaning":"to meet, come together","meaningCN":"相遇；走到一起","example":"Delegates walked together into one hall, which is the literal image of the Latin verb.","exampleCN":"代表们一起走进同一座大厅，这正是那个拉丁动词的字面意象。"},{"word":"congressus","structure":"congredi + -tus (action noun)","meaning":"a meeting, an encounter","meaningCN":"会合；遭遇","example":"The noun named the meeting before it named the body.","exampleCN":"这个名词先指会合，后指机构。"},{"word":"congress","structure":"congressus through French","meaning":"assembly; legislature","meaningCN":"集会；立法机关","example":"Congress meets in the Capitol.","exampleCN":"国会在国会大厦开会。"},{"word":"congressional","structure":"congress + -ional (relating to)","meaning":"relating to a congress","meaningCN":"与国会有关的","example":"A congressional hearing opened in June.","exampleCN":"一场国会听证会在六月开始。"},{"word":"progress","structure":"pro- 'forward' + gradi","meaning":"to move forward","meaningCN":"前进","example":"The same root points a different way.","exampleCN":"同一词根指向另一个方向。"},{"word":"ingress","structure":"in- 'into' + gradi","meaning":"entering","meaningCN":"进入","example":"Ingress is movement inward.","exampleCN":"ingress 是向内的移动。"},{"word":"egress","structure":"e- 'out' + gradi","meaning":"going out","meaningCN":"外出；出口","example":"Egress is movement outward.","exampleCN":"egress 是向外的移动。"},{"word":"-ional","structure":"-ional (English adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns congress into an adjective.","exampleCN":"这个词尾把 congress 变成形容词。"}],"latinEntries":[{"word":"gradi","structure":"gradi, gressus sum (deponent verb, third conjugation)","meaning":"to walk, step","meaningCN":"走；迈步"},{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"a step","meaningCN":"一步"},{"word":"congredi","structure":"congredi, congressus sum (deponent verb, third conjugation)","meaning":"to meet, come together","meaningCN":"相遇；会合"},{"word":"congressus","structure":"congressus, congressus (m., fourth declension)","meaning":"a meeting","meaningCN":"会合；会议"}],"derivatives":[{"word":"congressional","pos":"adj.","zh":"国会的；代表大会的"},{"word":"congressman","pos":"n.","zh":"（美国）国会议员"},{"word":"congresswoman","pos":"n.","zh":"（美国）女国会议员"},{"word":"congressperson","pos":"n.","zh":"国会议员（中性说法）"},{"word":"progress","pos":"n./v.","zh":"前进；进步"},{"word":"gradient","pos":"n.","zh":"梯度；坡度"}]}},{"word":"congressional","ipa_uk":"/kɒŋˈɡresənəl/","ipa_us":"/kɑːŋˈɡresənəl/","definition_zh":"国会的；美国国会的；由国会授权的","definition_en":"relating to a congress, especially the United States Congress, or authorized by it","core_image":"一间挂着两排木牌的房间，每块牌子都写着同一座大厅的编号","scene":"走廊墙上挂满木牌，每块牌子都印着同一座大厅的座位号。A congressional committee opened the hearing on the tax bill.","sceneCN":"句中这个词指属于美国国会的（第 1 个义项：与美国国会有关的）；句意为一个国会委员会就税收法案开启了听证。图中可辨识物件：木牌、座位号、委员会名牌、听证桌、麦克风。","pos":[{"tag":"adj.","zh":"国会的；与国会有关的"},{"tag":"adj.","zh":"由国会授权的"}],"collocations":[{"phrase":"congressional committee","zh":"国会委员会"},{"phrase":"congressional hearing","zh":"国会听证"},{"phrase":"congressional district","zh":"国会选区"},{"phrase":"congressional approval","zh":"国会批准"},{"phrase":"congressional leaders","zh":"国会领袖"},{"phrase":"congressional budget office","zh":"国会预算办公室"}],"forms":[{"label":"原级","form":"congressional"},{"label":"副词","form":"congressionally"},{"label":"名词（国会）","form":"Congress"},{"label":"名词（议员）","form":"congressman"},{"label":"名词（女议员）","form":"congresswoman"}],"derivatives":[{"word":"congress","pos":"n.","zh":"国会；代表大会"},{"word":"congressman","pos":"n.","zh":"（美国）国会议员"},{"word":"congresswoman","pos":"n.","zh":"（美国）女国会议员"},{"word":"congressperson","pos":"n.","zh":"国会议员（中性说法）"},{"word":"congressionally","pos":"adv.","zh":"以国会方式"}],"senses":[{"no":"01","title":"Relating to the United States Congress","titleCN":"与美国国会有关的","definition":"concerning the American national legislature, its members or its business","definitionCN":"与美国国家立法机关、其议员或事务有关的","example":"A congressional committee opened the hearing on the tax bill.","exampleCN":"一个国会委员会就税收法案开启了听证。","why":"The adjective comes from the noun congress plus -al, and in American use the capitalised noun points to one legislature.","whyCN":"这个形容词由名词 congress 加 -al 构成，在美式用法中大写名词专指一个立法机关。"},{"no":"02","title":"Of hearings and committees","titleCN":"听证与委员会的","definition":"describing the investigative and deliberative organs through which Congress works","definitionCN":"形容国会赖以运作的调查与审议机构","example":"The congressional hearing lasted five hours.","exampleCN":"这场国会听证持续了五小时。","why":"Committee work is where most congressional business happens, so the adjective is used most often with those nouns.","whyCN":"大部分国会事务在委员会里发生，因此这个形容词最常与这类名词连用。"},{"no":"03","title":"Authorized by Congress","titleCN":"由国会授权的","definition":"approved or required by statute of Congress rather than by the executive","definitionCN":"由国会立法批准或要求，而非由行政决定","example":"The programme needs congressional approval before it can start.","exampleCN":"该计划需要国会批准才能启动。","why":"Only Congress can pass federal statutes, so its adjective marks the source of legal authority.","whyCN":"只有国会能通过联邦法规，因此这个形容词标记法律权威的来源。"},{"no":"04","title":"Of a district or seat","titleCN":"国会选区或席位的","definition":"relating to the constituency that elects a member of the House","definitionCN":"与选举众议员的选区有关的","example":"The state gained one congressional seat after the census.","exampleCN":"人口普查后这个州多了一个国会席位。","why":"Seats are counted by district, so the adjective attaches to maps and numbers.","whyCN":"席位按选区计数，因此这个形容词附着在地图与数字上。"},{"no":"05","title":"Of the Continental Congress","titleCN":"大陆会议的（历史）","definition":"historical use for the revolutionary assemblies that met before the Constitution","definitionCN":"历史用法，指制宪前召开的革命时期会议","example":"Congressional delegates signed the declaration in 1776.","exampleCN":"大陆会议的代表在 1776 年签署了宣言。","why":"American usage dates from 1776, when the word described the Continental Congress rather than the later bicameral body.","whyCN":"美式用法可追到 1776 年，当时这个词描述的是大陆会议，而非后来的两院制机构。"},{"no":"06","title":"Of any congress","titleCN":"任何代表大会的","definition":"relating to a scholarly, party or diplomatic congress","definitionCN":"与学术、政党或外交大会有关的","example":"Congressional papers from the medical meeting filled two volumes.","exampleCN":"这次医学会议的论文装满了两卷。","why":"The ending -al is general, so the adjective can serve any body called a congress.","whyCN":"词尾 -al 是通用的，因此这个形容词可用于任何被称为 congress 的机构。"},{"no":"07","title":"Of congressional procedure","titleCN":"国会程序的","definition":"describing the rules and customs by which the chamber conducts debate and votes","definitionCN":"形容议院进行辩论与表决所依的规则与惯例","example":"A congressional rule limited each speaker to five minutes.","exampleCN":"一条国会规则把每位发言者限制在五分钟。","why":"Procedure is what turns a majority into a lawful decision, so the adjective marks those rules.","whyCN":"程序是把多数变成合法决定的东西，因此这个形容词标记这些规则。"},{"no":"08","title":"Of congressional staff and resources","titleCN":"国会人员与资源的","definition":"relating to the employees, offices and budget that support the legislature","definitionCN":"与支撑立法机关运转的雇员、办公室与预算有关","example":"Congressional staff drafted most of the amendment.","exampleCN":"国会工作人员起草了大部分修正案。","why":"A modern legislature is an institution with employees, so its adjective covers the machinery behind the votes.","whyCN":"现代立法机关是有雇员的机构，因此这个形容词覆盖投票背后的机器。"}],"etymology":{"intro":{"en":"Congressional is recorded from the 1690s, from Latin congressus through congressionem plus -al. The specific American sense appears from 1776 and was at first disliked as a new coinage.","cn":"congressional 自十七世纪九十年代见于记录，由拉丁 congressus（经由 congressionem）加 -al 构成。特指美国国会的义项自 1776 年出现，起初曾被当作生造词而受排斥。"},"items":[{"era":"LATIN CONGRESSUS","en":"Congressus named a meeting or encounter, from congredi 'to come together', built on com- and gradi 'to walk'.","cn":"congressus 指会合或遭遇，出自 congredi「走到一起」，由 com- 与 gradi「走」构成。"},{"era":"LATIN CONGRESSIONEM","en":"The oblique stem congression- supplied the base to which the English ending was attached.","cn":"斜格词干 congression- 提供了英语接上词尾的基础。"},{"era":"ENGLISH 1690","en":"The adjective appears in the 1690s with the general sense 'of or pertaining to a congress'.","cn":"这个形容词在十七世纪九十年代出现，泛指「与代表大会有关的」。"},{"era":"AMERICAN SENSE 1776","en":"From 1776 it was used specifically of the Congress of the American states; some writers called the new usage barbarous.","cn":"自 1776 年起，它专门用于美国各州的国会；当时有些作者称这个新用法粗野。"},{"era":"MODERN RANGE","en":"Later it covered committees, districts, staff and procedure, since those are the parts of the institution that act.","cn":"后来它覆盖委员会、选区、人员与程序，因为这些都是该机构行动的部分。"},{"era":"APPROXIMATE DATES","en":"The form and root are documented; only the earliest citation of each sense is approximate, so nothing is marked source uncertain.","cn":"词形与词根均有记录；只有各义项的最早书证是约数，因此没有需要标为来源不确定的部分。"}]},"similar":{"note":{"en":"Group one holds the words of the congress family, which differ only by ending; group two holds other adjectives of legislative relation.","cn":"第一组是 congress 词族的词，差别只在词尾；第二组是其他表示立法关系的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"congress","ipa":"/ˈkɒŋɡres/","tag":"the noun","definition":"The legislature or the meeting itself; the adjective only describes what belongs to it.","definitionCN":"指立法机关或会议本身；形容词只描述属于它的事物。"},{"word":"congressman","ipa":"/ˈkɒŋɡresmən/","tag":"a member","definition":"A member of the United States Congress, usually of the House; it names a person.","definitionCN":"指美国国会议员，通常指众议员；它命名人。"},{"word":"congressperson","ipa":"/ˈkɒŋɡresˌpɜːsən/","tag":"neutral term","definition":"A neutral word for a member of Congress, avoiding the gender of congressman and congresswoman.","definitionCN":"指国会议员的中性说法，避开 congressman 与 congresswoman 的性别标记。"},{"word":"congressional","ipa":"/kɒŋˈɡresənəl/","tag":"this adjective","definition":"The relational adjective of congress, formed with -al; it is the entry you are reading.","definitionCN":"congress 的关系形容词，由 -al 构成；本词条即此词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"parliamentary","ipa":"/ˌpɑːləˈmentəri/","tag":"the British model","definition":"Relating to a parliament; it is the counterpart of congressional in systems where the executive sits in the assembly.","definitionCN":"指与议会有关的；在行政坐于议会的体制里，它是 congressional 的对应词。"},{"word":"legislative","ipa":"/ˈleɡɪsleɪtɪv/","tag":"lawmaking in general","definition":"Relating to lawmaking or to any legislature; it is broader than congressional and names no particular country.","definitionCN":"指与立法或任何立法机关有关的；比 congressional 宽泛，不限定国家。"},{"word":"federal","ipa":"/ˈfedərəl/","tag":"level of government","definition":"Relating to the central government of a union of states; congressional business is federal, but the words are not interchangeable.","definitionCN":"指由州组成的联邦中央政府的；国会事务属联邦层面，但两词不可互换。"},{"word":"statutory","ipa":"/ˈstætʃuːtəri/","tag":"by statute","definition":"Required or created by a written law; a congressional mandate is statutory in force, but statutory says nothing about who passed it.","definitionCN":"指由成文法规定或创设的；国会授权确实具有成文法效力，但 statutory 不说明是谁通过的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffix, the real root and the real institutional phrases.","cn":"正常联想：真实词尾、真实词根与真实的机构搭配。"},"normal":[{"en":"congress plus -al 'relating to': whatever belongs to the coming-together chamber.","cn":"congress 加 -al「与……有关」：一切属于那个「会合议院」的东西。"},{"en":"The family runs congress, congressional, congressman and congresswoman.","cn":"同族词包括 congress、congressional、congressman 与 congresswoman。"},{"en":"Fixed phrases mark the institution: congressional committee, congressional district, congressional approval.","cn":"固定搭配标出机构用法：国会委员会、国会选区、国会批准。"},{"en":"The root gradi 'to walk' also sits in progress and egress.","cn":"词根 gradi「走」也出现在 progress 与 egress 中。"},{"en":"The word was once attacked as an American barbarism, a fact worth remembering in style debates.","cn":"这个词曾被指为美式生造词，这一点在文体争论中值得一提。"}],"abstract":[{"en":"Picture a wall of nameplates, each cut to the same width.","cn":"想象一墙名牌，每块都裁成同样的宽度。"},{"en":"Picture a microphone that only switches on when a quorum is counted.","cn":"想象一只麦克风只有在法定人数点清后才通电。"},{"en":"Picture a budget line that must be signed twice, once by each house.","cn":"想象一条预算科目要签两次名，每院各一次。"}]},"examples":[{"en":"Congressional leaders met the president at the White House.","cn":"国会领袖在白宫会见了总统。"},{"en":"The congressional district was redrawn after the census.","cn":"人口普查后该国会选区被重新划分。"},{"en":"Congressional approval is needed for the sale of federal land.","cn":"出售联邦土地需要国会批准。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康-格瑞-申-诺」——「康」健的代表一起迈步（格瑞），再把「申」请写成「诺」言 → 国会的","word":"congressional"},"root":"congress + -al；congress 来自拉丁 congressus「会合」← congredi ← com- + gradi「走」。","sensesIntro":{"en":"Eight senses attach one adjective to every working part of a legislature: the body, its hearings, its authorisation, its districts, its revolutionary past, its namesake meetings, its procedure and its staff.","cn":"八个义项把同一个形容词贴到立法机关的每个工作部件上：机关本身、听证、授权、选区、革命时期的前身、同名会议、程序与人员。"},"semanticMap":{"core":{"en":"CORE IMAGE: a corridor of nameplates all bearing the same hall number.","cn":"核心意象：一条走廊的名牌，全都写着同一座大厅的编号。"},"chain":["BELONGING TO CONGRESS","COMMITTEE WORK","LEGAL AUTHORITY","DISTRICT SEAT","HISTORICAL BODY","STAFF AND RULES"],"branches":[{"senses":"01 · 06","en":"TWO CONGRESSES: the American legislature and any scholarly congress share one adjective.","cn":"两种大会：美国立法机关与任何学术大会共用一个形容词。"},{"senses":"02 · 07","en":"THE WORKING ROOM: hearings and procedure are how a chamber turns argument into decision.","cn":"工作间：听证与程序是议院把争论变成决定的方式。"},{"senses":"03 · 08","en":"AUTHORITY AND MACHINERY: statutes need staff to draft them and votes to pass them.","cn":"权威与机器：法规需要人员起草，也需要投票通过。"},{"senses":"04","en":"THE MAP: seats are counted in districts, which is why the adjective attaches to geography.","cn":"地图：席位按选区计数，所以这个形容词附着在地理上。"},{"senses":"05","en":"THE FIRST CONGRESS: the revolutionary assembly gave the word its American start.","cn":"第一届国会：革命时期的会议给了这个词美式起点。"}]},"affixes":{"intro":{"en":"Congressional is a Latin noun plus an English relational ending, and its family splits into persons, places and procedures.","cn":"congressional 是一个拉丁名词加英语关系词尾，其词族分成人物、地点与程序三支。"},"latinIntro":{"en":"Congredi and congressus supply the noun; the ending -al comes from Latin -alis and marks relation.","cn":"congredi 与 congressus 提供名词；词尾 -al 来自拉丁 -alis，标记关系。"},"items":[{"word":"congressus","structure":"congressus, congressus (m., fourth declension)","meaning":"a meeting","meaningCN":"会合；会议","example":"The noun names the gathering.","exampleCN":"这个名词命名集会。"},{"word":"congress","structure":"congressus through French","meaning":"assembly; legislature","meaningCN":"集会；立法机关","example":"Congress sits in Washington.","exampleCN":"国会在华盛顿开会。"},{"word":"congressional","structure":"congress + -al (relating to)","meaning":"relating to a congress","meaningCN":"与国会有关的","example":"The congressional record is published daily.","exampleCN":"国会议事录每日出版。"},{"word":"congressionally","structure":"congressional + -ly (adverb)","meaning":"in a congressional way","meaningCN":"以国会方式","example":"The office was congressionally mandated.","exampleCN":"该办公室由国会授权设立。"},{"word":"congressman","structure":"congress + man (person)","meaning":"a male member of Congress","meaningCN":"男国会议员","example":"The congressman voted against the bill.","exampleCN":"这位议员对该法案投了反对票。"},{"word":"congresswoman","structure":"congress + woman (person)","meaning":"a female member of Congress","meaningCN":"女国会议员","example":"The congresswoman chaired the committee.","exampleCN":"这位女议员主持该委员会。"},{"word":"congressperson","structure":"congress + person (neutral)","meaning":"a member of Congress, gender-neutral","meaningCN":"国会议员（中性）","example":"Each congressperson receives one vote.","exampleCN":"每位议员有一票。"},{"word":"-al","structure":"-al (English adjective suffix, from Latin -alis)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending also builds national and regional.","exampleCN":"这个词尾还构成 national 与 regional。"},{"word":"-ly","structure":"-ly (English adverb suffix)","meaning":"in the manner of","meaningCN":"以……方式","example":"The adverb marks the manner of an act.","exampleCN":"这个副词词尾标记行为方式。"}],"latinEntries":[{"word":"congredi","structure":"congredi, congressus sum (deponent verb, third conjugation)","meaning":"to meet, come together","meaningCN":"相遇；会合"},{"word":"congressus","structure":"congressus, congressus (m., fourth declension)","meaning":"a meeting","meaningCN":"会合；会议"},{"word":"congressio","structure":"congressio, congressionis (f., third declension)","meaning":"a meeting, encounter","meaningCN":"会合；遭遇"}],"derivatives":[{"word":"congress","pos":"n.","zh":"国会；代表大会"},{"word":"congressionally","pos":"adv.","zh":"以国会方式"},{"word":"congressman","pos":"n.","zh":"（美国）国会议员"},{"word":"congresswoman","pos":"n.","zh":"（美国）女国会议员"},{"word":"congressperson","pos":"n.","zh":"国会议员（中性说法）"}]}},{"word":"senate","ipa_uk":"/ˈsenət/","ipa_us":"/ˈsenət/","definition_zh":"参议院；（古罗马）元老院；（某些大学的）理事会","definition_en":"the upper and usually smaller chamber of a national or state legislature, or the council of elders in ancient Rome","core_image":"一圈年长者的座位围成半圆，中央留出一块空地给发言的人","scene":"半圆形座位上坐着一圈年长者，中央空地只站得下一个人。The senate approved the treaty after three days of debate.","sceneCN":"句中这个词指国家立法机关的上院（第 1 个义项：通常人数较少、审议与确认事项的上院）；句意为参议院经过三天辩论批准了该条约。图中可辨识物件：半圆座位、中央空地、发言台、条约文本、表决牌。","pos":[{"tag":"n.","zh":"参议院；上院（可数，常大写）"},{"tag":"n.","zh":"（古罗马）元老院"},{"tag":"n.","zh":"（大学等机构的）理事会；评议会"}],"collocations":[{"phrase":"the United States Senate","zh":"美国参议院"},{"phrase":"senate seat","zh":"参议院席位"},{"phrase":"the Roman Senate","zh":"古罗马元老院"},{"phrase":"senate committee","zh":"参议院委员会"},{"phrase":"confirm by the senate","zh":"经参议院确认"},{"phrase":"state senate","zh":"州参议院"}],"forms":[{"label":"复数","form":"senates"},{"label":"形容词","form":"senatorial"},{"label":"名词（参议员）","form":"senator"},{"label":"名词（参议员群体）","form":"senatorship"},{"label":"相关名词（年长者）","form":"senior"}],"derivatives":[{"word":"senator","pos":"n.","zh":"参议员"},{"word":"senatorial","pos":"adj.","zh":"参议院的；参议员的"},{"word":"senatorship","pos":"n.","zh":"参议员身份"},{"word":"senior","pos":"adj./n.","zh":"年长的；资深者"}],"senses":[{"no":"01","title":"The upper chamber of a legislature","titleCN":"立法机关的上院","definition":"the usually smaller and more deliberative house of a national or state legislature","definitionCN":"国家或州立法机关中通常人数较少、更重审议的议院","example":"The senate approved the treaty after three days of debate.","exampleCN":"参议院经过三天辩论批准了该条约。","why":"The Latin senatus was a council of elders, and the name kept that image of fewer, older, slower deliberators when modern upper houses were created.","whyCN":"拉丁 senatus 是长老会议，现代上院设立时，这个名称保留了「人数更少、更年长、更慢思量」的意象。"},{"no":"02","title":"The Roman Senate","titleCN":"古罗马元老院","definition":"the council of elders that advised and directed the Roman state","definitionCN":"为罗马国家提供建议并主导国政的长老会议","example":"The Roman senate debated the general's triumph.","exampleCN":"罗马元老院辩论了那位将军的凯旋式。","why":"The oldest sense is specifically Roman, and the word entered English about 1200 with that reference alone.","whyCN":"最老的义项专指罗马，这个词约在 1200 年进入英语时只有这一指称。"},{"no":"03","title":"The senators collectively","titleCN":"全体参议员","definition":"the members of the chamber regarded as one actor","definitionCN":"把该院成员视为一个行动者","example":"The senate was split along party lines.","exampleCN":"参议院按党派分裂。","why":"An institution acts through votes, so the name passes from the chamber to the people in it.","whyCN":"机构通过投票行动，于是名称从议院转到里面的人。"},{"no":"04","title":"The chamber or its building","titleCN":"议事厅或参议院大楼","definition":"the room or building in which the upper house meets","definitionCN":"上院开会的房间或建筑","example":"Reporters waited in the senate corridor.","exampleCN":"记者在参议院走廊等候。","why":"Metonymy lets a place carry the name of the body that meets there.","whyCN":"借代使地点承担了在那里开会之机构的名字。"},{"no":"05","title":"A state senate","titleCN":"州参议院","definition":"the upper house of a state legislature within a federation","definitionCN":"联邦制内州立法机关的上院","example":"The state senate passed its own version of the bill.","exampleCN":"州参议院通过了该法案的自己版本。","why":"Federalism repeats the model at a lower level, so the name reappears with a narrower jurisdiction.","whyCN":"联邦制在更低层级重复这个模式，于是这个名字随着更窄的管辖范围再次出现。"},{"no":"06","title":"A university senate","titleCN":"大学理事会","definition":"the governing council of a university or similar institution","definitionCN":"大学或类似机构的治理理事会","example":"The university senate approved the new faculty.","exampleCN":"大学理事会批准了新设的学院。","why":"The image of a council of senior members fits any institution that governs through its elders.","whyCN":"「资深成员组成会议」的意象，适合任何靠年长者治理的机构。"},{"no":"07","title":"A senior advisory council","titleCN":"资深顾问会议","definition":"an extended use for a body of respected elders advising a leader","definitionCN":"引申用法，指由受尊敬的长者组成、向领导人提供建议的团体","example":"The village senate settled disputes over land.","exampleCN":"村里的长老会议解决土地争端。","why":"Advice from elders is the original function, so the word can describe any such council without a legislature.","whyCN":"长者提供建议是原本的职能，因此这个词可以描述任何这类会议，而无需立法机关。"},{"no":"08","title":"The confirming and reviewing function","titleCN":"确认与复核的职能","definition":"the upper house's role of checking appointments and treaties rather than initiating them","definitionCN":"上院检查任命与条约、而不主动提出它们的角色","example":"Senate review slowed the appointment for a month.","exampleCN":"参议院的复核使这项任命拖了一个月。","why":"Upper houses were designed to slow and check, so the name can stand for that function itself.","whyCN":"上院的设计本就是放慢与检查，因此这个名字可以代表那项职能本身。"}],"etymology":{"intro":{"en":"Senate entered English about 1200 from Old French senat or Latin senatus, literally 'council of elders', from senex 'old man'. The American upper house took the name in 1775.","cn":"senate 约在 1200 年经古法语 senat 或拉丁 senatus 进入英语，字面是「长老会议」，出自 senex「老人」。美国上院于 1775 年采用此名。"},"items":[{"era":"LATIN SENEX","en":"Senex, genitive senis, meant 'old man, old'. It belongs to a reconstructed Indo-European root for 'old' that also underlies senior and senile.","cn":"senex（属格 senis）意为「老人、年老的」。它属于一个可重构的印欧语「老」词根，senior 与 senile 也由此而来。"},{"era":"LATIN SENATUS","en":"Senatus, literally 'council of elders', named the highest council of the Roman state; the abstract ending marks a body rather than one person.","cn":"senatus 字面为「长老会议」，命名罗马国家的最高会议；这个抽象词尾标记团体，而非个人。"},{"era":"ENGLISH 1200","en":"English senate first referred only to the Roman body, and from the late fourteenth century to governing councils of free cities.","cn":"英语 senate 最初只指罗马元老院，自十四世纪晚期起也指自由城市的治理会议。"},{"era":"NATIONAL UPPER HOUSES","en":"From the 1550s the word named national governing bodies, typically the upper or less numerous branch of a legislature.","cn":"自十六世纪五十年代起，这个词指国家治理机构，通常是立法机关的上院或人数较少的一院。"},{"era":"AMERICAN USE 1775","en":"The specific sense 'upper house of the United States legislature' is recorded from 1775.","cn":"「美国立法机关上院」这一特定义项自 1775 年见于记录。"},{"era":"APPROXIMATE DATES","en":"The root and the chain of forms are well documented; the reconstructed Indo-European root is a reconstruction, and the English dates are approximate first citations.","cn":"词根与词形链条记录充分；印欧语词根属重构形式，英语各年代为首见书证的约数。"}]},"similar":{"note":{"en":"Group one holds words from the Latin 'old' root, which look alike and are often confused; group two holds other names for deliberative chambers.","cn":"第一组是由拉丁「老」词根构成的词，形似且常被混淆；第二组是其他议事机构的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"senator","ipa":"/ˈsenətə/","tag":"one member","definition":"A single member of a senate, from Latin senator; the noun of person, not of body.","definitionCN":"指参议院的单个成员，出自拉丁 senator；是人物的名词，不是机构的名词。"},{"word":"senior","ipa":"/ˈsiːniə/","tag":"older or higher","definition":"Older or higher in rank, from Latin senior, the comparative of senex; it compares age or status.","definitionCN":"指年长的或级别更高的，出自拉丁 senior，即 senex 的比较级；它比较年龄或地位。"},{"word":"senile","ipa":"/ˈsiːnaɪl/","tag":"of old age","definition":"Showing the mental decline of old age, from Latin senilis; it is a medical description, not an institution.","definitionCN":"指显出老年心智衰退的，出自拉丁 senilis；是医学描述，不指机构。"},{"word":"senescent","ipa":"/sɪˈnesənt/","tag":"growing old","definition":"Becoming old, from the present participle of Latin senescere 'to grow old'; used of cells and organisms.","definitionCN":"指正在变老的，出自拉丁 senescere「变老」的现在分词；多用于细胞与生物体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"upper house","ipa":"/ˈʌpə haʊs/","tag":"structural description","definition":"The general term for the smaller chamber of a bicameral legislature; senate is one name for such a house.","definitionCN":"指两院制立法机关中较小议院的一般说法；senate 是这类议院的一个名称。"},{"word":"council","ipa":"/ˈkaʊnsəl/","tag":"advising body","definition":"A body that advises or administers; it is broader than senate and need not legislate.","definitionCN":"指提供建议或进行行政管理的机构；比 senate 宽泛，不必然立法。"},{"word":"chamber","ipa":"/ˈtʃeɪmbə/","tag":"the room or house","definition":"Either of the two houses of a legislature, or the room where one meets; it is the neutral structural word.","definitionCN":"指立法机关两院中的任一院，或某院开会的房间；是中性的结构用词。"},{"word":"parliament","ipa":"/ˈpɑːləmənt/","tag":"the whole assembly","definition":"The whole national assembly; a senate may be one part of it, as in a bicameral parliament.","definitionCN":"指整个国家议会；在两院制议会中，参议院可以是它的一部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real family and the real institutional phrases.","cn":"正常联想：真实的拉丁词根、真实词族与真实的机构搭配。"},"normal":[{"en":"senex 'old man': the council of elders, which is what the word literally says.","cn":"senex「老人」：长老会议，这正是这个词字面上说的。"},{"en":"The family runs senate, senator, senatorial, senior and senile.","cn":"同族词包括 senate、senator、senatorial、senior 与 senile。"},{"en":"Fixed phrases mark the institution: senate seat, senate committee, state senate.","cn":"固定搭配标出机构用法：参议院席位、参议院委员会、州参议院。"},{"en":"The word came into English about 1200 for Rome alone, then spread to modern upper houses.","cn":"这个词约在 1200 年进入英语时只指罗马，后来才扩展到现代上院。"},{"en":"The reconstructed Indo-European root means 'old' and also yields senior and senile.","cn":"可重构的印欧语词根意为「老」，还产生 senior 与 senile。"}],"abstract":[{"en":"Picture a semicircle of older chairs set slightly behind the younger row.","cn":"想象一圈更旧的椅子排成半圆，略微靠在那排更年轻的座位后面。"},{"en":"Picture a second key that cannot open a door by itself but can refuse to turn.","cn":"想象第二把钥匙，它不能独自开门，却能拒绝转动。"},{"en":"Picture a clock deliberately set a little slow so that nothing is decided in a hurry.","cn":"想象一只故意调慢的钟，让任何事都不被匆忙决定。"}]},"examples":[{"en":"The senate must confirm the nomination by a simple majority.","cn":"参议院须以简单多数确认这项提名。"},{"en":"A bronze tablet recorded the Roman senate's decree.","cn":"一块铜板记录了罗马元老院的法令。"},{"en":"The university senate voted to change the admissions rules.","cn":"大学理事会投票修改招生规则。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「塞-纳-特」——一群年长者「塞」满半圆座位，把意见「纳」进来再作决定，个个都很「特」别 → 参议院","word":"senate"},"root":"拉丁 senatus「长老会议」← senex（属格 senis）「老人」，属可重构的印欧语「老」词根；英语约 1200 年借入。","sensesIntro":{"en":"Eight senses follow one semicircle of elders: the Roman council, then any upper house, its members, its room, its state copies, its academic copies, any council of elders and finally the function of checking rather than initiating.","cn":"八个义项围绕一圈长者座位展开：罗马元老院，然后是任何上院、其成员、其议事厅、州级复制、大学复制、任何长老会议，最后是「检查而非发起」的职能。"},"semanticMap":{"core":{"en":"CORE IMAGE: a semicircle of older chairs with one empty space for the speaker.","cn":"核心意象：一圈年长者的座位，中央留一个空位给发言者。"},"chain":["COUNCIL OF ELDERS","ROMAN SENATE","UPPER HOUSE","MEMBERS AS ONE","STATE CHAMBER","CHECKING FUNCTION"],"branches":[{"senses":"01 · 02","en":"FROM ROME TO MODERNITY: the ancient council supplied the image that modern upper houses borrowed.","cn":"从罗马到现代：古代的长老会议提供了现代上院所借用的意象。"},{"senses":"03 · 04","en":"PERSONS AND PLACE: the members and the corridor both answer to the chamber's name.","cn":"人与地点：议员与走廊都应和着议院的名字。"},{"senses":"05","en":"FEDERAL COPY: a state repeats the model with a narrower jurisdiction.","cn":"联邦复制：州以更窄的管辖范围重复这个模式。"},{"senses":"06 · 07","en":"ELDERS ANYWHERE: a university and a village both govern through a council of senior members.","cn":"各处的长者：大学与村庄都靠资深成员组成的会议治理。"},{"senses":"08","en":"THE SLOW KEY: the upper house exists to check, delay and confirm.","cn":"慢钥匙：上院的存在就是为了检查、延迟与确认。"}]},"affixes":{"intro":{"en":"Senate rests on a Latin word for an old man, and that root spreads across words about age, rank and councils.","cn":"senate 依托一个意为「老人」的拉丁词，这个词根散布在关于年龄、地位与会议的词中。"},"latinIntro":{"en":"Senex gives senatus and senator; senior is its comparative, and senilis and senescere describe growing old.","cn":"senex 给出 senatus 与 senator；senior 是它的比较级，senilis 与 senescere 描述变老。"},"items":[{"word":"senex","structure":"senex, senis (m., third declension)","meaning":"old man; old","meaningCN":"老人；年老的","example":"The root carries age and respect together.","exampleCN":"这个词根同时带着年岁与敬重。"},{"word":"senatus","structure":"senex + -atus (collective)","meaning":"council of elders","meaningCN":"长老会议","example":"The body, not the person, takes this form.","exampleCN":"这个形式指团体，不指个人。"},{"word":"senate","structure":"senatus through Old French senat","meaning":"upper house; council","meaningCN":"上院；会议","example":"The senate met in the old hall.","exampleCN":"参议院在旧厅开会。"},{"word":"senator","structure":"senatus + -or (person)","meaning":"member of a senate","meaningCN":"参议员","example":"The senator spoke last.","exampleCN":"这位参议员最后发言。"},{"word":"senatorial","structure":"senator + -ial (relating to)","meaning":"of senators","meaningCN":"参议员的","example":"The senatorial inquiry took a year.","exampleCN":"参议院的调查花了一年。"},{"word":"senior","structure":"senex + comparative ending","meaning":"older; higher in rank","meaningCN":"年长的；资深的","example":"She is the senior partner.","exampleCN":"她是资深合伙人。"},{"word":"senile","structure":"senex + -ilis (of)","meaning":"of old age","meaningCN":"老年的","example":"The term describes age-related decline.","exampleCN":"这个词描述与年龄相关的衰退。"},{"word":"senescence","structure":"senescere + -ence (state)","meaning":"the process of growing old","meaningCN":"衰老过程","example":"Cellular senescence can halt division.","exampleCN":"细胞衰老可以停止分裂。"},{"word":"-atus","structure":"-atus (Latin collective noun ending)","meaning":"a body or office","meaningCN":"团体或职务","example":"The same ending appears in senate and electorate.","exampleCN":"同一词尾出现在 senate 与 electorate 中。"}],"latinEntries":[{"word":"senex","structure":"senex, senis (m., third declension)","meaning":"old man","meaningCN":"老人"},{"word":"senatus","structure":"senatus, senatus (m., fourth declension)","meaning":"council of elders","meaningCN":"长老会议"},{"word":"senator","structure":"senator, senatoris (m., third declension)","meaning":"member of the senate","meaningCN":"元老院成员"},{"word":"senilis","structure":"senilis, senile (adjective)","meaning":"of old age","meaningCN":"老年的"}],"derivatives":[{"word":"senator","pos":"n.","zh":"参议员"},{"word":"senatorial","pos":"adj.","zh":"参议院的；参议员的"},{"word":"senatorship","pos":"n.","zh":"参议员身份"},{"word":"senior","pos":"adj./n.","zh":"年长的；资深者"},{"word":"senile","pos":"adj.","zh":"老年衰退的"},{"word":"senescence","pos":"n.","zh":"衰老过程"}]}},{"word":"senator","ipa_uk":"/ˈsenətə/","ipa_us":"/ˈsenətər/","definition_zh":"参议员；（古罗马）元老院议员；（大学等的）理事会成员","definition_en":"a member of a senate, especially of the upper house of a national or state legislature","core_image":"一个人坐在半圆座位的边缘，胸前别着一枚写着席位编号的徽章","scene":"半圆座位的边缘坐着一个人，胸前的徽章刻着席位编号。The senator from the coastal district voted against the bill.","sceneCN":"句中这个词指参议院的成员（第 1 个义项：在参议院中任职并投票的议员）；句意为来自沿海选区的这位参议员对该法案投了反对票。图中可辨识物件：半圆座位、席位徽章、表决牌、选区地图、议事册。","pos":[{"tag":"n.","zh":"参议员（可数，常大写作头衔）"},{"tag":"n.","zh":"（古罗马）元老院议员"}],"collocations":[{"phrase":"state senator","zh":"州参议员"},{"phrase":"senior senator","zh":"资深参议员"},{"phrase":"the senator from Ohio","zh":"来自俄亥俄州的参议员"},{"phrase":"senator-elect","zh":"当选但未就职的参议员"},{"phrase":"a senator's term","zh":"参议员任期"},{"phrase":"Roman senator","zh":"罗马元老院议员"}],"forms":[{"label":"复数","form":"senators"},{"label":"阴性形式","form":"senatress"},{"label":"形容词","form":"senatorial"},{"label":"名词（机构）","form":"senate"},{"label":"名词（身份）","form":"senatorship"}],"derivatives":[{"word":"senate","pos":"n.","zh":"参议院"},{"word":"senatorial","pos":"adj.","zh":"参议员的；参议院的"},{"word":"senatorship","pos":"n.","zh":"参议员身份"},{"word":"senatress","pos":"n.","zh":"女参议员（旧称）"},{"word":"senior","pos":"adj./n.","zh":"年长的；资深者"}],"senses":[{"no":"01","title":"A member of a senate","titleCN":"参议院成员","definition":"a person who sits in an upper house and votes on laws, treaties and appointments","definitionCN":"在上院任职、对法律、条约与任命投票的人","example":"The senator from the coastal district voted against the bill.","exampleCN":"来自沿海选区的这位参议员对该法案投了反对票。","why":"Latin senator meant a member of the council of elders, so the person is named by the body before the body is named by the person.","whyCN":"拉丁 senator 指长老会议的成员，因此是先有人物之名，后有机构之名。"},{"no":"02","title":"A United States senator","titleCN":"美国参议员","definition":"one of the two members elected to represent a state in the United States Senate","definitionCN":"在美国参议院中代表一个州的两名成员之一","example":"Each state sends two senators to Washington.","exampleCN":"每个州向华盛顿派出两名参议员。","why":"American usage from 1788 made the word point to a specific federal office.","whyCN":"自 1788 年起的美国用法，使这个词指向一个特定的联邦职位。"},{"no":"03","title":"A state senator","titleCN":"州参议员","definition":"a member of the upper house of a state legislature","definitionCN":"州立法机关上院的成员","example":"The state senator chaired the education committee.","exampleCN":"这位州参议员主持教育委员会。","why":"Federalism repeats the office at a lower level, so the same title carries a narrower mandate.","whyCN":"联邦制在更低层级重复这个职位，于是同一头衔带着更窄的授权。"},{"no":"04","title":"A Roman senator","titleCN":"古罗马元老院议员","definition":"a member of the ancient Roman council of elders","definitionCN":"古罗马长老会议的成员","example":"A Roman senator wore a broad purple stripe.","exampleCN":"罗马元老院议员佩戴一条宽紫边。","why":"The oldest sense is Roman, and English borrowed the word about 1200 with that reference alone.","whyCN":"最老的义项是罗马的，英语约在 1200 年借入时只有这一指称。"},{"no":"05","title":"A university senate member","titleCN":"大学理事会成员","definition":"a member of the governing council of a university or college","definitionCN":"大学或学院治理理事会的成员","example":"The senator for the faculty of law spoke first.","exampleCN":"法学院推举的理事先发言。","why":"The model of a council of senior members fits academic governance, so the title travels there.","whyCN":"资深成员组成会议的模式适合学术治理，于是这个头衔转移过去。"},{"no":"06","title":"An elder councillor","titleCN":"长者议事会的成员（引申）","definition":"an extended use for a respected elder who advises a community","definitionCN":"引申用法，指为共同体提供建议的受尊敬长者","example":"The village senator settled the boundary dispute.","exampleCN":"村里的长老解决了边界争端。","why":"Because the root means old man, the title can still carry the simple weight of age and respect.","whyCN":"因为词根意为「老人」，这个头衔仍能带着单纯的年岁与敬重分量。"},{"no":"07","title":"The office or title","titleCN":"职位或头衔","definition":"the formal style used before a name, as in Senator Smith","definitionCN":"放在姓名前的正式称呼，如「史密斯参议员」","example":"The letter was addressed to Senator Ruiz.","exampleCN":"这封信寄给鲁伊斯参议员。","why":"An office becomes a title when it can stand before a surname, and the word then names the post rather than its holder.","whyCN":"当职位能放在姓氏前，它就变成头衔，此时这个词命名的是职位，而非任职者。"},{"no":"08","title":"A region's voice in the upper house","titleCN":"上院中代表某一地区的议员","definition":"a member regarded as the representative of a state, province or district","definitionCN":"被视为某州、省或选区代表的成员","example":"Voters treat the senator as their voice on federal spending.","exampleCN":"选民把这位参议员当作他们在联邦开支上的声音。","why":"Upper houses often represent territories rather than populations, so the office carries a regional duty.","whyCN":"上院往往代表地域而非人口，因此这个职位带着地域职责。"}],"etymology":{"intro":{"en":"Senator came into English about 1200 from Old French senator or Latin senator 'member of the senate', from senex 'old man'. American use for a federal office dates from 1788.","cn":"senator 约在 1200 年经古法语 senator 或拉丁 senator「元老院成员」进入英语，出自 senex「老人」。指美国联邦职位的用法自 1788 年起。"},"items":[{"era":"LATIN SENEX","en":"Senex, genitive senis, meant 'old man, old'. It belongs to a reconstructed Indo-European root for 'old' shared by senior and senile.","cn":"senex（属格 senis）意为「老人、年老的」。它属于一个可重构的印欧语「老」词根，senior 与 senile 共用此根。"},{"era":"LATIN SENATUS","en":"Senatus named the council of elders of the Roman state, and senator was the member of that council.","cn":"senatus 命名罗马国家的长老会议，senator 则是该会议的成员。"},{"era":"OLD FRENCH SENATOR","en":"Old French senator carried the word into English about 1200; the native English equivalent would have been elder.","cn":"古法语 senator 约在 1200 年把这个词带入英语；英语本族语的对应说法本会是 elder。"},{"era":"MODERN BODY","en":"From the late fourteenth century the word was used for members of modern governing bodies, not only of the Roman one.","cn":"自十四世纪晚期起，这个词用于现代治理机构的成员，不再只指罗马。"},{"era":"AMERICAN 1788","en":"American usage for a member of the United States Senate is recorded from 1788; the feminine senatress appears from 1731.","cn":"指美国参议院成员的用法自 1788 年见于记录；阴性形式 senatress 自 1731 年出现。"},{"era":"APPROXIMATE DATES","en":"The root word is ancient, the chain is documented, and the reconstructed Indo-European root is admittedly a reconstruction.","cn":"词根古老，词形链条有记录，而印欧语词根本身是承认的重构形式。"}]},"similar":{"note":{"en":"Group one holds words from the Latin root for 'old', easily confused with senator; group two holds other people who deliberate or represent.","cn":"第一组是由拉丁「老」词根构成的词，易与 senator 混淆；第二组是其他议事或代表的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"senate","ipa":"/ˈsenət/","tag":"the body","definition":"The council or upper house itself; senator names one of its members.","definitionCN":"指会议或上院本身；senator 指其中一名成员。"},{"word":"senior","ipa":"/ˈsiːniə/","tag":"older or higher","definition":"Older or higher in rank, the comparative of the Latin word for old; it compares people rather than naming an office.","definitionCN":"指年长的或级别更高的，是拉丁「老」一词的比较级；它比较人，不命名职位。"},{"word":"senile","ipa":"/ˈsiːnaɪl/","tag":"age-related decline","definition":"Showing the mental decline of old age; the root is the same, but the meaning has moved to medicine.","definitionCN":"指显出老年心智衰退的；词根相同，但词义已转到医学。"},{"word":"senatorial","ipa":"/ˌsenəˈtɔːriəl/","tag":"the adjective","definition":"Relating to senators or a senate; it describes the office, not the person.","definitionCN":"指与参议员或参议院有关的；描述职位，不描述人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","tag":"the broader role","definition":"An elected person who acts for a constituency; every senator is one, but not every representative sits in an upper house.","definitionCN":"指为选区行事的民选者；每个参议员都是代表，但并非每个代表都在上院。"},{"word":"legislator","ipa":"/ˈleɡɪsleɪtə/","tag":"lawmaking in general","definition":"Any member of a lawmaking body; senator is the title used in an upper house.","definitionCN":"指任何立法机关的成员；senator 是上院使用的头衔。"},{"word":"delegate","ipa":"/ˈdelɪɡət/","tag":"sent by others","definition":"A person sent with authority to act for a group; the emphasis is on being sent, not on the chamber.","definitionCN":"指受派代表某群体行事的人；强调「被派出」，不强调议院。"},{"word":"councillor","ipa":"/ˈkaʊnsələ/","tag":"local or advisory","definition":"A member of a council, often local or advisory; it is the everyday counterpart of the older senate model.","definitionCN":"指理事会成员，常为地方或顾问性质；是较老的长老会议模式在日常中的对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real family and the real titles.","cn":"正常联想：真实的拉丁词根、真实词族与真实头衔用法。"},"normal":[{"en":"senex 'old man' plus the person ending: one old councillor, then one member of the upper house.","cn":"senex「老人」加人物词尾：先是长老会议的一员，后是上院的一员。"},{"en":"The family runs senate, senator, senatorial, senatorship and senior.","cn":"同族词包括 senate、senator、senatorial、senatorship 与 senior。"},{"en":"Fixed phrases mark the role: state senator, senior senator, senator-elect.","cn":"固定搭配标出角色：州参议员、资深参议员、当选未就职的参议员。"},{"en":"The title can stand before a name, as in Senator Ruiz.","cn":"这个头衔可以放在姓名前，如「鲁伊斯参议员」。"},{"en":"English had a native equivalent in elder, which shows how old the idea is.","cn":"英语本有本族对应词 elder，可见这个观念之老。"}],"abstract":[{"en":"Picture one chair at the edge of a semicircle, marked with a number rather than a name.","cn":"想象半圆边缘的一把椅子，上面刻着号码而不是名字。"},{"en":"Picture a badge that opens one corridor but not another.","cn":"想象一枚徽章能开一条走廊的门，却开不了另一条。"},{"en":"Picture a voice that speaks for a coastline it has never walked.","cn":"想象一个声音替一段它从未走过的海岸线说话。"}]},"examples":[{"en":"The senator questioned the nominee for two hours.","cn":"这位参议员对获提名者质询了两小时。"},{"en":"A Roman senator could be removed by the censors.","cn":"罗马元老院议员可能被监察官除名。"},{"en":"The faculty senator reported on the budget.","cn":"教师理事汇报了预算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「塞-纳-特」——被「塞」进半圆座位、替大家把意见「纳」进来的人，地位很「特」别 → 参议员","word":"senator"},"root":"拉丁 senator「元老院成员」← senatus「长老会议」← senex（属格 senis）「老人」；词根属可重构的印欧语「老」词根。","sensesIntro":{"en":"Eight senses follow one person: a member of an upper house, an American federal senator, a state senator, a Roman elder, a university councillor, a village elder, a title and a regional voice.","cn":"八个义项围绕同一个人展开：上院成员、美国联邦参议员、州参议员、罗马元老、大学理事、村庄长老、一个头衔、一个地域的声音。"},"semanticMap":{"core":{"en":"CORE IMAGE: one chair at the rim of a semicircle, marked with a seat number.","cn":"核心意象：半圆边缘的一把椅子，刻着席位号。"},"chain":["COUNCIL MEMBER","ROMAN ELDER","US SENATOR","STATE SENATOR","UNIVERSITY COUNCILLOR","REGIONAL VOICE"],"branches":[{"senses":"01 · 07","en":"PERSON AND POST: the same word names the holder and the title printed before a surname.","cn":"人与职位：同一个词既命名任职者，也命名印在姓氏前的头衔。"},{"senses":"02 · 03","en":"TWO LEVELS: a federal and a state senator hold the same title with different mandates.","cn":"两个层级：联邦与州参议员头衔相同，授权不同。"},{"senses":"04 · 06","en":"FROM ROME TO THE VILLAGE: the elder of a council survives wherever respected age still governs.","cn":"从罗马到村庄：只要受尊敬的年岁仍在治理，长老会议的成员就存在。"},{"senses":"05","en":"THE FACULTY: academic governance borrows the council of seniors.","cn":"学院：学术治理借用了资深成员会议的模式。"},{"senses":"08","en":"THE DISTRICT: upper houses represent territory, so the member speaks for a place.","cn":"选区：上院代表地域，因此成员替一个地方说话。"}]},"affixes":{"intro":{"en":"Senator is a Latin person-noun from an old-age root, and the same pieces build senate, senatorial and senior.","cn":"senator 是一个出自「年老」词根的拉丁人物名词，同样的构件构成 senate、senatorial 与 senior。"},"latinIntro":{"en":"Senex gives senatus 'council' and senator 'member'; senior is its comparative and senilis describes old age.","cn":"senex 给出 senatus「会议」与 senator「成员」；senior 是比较级，senilis 描述老年。"},"items":[{"word":"senex","structure":"senex, senis (m., third declension)","meaning":"old man","meaningCN":"老人","example":"The root carries age and authority together.","exampleCN":"这个词根同时带着年岁与权威。"},{"word":"senatus","structure":"senex + -atus (collective)","meaning":"council of elders","meaningCN":"长老会议","example":"The council lent its name to the modern house.","exampleCN":"这个会议把名字借给了现代议院。"},{"word":"senator","structure":"senatus + -or (person)","meaning":"member of the senate","meaningCN":"元老院成员","example":"The senator rose to speak.","exampleCN":"这位参议员起身发言。"},{"word":"senate","structure":"senatus through Old French","meaning":"upper house","meaningCN":"上院","example":"The senate adjourned.","exampleCN":"参议院休会。"},{"word":"senatorial","structure":"senator + -ial (relating to)","meaning":"of senators","meaningCN":"参议员的","example":"The senatorial election drew little attention.","exampleCN":"这次参议员选举没引起多少注意。"},{"word":"senatorship","structure":"senator + -ship (office)","meaning":"the office of senator","meaningCN":"参议员职位","example":"She held the senatorship for twelve years.","exampleCN":"她担任参议员十二年。"},{"word":"senior","structure":"senex + comparative ending","meaning":"older, higher in rank","meaningCN":"年长的；资深的","example":"The senior senator spoke first.","exampleCN":"资深参议员先发言。"},{"word":"senile","structure":"senex + -ilis (of)","meaning":"of old age","meaningCN":"老年的","example":"The word moved from age to medicine.","exampleCN":"这个词从年龄义转到医学义。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who acts or belongs","meaningCN":"行事或归属的人","example":"The ending marks the person rather than the body.","exampleCN":"这个词尾标记人，不标记机构。"}],"latinEntries":[{"word":"senex","structure":"senex, senis (m., third declension)","meaning":"old man","meaningCN":"老人"},{"word":"senatus","structure":"senatus, senatus (m., fourth declension)","meaning":"council of elders","meaningCN":"长老会议"},{"word":"senator","structure":"senator, senatoris (m., third declension)","meaning":"member of the senate","meaningCN":"元老院成员"}],"derivatives":[{"word":"senate","pos":"n.","zh":"参议院"},{"word":"senatorial","pos":"adj.","zh":"参议员的"},{"word":"senatorship","pos":"n.","zh":"参议员职位"},{"word":"senatress","pos":"n.","zh":"女参议员（旧称）"},{"word":"senior","pos":"adj./n.","zh":"年长的；资深者"}]}},{"word":"court","ipa_uk":"/kɔːt/","ipa_us":"/kɔːrt/","definition_zh":"法院；法庭；宫廷；庭院；球场；求爱；招致（风险）","definition_en":"a place where legal cases are heard, the judges who hear them, the household of a monarch, an enclosed yard, a playing surface, or the act of seeking favour","core_image":"一圈围墙把一片空地围住，围墙上开着一扇门，门内有人审事、有人议事、有人打球","scene":"一圈围墙围住一片空地，门口站着守门人。The court heard the appeal in a room with no windows.","sceneCN":"句中这个词指审理案件的法院（第 1 个义项：审理法律案件、由法官主持的司法机构）；句意为法院在一间没有窗的房间里审理了上诉。图中可辨识物件：围墙、院门、审判桌、球场白线、王室徽记。","pos":[{"tag":"n.","zh":"法院；法庭；宫廷；庭院；球场"},{"tag":"v.","zh":"求爱；讨好；招致（危险、批评）"}],"collocations":[{"phrase":"court of law","zh":"法院"},{"phrase":"the high court","zh":"高等法院"},{"phrase":"at court","zh":"在宫廷里"},{"phrase":"tennis court","zh":"网球场"},{"phrase":"court danger","zh":"招致危险"},{"phrase":"court a voter","zh":"争取选民"},{"phrase":"court of public opinion","zh":"舆论法庭"}],"forms":[{"label":"复数","form":"courts"},{"label":"三单（he/she/it）","form":"courts"},{"label":"过去式","form":"courted"},{"label":"过去分词","form":"courted"},{"label":"现在分词","form":"courting"},{"label":"名词（求爱；庭院）","form":"courtship"}],"derivatives":[{"word":"courtesy","pos":"n.","zh":"礼貌；好意"},{"word":"courteous","pos":"adj.","zh":"有礼的"},{"word":"courtier","pos":"n.","zh":"廷臣"},{"word":"courtyard","pos":"n.","zh":"庭院"},{"word":"courtship","pos":"n.","zh":"求爱期"},{"word":"courtroom","pos":"n.","zh":"法庭"}],"senses":[{"no":"01","title":"A judicial tribunal","titleCN":"审理案件的法院","definition":"an institution with authority to hear and decide legal cases","definitionCN":"有权审理并裁决法律案件的机构","example":"The court heard the appeal in a room with no windows.","exampleCN":"法院在一间没有窗的房间里审理了上诉。","why":"The earliest courts were held in the sovereign's presence, so the word for the ruler's surroundings became the word for justice.","whyCN":"最早的审判在君主面前举行，于是「统治者周围」的词变成了「司法」的词。"},{"no":"02","title":"The courthouse or courtroom","titleCN":"法院大楼或法庭","definition":"the building or room where cases are heard","definitionCN":"审理案件所在的建筑或房间","example":"A crowd waited outside the court.","exampleCN":"一群人在法院外等候。","why":"Place and institution share a name in English, so the building answers to the same word as the tribunal.","whyCN":"英语里地点与机构常共用一个名字，因此大楼与审判机构用同一个词。"},{"no":"03","title":"The judges collectively","titleCN":"全体法官","definition":"the judge or panel of judges deciding a case","definitionCN":"裁决某案的法官或法官团","example":"The court was divided two to one.","exampleCN":"法官团以二比一分歧。","why":"A tribunal acts through its members, so the name slides from the institution to the bench.","whyCN":"审判机构通过其成员行动，于是名字从机构滑向法官席。"},{"no":"04","title":"A royal court","titleCN":"宫廷；王室","definition":"the household and entourage of a monarch","definitionCN":"君主的家眷与随从群体","example":"The painter spent ten years at court.","exampleCN":"这位画家在宫廷待了十年。","why":"This is the original sense: the enclosed space where a sovereign holds state, and the people around it.","whyCN":"这是本义：君主临朝所在的围合空间，以及围绕他的人。"},{"no":"05","title":"An enclosed yard","titleCN":"围起来的院子","definition":"a space enclosed by walls or buildings, as a courtyard","definitionCN":"由墙或建筑围起来的空间，如庭院","example":"The children played in the back court.","exampleCN":"孩子们在后院玩耍。","why":"The Latin word meant an enclosed yard, and that physical sense survives beside all the institutional ones.","whyCN":"拉丁词本指围起来的院子，这个物理义在所有机构义旁边留存下来。"},{"no":"06","title":"A playing surface","titleCN":"球场","definition":"a marked level area on which a ball game is played","definitionCN":"打球用的、划了线的平整场地","example":"The tennis court was wet after the rain.","exampleCN":"雨后网球场是湿的。","why":"The sense began with tennis in the sixteenth century: an enclosed level plot, exactly the old yard.","whyCN":"这一义在十六世纪从网球开始：一块围起来的平整地块，正是旧日的院子。"},{"no":"07","title":"To woo","titleCN":"求爱；追求","definition":"to try to win someone's love or favour by attention and flattery","definitionCN":"以殷勤与奉承争取某人的爱意或好感","example":"He courted her for two years before they married.","exampleCN":"他们结婚前，他追求了她两年。","why":"The verb comes from the behaviour of people at court, where favour is won by attentiveness.","whyCN":"这个动词出自宫廷里的行为方式：在宫廷里，好感靠殷勤周到赢得。"},{"no":"08","title":"To invite risk or trouble","titleCN":"招致风险或麻烦","definition":"to act in a way that makes danger, criticism or failure likely","definitionCN":"以某种方式行事，使危险、批评或失败易于发生","example":"The company courted controversy with its new advert.","exampleCN":"这家公司因新广告招来争议。","why":"Seeking favour and seeking danger use the same verb: both mean actively going after a response.","whyCN":"求好感与招危险用同一个动词：两者都是主动去争取一种回应。"}],"etymology":{"intro":{"en":"Court came into English in the late twelfth century from Old French cort, from Latin cortem, accusative of cohors 'enclosed yard'. The same Latin word also named a cohort of soldiers.","cn":"court 于十二世纪晚期从古法语 cort 进入英语，出自拉丁 cohors「围起来的院子」的宾格 cortem。同一个拉丁词也指一队士兵。"},"items":[{"era":"LATIN COHORS","en":"Cohors meant an enclosed yard and, by extension, the company of soldiers quartered in it. It is generally taken to be com- 'together' plus a stem related to hortus 'garden, plot'.","cn":"cohors 指围起来的院子，引申指驻扎其中的一队士兵。一般认为它由 com-「共同」加一个与 hortus「园圃、地块」相关的词干构成。"},{"era":"PIE ENCLOSURE","en":"The second element is referred to a reconstructed Indo-European root meaning 'to grasp, enclose', which also underlies yard and garden words.","cn":"第二个构件被追溯到一条可重构的印欧语词根，意为「抓住、围合」，yard 与 garden 一类词也由此而来。"},{"era":"OLD FRENCH CORT","en":"Old French cort meant the king's court and princely residence; it entered English in the late twelfth century as a formal assembly held by a sovereign.","cn":"古法语 cort 指国王的宫廷与君主居所；它在十二世纪晚期进入英语，指君主举行的正式集会。"},{"era":"LEGAL SENSE 1300","en":"Because early courts of justice were held before the sovereign, the word took the sense of a tribunal about 1300, along with the hall where justice was done.","cn":"由于早期审判在君主面前举行，这个词约在 1300 年取得审判机构的义项，同时也指审案的厅堂。"},{"era":"YARD AND GAME","en":"The physical sense 'enclosed space' survives as courtyard, and from the 1510s the word named the smooth plot used for tennis, then for other ball games.","cn":"「围合空间」这一物理义以 courtyard 留存；自十六世纪一十年代起，这个词指网球用的平整场地，后也指其他球类场地。"},{"era":"THE VERB 1570","en":"The verb 'to court' is recorded from the 1570s, first for amorous attention and then for any attempt to win favour or invite a response.","cn":"动词「求爱」自十六世纪七十年代见于记录，先指爱慕殷勤，后指任何争取好感或招致回应的举动。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin yard-word, which look and sound close; group two holds institutions and places that hear cases.","cn":"第一组是由同一个拉丁「院子」词构成的词，形音都近；第二组是审理案件的机构与场所。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cohort","ipa":"/ˈkəʊhɔːt/","tag":"the same Latin word","definition":"A group of soldiers, or a group of people sharing a trait; it is the direct Latin descendant, while court went through French.","definitionCN":"指一队士兵，或共享某特征的一群人；它是拉丁原词直系后代，而 court 经法语而来。"},{"word":"courtyard","ipa":"/ˈkɔːtjɑːd/","tag":"the physical sense","definition":"An enclosed area next to a building; it is court plus yard, the old meaning written out twice.","definitionCN":"指建筑旁围起来的空地；是 court 加 yard，等于把旧义写了两遍。"},{"word":"courteous","ipa":"/kɜːˈtiːəs/","tag":"court behaviour","definition":"Polite and well-mannered, from Old French curteis 'having courtly bearing'; politeness was the style of the court.","definitionCN":"指有礼有节的，出自古法语 curteis「有宫廷风范的」；礼貌本是宫廷的作风。"},{"word":"courtier","ipa":"/ˈkɔːtiə/","tag":"a person at court","definition":"An attendant at a royal court; the ending marks the person where court marks the place.","definitionCN":"指王室宫廷的侍从；词尾标记人，court 标记场所。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tribunal","ipa":"/ˈtrɪbjuːnəl/","tag":"formal deciding body","definition":"A body appointed to decide a particular dispute or class of cases; it is narrower and more specialised than court.","definitionCN":"指为裁决特定争议或某类案件而设的机构；比 court 更窄、更专门。"},{"word":"bench","ipa":"/bentʃ/","tag":"the judges","definition":"The judges collectively, or the seat they occupy; it names the persons where court names the institution.","definitionCN":"指全体法官或他们的席位；court 命名机构，bench 命名人。"},{"word":"judiciary","ipa":"/ˈdʒuːdɪʃiəri/","tag":"the whole branch","definition":"The entire system of judges and courts in a state; court is one unit inside it.","definitionCN":"指一国法官与法院的整体系统；court 是其中的一个单位。"},{"word":"forum","ipa":"/ˈfɔːrəm/","tag":"public arena","definition":"A public place for discussion or judgment, literally the Roman market square; it is figurative for court in phrases like the court of public opinion.","definitionCN":"指供讨论或评判的公共场所，字面是罗马的市场广场；在「舆论法庭」一类说法里是 court 的比喻对应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin word, the real family and the real fixed phrases.","cn":"正常联想：真实的拉丁词、真实词族与真实的固定搭配。"},"normal":[{"en":"Latin cohors 'enclosed yard': a wall around a plot, which becomes a palace, a tribunal and a tennis court.","cn":"拉丁 cohors「围起来的院子」：围住一块地的墙，后来变成宫殿、法庭与网球场。"},{"en":"The family runs court, courtship, courteous, courtesy, courtier and courtyard.","cn":"同族词包括 court、courtship、courteous、courtesy、courtier 与 courtyard。"},{"en":"Fixed phrases mark every sense: court of law, at court, tennis court, court danger.","cn":"固定搭配标出各义：法院、在宫廷、网球场、招致危险。"},{"en":"Cohort is the same Latin word borrowed directly, so the two are relatives.","cn":"cohort 是同一个拉丁词直接借入，因此二者是同族。"},{"en":"The verb is from the behaviour of people at court, where favour is won by attention.","cn":"动词出自宫廷里人的行为方式：好感靠殷勤赢得。"}],"abstract":[{"en":"Picture a wall with one gate, and the same gate lets in petitioners, courtiers and tennis players.","cn":"想象一堵墙只有一扇门，同一扇门放进请愿者、廷臣与网球手。"},{"en":"Picture a room where the judge sits in the place once kept for a throne.","cn":"想象一间屋子，法官坐的位置曾是留给王座的。"},{"en":"Picture someone walking toward a fire on purpose, calling it a courtesy.","cn":"想象一个人故意走向火堆，却把这叫作战殷勤。"}]},"examples":[{"en":"The court ruled that the search was unlawful.","cn":"法院裁定该搜查不合法。"},{"en":"She courted the rural vote with promises about clinics.","cn":"她以建诊所的承诺争取乡村选票。"},{"en":"The old court is now a public garden.","cn":"旧日的庭院如今是公园。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「考-特」——一堵围墙「考」察着里面的人，院门很「特」别：审案的、议事的、打球的都从这里进 → 法院/庭院","word":"court"},"root":"古法语 cort ← 拉丁 cohors（宾格 cortem）「围起来的院子」= com-（共同）+ 与 hortus「园圃」相关的词干；更深可追至可重构的印欧语「抓住、围合」词根。","sensesIntro":{"en":"Eight senses all sit inside one wall: the yard becomes a palace, the palace becomes a tribunal, the tribunal becomes its building, its judges, then the same walled plot becomes a tennis court, and finally the verb describes the attentiveness that wins favour or invites trouble.","cn":"八个义项都待在同一堵墙里：院子变成宫殿，宫殿变成审判机构，机构再变成大楼与法官；同一个围合地块又变成网球场；最后动词描述那种「争取好感」或「招来麻烦」的殷勤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walled plot with one gate, used for state, for judgment and for play.","cn":"核心意象：一块有围墙和一道门的场地，用于临朝、审判与游戏。"},"chain":["ENCLOSED YARD","ROYAL HOUSEHOLD","JUDICIAL BODY","COURTHOUSE","THE JUDGES","PLAYING SURFACE"],"branches":[{"senses":"01 · 04","en":"POWER TO JUSTICE: the sovereign's surroundings became the place where law is spoken.","cn":"从权力到司法：君主周围的环境变成了宣法之地。"},{"senses":"02 · 03","en":"PLACE AND PERSONS: the building and the bench share the institution's name.","cn":"地点与人：大楼与法官席共用机构的名字。"},{"senses":"05 · 06","en":"THE OLD YARD TWICE: a courtyard and a tennis court are the same enclosed plot at different scales.","cn":"旧院子的两次出现：庭院与网球场是同一块围合地在不同尺度上。"},{"senses":"07","en":"COURT BEHAVIOUR: winning favour by attention comes straight from life at court.","cn":"宫廷举止：靠殷勤赢得好感，直接来自宫廷生活。"},{"senses":"08","en":"INVITED RESPONSE: the same pursuit can aim at love or at trouble.","cn":"招来的回应：同一种追求，可以指向爱情，也可以指向麻烦。"}]},"affixes":{"intro":{"en":"Court is a short Latin-derived word with a large family, and its pieces mostly come from French rather than from a prefix and root.","cn":"court 是一个简短的拉丁来源词，词族很大，其构件多来自法语，而非某前缀加某词根。"},"latinIntro":{"en":"Latin cohors 'enclosed yard' gave court through French and cohort directly; French endings then built courteous, courtier and courtship.","cn":"拉丁 cohors「围起来的院子」经法语给出 court，并直接给出 cohort；法语词尾再构成 courteous、courtier 与 courtship。"},"items":[{"word":"cohors","structure":"cohors, cohortis (f., third declension)","meaning":"enclosed yard; company of soldiers","meaningCN":"围起来的院子；一队士兵","example":"The Latin word named both a space and the men in it.","exampleCN":"这个拉丁词既命名空间，也命名其中的人。"},{"word":"cort","structure":"cort (Old French noun)","meaning":"king's court; princely residence","meaningCN":"国王宫廷；君主居所","example":"Old French carried the word into English.","exampleCN":"古法语把这个词带进英语。"},{"word":"court","structure":"cort + English spelling","meaning":"tribunal; palace; yard","meaningCN":"法院；宫廷；庭院","example":"The court sits at ten.","exampleCN":"法院十点开庭。"},{"word":"courteous","structure":"court + -eous (having the quality of)","meaning":"polite, courtly","meaningCN":"有礼的；有宫廷风范的","example":"The clerk was courteous to every caller.","exampleCN":"这位职员对每位来电者都很客气。"},{"word":"courtesy","structure":"courteous + -y (state)","meaning":"politeness","meaningCN":"礼貌","example":"He bowed out of courtesy.","exampleCN":"他出于礼貌退场。"},{"word":"courtier","structure":"court + -ier (person)","meaning":"attendant at court","meaningCN":"廷臣","example":"A courtier carried the message.","exampleCN":"一名廷臣传递了消息。"},{"word":"courtship","structure":"court + -ship (state or activity)","meaning":"the act of wooing","meaningCN":"求爱","example":"Their courtship lasted a year.","exampleCN":"他们的求爱持续了一年。"},{"word":"courtyard","structure":"court + yard (enclosed ground)","meaning":"enclosed area by a building","meaningCN":"庭院","example":"The courtyard was full of snow.","exampleCN":"庭院里积满了雪。"},{"word":"courtroom","structure":"court + room","meaning":"the room where cases are heard","meaningCN":"法庭","example":"The courtroom was silent.","exampleCN":"法庭里一片寂静。"},{"word":"cohort","structure":"cohors borrowed directly","meaning":"a band of soldiers","meaningCN":"一队士兵","example":"A cohort marched through the gate.","exampleCN":"一队士兵穿过大门。"}],"latinEntries":[{"word":"cohors","structure":"cohors, cohortis (f., third declension)","meaning":"enclosed yard; cohort","meaningCN":"围起来的院子；步兵队"},{"word":"cors","structure":"cors, cortis (f., third declension, variant form)","meaning":"yard, enclosure","meaningCN":"院子；围地"},{"word":"hortus","structure":"hortus, horti (m., second declension)","meaning":"garden, plot","meaningCN":"园圃；地块"}],"derivatives":[{"word":"courtesy","pos":"n.","zh":"礼貌；好意"},{"word":"courteous","pos":"adj.","zh":"有礼的"},{"word":"courtier","pos":"n.","zh":"廷臣"},{"word":"courtship","pos":"n.","zh":"求爱期"},{"word":"courtyard","pos":"n.","zh":"庭院"},{"word":"courtroom","pos":"n.","zh":"法庭"}]}},{"word":"election","ipa_uk":"/ɪˈlekʃən/","ipa_us":"/ɪˈlekʃən/","definition_zh":"选举；投票；当选；（神学）神的拣选","definition_en":"the process of choosing a person for office by voting, the event at which this happens, or the act of choosing","core_image":"一只木箱封着口，箱前的人排成一列，每人手里捏着一张折好的纸","scene":"木箱的封口前，人们排成一列，每人手里捏着一张折好的纸。The election will be decided by three northern districts.","sceneCN":"句中这个词指通过投票选择任职者的过程（第 1 个义项：以投票方式选出担任公职者的程序）；句意为这场选举将由北部的三个选区决定。图中可辨识物件：投票箱、折好的选票、排队的人、监票员、计票板。","pos":[{"tag":"n.","zh":"选举；投票（可数或不可数）"},{"tag":"n.","zh":"当选；被选中的结果"},{"tag":"n.","zh":"（神学）拣选"}],"collocations":[{"phrase":"general election","zh":"大选"},{"phrase":"win the election","zh":"赢得选举"},{"phrase":"call an election","zh":"宣布举行选举"},{"phrase":"election result","zh":"选举结果"},{"phrase":"by election","zh":"补选"},{"phrase":"the election of a president","zh":"总统的选举"}],"forms":[{"label":"复数","form":"elections"},{"label":"动词","form":"elect"},{"label":"名词（选民）","form":"elector"},{"label":"形容词","form":"electoral"},{"label":"形容词（可选择的）","form":"elective"}],"derivatives":[{"word":"elect","pos":"v./adj.","zh":"选举；当选而尚未就职的"},{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electoral","pos":"adj.","zh":"选举的"},{"word":"electorate","pos":"n.","zh":"全体选民"},{"word":"elective","pos":"adj./n.","zh":"选举产生的；选修课"},{"word":"electioneer","pos":"v.","zh":"从事竞选活动"}],"senses":[{"no":"01","title":"The voting process","titleCN":"以投票选择任职者的过程","definition":"the procedure by which people choose a candidate for office by casting votes","definitionCN":"人们通过投票选出任职者的程序","example":"The election will be decided by three northern districts.","exampleCN":"这场选举将由北部的三个选区决定。","why":"The Latin verb eligere means 'to pick out', so the noun is literally a picking out of one person from several.","whyCN":"拉丁动词 eligere 意为「挑出」，因此这个名词字面上就是从若干人中挑出一个。"},{"no":"02","title":"The voting event","titleCN":"投票日或投票活动","definition":"the day or occasion on which votes are cast","definitionCN":"进行投票的那一天或那场活动","example":"Polling stations open at seven on election day.","exampleCN":"选举日投票站七点开门。","why":"A process needs a date, and English uses the same noun for the procedure and for the occasion.","whyCN":"程序需要一个日期，英语便用同一个名词既指程序也指那场活动。"},{"no":"03","title":"The contest as a whole","titleCN":"整场选战","definition":"the campaign and rivalry leading to the vote, treated as a single contest","definitionCN":"把通往投票的竞选与竞争视为一场比赛","example":"The election was fought over health care.","exampleCN":"这场选举围绕医疗保健展开。","why":"Reporters speak of an election as a race, because the result is a single win or loss.","whyCN":"记者把选举说成一场赛跑，因为结果只有输赢。"},{"no":"04","title":"A particular instance","titleCN":"某一场具体选举","definition":"one countable vote, such as a general, local or by-election","definitionCN":"一次可数的投票，如大选、地方选举或补选","example":"She won three elections in a row.","exampleCN":"她连续赢了三场选举。","why":"Because votes recur, the noun takes a plural and counts occasions.","whyCN":"由于投票反复举行，这个名词有复数，用来数场次。"},{"no":"05","title":"Divine election","titleCN":"神的拣选（神学）","definition":"the theological doctrine that God chooses certain people for salvation","definitionCN":"神拣选某些人得救的神学学说","example":"The sermon dwelt on election and grace.","exampleCN":"这篇布道详述拣选与恩典。","why":"Choosing is the shared idea: God picks out, as voters pick out, and the older theological sense uses the same verb.","whyCN":"共同点是「挑选」：神挑出人，正如选民挑出人，较早的神学义用的是同一个动词。"},{"no":"06","title":"The act of choosing","titleCN":"选择这一动作（古旧用法）","definition":"archaic or formal use for making a choice between options","definitionCN":"古旧或正式用法，指在若干选项之间作出选择","example":"He made a free election of his course.","exampleCN":"他自由选择了自己的道路。","why":"Before it meant a ballot, the word simply meant choice, and that plain sense survives in formal writing.","whyCN":"在指投票之前，这个词只表示选择，这个朴素义在正式写作中留存。"},{"no":"07","title":"A legal choice between remedies","titleCN":"法律上在救济方式间的选择","definition":"the formal choice of one legal remedy or procedure rather than another","definitionCN":"在若干法律救济或程序中选择其一的形式行为","example":"The claim was barred by an election of remedies.","exampleCN":"该请求因已作救济选择而受阻。","why":"Law keeps the old sense of choice and uses it for a binding decision between procedures.","whyCN":"法律保留了「选择」的旧义，并用它指在程序之间作出的有约束力的决定。"},{"no":"08","title":"The result of being elected","titleCN":"当选的结果","definition":"the outcome of being chosen for office, as in the election of a candidate","definitionCN":"被选任公职的结果，如某位候选人的当选","example":"His election surprised the party's own pollsters.","exampleCN":"他的当选连本党民调人员都感到意外。","why":"English often names an event by its result, so the word can mean the fact of having won.","whyCN":"英语常用结果来命名事件，因此这个词可以指「已经胜出」这一事实。"}],"etymology":{"intro":{"en":"Election entered English about 1300 from Anglo-French eleccioun and Latin electio, from eligere 'to pick out', built on ex- 'out' and legere 'to choose, gather'. The root is legere, not lex 'law'.","cn":"election 约在 1300 年经盎格鲁法语 eleccioun 与拉丁 electio 进入英语，出自 eligere「挑出」，由 ex-「出」与 legere「选择、收集」构成。其词根是 legere，不是 lex「法律」。"},"items":[{"era":"LATIN LEGERE","en":"Legere meant 'to gather, to pick, to read', from a reconstructed Indo-European root for collecting. It also yields legible, lecture and legend.","cn":"legere 意为「收集、挑选、读」，出自一条可重构的印欧语「收集」词根。它还产生 legible、lecture 与 legend。"},{"era":"LATIN ELIGERE","en":"Ex- 'out' plus legere produced eligere 'to pick out, select', the verb behind election and elect.","cn":"ex-「出」加 legere 构成 eligere「挑出、选出」，即 election 与 elect 背后的动词。"},{"era":"LATIN ELECTIO","en":"Electio named the act of choosing, whether by one person or by a body of electors.","cn":"electio 命名选择的动作，选者可以是一个人，也可以是一群选民。"},{"era":"ENGLISH 1300","en":"English election first covered both the act of choosing a person for office and the formal vote by an established procedure.","cn":"英语 election 最初同时涵盖「选人任职」与「按既定程序正式投票」。"},{"era":"THEOLOGICAL SENSE","en":"The sense 'God's choice of someone' is recorded from the late fourteenth century, and it remains the technical term in theology.","cn":"「神拣选某人」这一义项自十四世纪晚期见于记录，至今仍是神学的专用说法。"},{"era":"MODERN CAMPAIGN","en":"The modern sense of a public contest with campaigns and polling belongs to the nineteenth century and to the growth of mass electorates.","cn":"带竞选活动与民调的现代选战义，属于十九世纪与大众选民兴起之后。"}]},"similar":{"note":{"en":"Group one holds words from legere 'to choose, read', which share letters with the law words but not a root; group two holds words for the act and instruments of voting.","cn":"第一组是出自 legere「选择、读」的词，与法律词族共有字母却不同根；第二组指投票的行为与工具。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"elect","ipa":"/ɪˈlekt/","tag":"the verb","definition":"To choose by vote; it is the action from which election is formed, and it also means 'chosen but not yet installed'.","definitionCN":"指以投票选出；它是构成 election 的动作，也指「已选出但尚未就职」。"},{"word":"eligible","ipa":"/ˈelɪdʒəbəl/","tag":"able to be chosen","definition":"Qualified to be chosen, from eligere; it describes a qualification, not a vote.","definitionCN":"指有资格被选，出自 eligere；描述资格，不描述投票。"},{"word":"elite","ipa":"/eɪˈliːt/","tag":"the chosen few","definition":"A selected group of the best or most powerful, from French élite and the same choosing verb.","definitionCN":"指被挑选出的最优秀或最有权力的一群，出自法语 élite 与同一个「选择」动词。"},{"word":"legible","ipa":"/ˈledʒəbəl/","tag":"the reading sense","definition":"Able to be read, from legere in its reading sense; it looks like the election family but has no political meaning.","definitionCN":"指可读的，出自 legere 的「读」义；形似选举词族，却无政治含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vote","ipa":"/vəʊt/","tag":"the single act","definition":"A formal expression of preference, or the right to make it; an election is made of many votes.","definitionCN":"指正式表达偏好，或表达该偏好的权利；一场选举由许多张选票组成。"},{"word":"ballot","ipa":"/ˈbælət/","tag":"the paper or the method","definition":"The paper used to vote, or the secret method of voting; it names the instrument rather than the whole process.","definitionCN":"指投票用的纸，或秘密投票的方式；命名工具，而非整个程序。"},{"word":"poll","ipa":"/pəʊl/","tag":"the count or the survey","definition":"The counting of votes, the place of voting, or a survey of opinion; it is narrower than election.","definitionCN":"指计票、投票地点，或民意调查；比 election 窄。"},{"word":"referendum","ipa":"/ˌrefəˈrendəm/","tag":"a vote on a question","definition":"A direct vote by the electorate on a specific proposal rather than on a candidate.","definitionCN":"指选民就某项具体提案而非候选人进行的直接投票。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real choosing root, the real family and the real political phrases.","cn":"正常联想：真实的「选择」词根、真实词族与真实的政治搭配。"},"normal":[{"en":"ex- 'out' plus legere 'choose': to pick one person out of many.","cn":"ex-「出」加 legere「选」：从许多人中挑出一个。"},{"en":"The family runs elect, election, elector, electoral, electorate and elective.","cn":"同族词包括 elect、election、elector、electoral、electorate 与 elective。"},{"en":"Fixed phrases mark the process: general election, win the election, election result.","cn":"固定搭配标出过程：大选、赢得选举、选举结果。"},{"en":"The root legere also gives legible and lecture, which are about reading, not voting.","cn":"词根 legere 还给出 legible 与 lecture，它们关乎阅读，不关乎投票。"},{"en":"Lex 'law' is a different root: legislation and election are not close relatives.","cn":"lex「法律」是另一个词根：legislation 与 election 并非近亲。"}],"abstract":[{"en":"Picture a sealed box that turns many private papers into one public name.","cn":"想象一只封口的箱子，把许多私人的纸变成一个人人皆知的姓名。"},{"en":"Picture a queue where every person holds the same size of paper and the same weight of choice.","cn":"想象一列队伍，每个人手里的纸一样大，选择的分量也一样重。"},{"en":"Picture a single door that opens for one person and closes for the rest.","cn":"想象一扇只为一个人打开、对其余所有人关闭的门。"}]},"examples":[{"en":"The election was held two weeks after the debate.","cn":"选举在辩论结束两周后举行。"},{"en":"Local elections often attract fewer voters than national ones.","cn":"地方选举吸引的选民通常少于全国选举。"},{"en":"The doctrine of election shaped the whole sermon.","cn":"拣选学说塑造了整篇布道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「伊-莱克-申」——从人群里把「伊」人「莱克」（挑）出来，再把结果「申」告出来 → 选举","word":"election"},"root":"拉丁 electio「选择」← eligere「挑出」= ex-（出）+ legere「选择、收集」；legere 与 lex「法律」是两个不同词根。","sensesIntro":{"en":"Eight senses follow one picking-out: the procedure, the day, the contest, one countable instance, God's choosing, plain choice, a legal choice and the fact of having won.","cn":"八个义项跟随同一个「挑出」动作：程序、投票日、选战、一场可数的选举、神的拣选、朴素的选择、法律上的选择、以及已经当选这一事实。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed box in front of a queue of people, each holding one folded paper.","cn":"核心意象：一只封口的箱子摆在队伍前，每人手里一张折好的纸。"},"chain":["PICKING OUT","VOTING PROCEDURE","VOTING DAY","THE CONTEST","DIVINE CHOICE","BEING ELECTED"],"branches":[{"senses":"01 · 02","en":"PROCESS AND DAY: a procedure needs a date, so one noun covers both.","cn":"程序与日期：程序需要一个日期，于是同一个名词覆盖两者。"},{"senses":"03 · 04","en":"ONE RACE, MANY RACES: a campaign is a single contest, while repeated votes are counted in the plural.","cn":"一场与多场：一次选战是一场比赛，而反复的投票用复数来数。"},{"senses":"05 · 06","en":"GOD AND PLAIN CHOICE: the theological sense and the archaic sense both keep the bare verb 'to choose'.","cn":"神与朴素选择：神学义与古义都保留着「选择」这个光秃秃的动词。"},{"senses":"07","en":"THE LAWYER'S CHOICE: a binding choice between remedies is the old sense put to legal work.","cn":"法律人的选择：在救济方式间作有约束力的选择，是旧义被用于法律工作。"},{"senses":"08","en":"THE WINNER: English often names an event by its result.","cn":"胜出者：英语常用结果来命名事件。"}]},"affixes":{"intro":{"en":"Election is built from a Latin prefix and a choosing root, and that root also builds reading words, which is why the family has two faces.","cn":"election 由一个拉丁前缀与一个「选择」词根构成，该词根还构成一批「读」的词，因此这个词族有两副面孔。"},"latinIntro":{"en":"Legere gives eligere 'pick out' and legere 'read'; electio is the noun of the first, and -or builds elector.","cn":"legere 给出 eligere「挑出」与「读」两义；electio 是前者的名词，-or 构成 elector。"},"items":[{"word":"legere","structure":"legere, legi, lectum (Latin verb, third conjugation)","meaning":"to gather, choose, read","meaningCN":"收集；选择；读","example":"The verb has both a choosing and a reading face.","exampleCN":"这个动词有「选择」与「读」两副面孔。"},{"word":"eligere","structure":"ex- + legere","meaning":"to pick out, select","meaningCN":"挑出；选出","example":"The council eligere a new member.","exampleCN":"理事会选出了一名新成员。"},{"word":"electio","structure":"eligere + -tio (action noun)","meaning":"a choosing","meaningCN":"选择","example":"The noun names the act before it names the ballot.","exampleCN":"这个名词先指动作，后指投票。"},{"word":"elect","structure":"electus, past participle of eligere","meaning":"to choose by vote","meaningCN":"以投票选出","example":"The town elects a mayor every four years.","exampleCN":"这个镇每四年选一次镇长。"},{"word":"election","structure":"electio through French","meaning":"a choosing by vote","meaningCN":"投票选举","example":"The election result was close.","exampleCN":"选举结果很接近。"},{"word":"elector","structure":"elect + -or (person)","meaning":"one who votes","meaningCN":"选民","example":"Every elector receives one ballot.","exampleCN":"每位选民领到一张选票。"},{"word":"electoral","structure":"elector + -al (relating to)","meaning":"relating to elections","meaningCN":"与选举有关的","example":"The electoral map changed after the census.","exampleCN":"人口普查后选举版图变了。"},{"word":"electorate","structure":"elector + -ate (body or office)","meaning":"the body of voters","meaningCN":"全体选民","example":"The electorate has grown younger.","exampleCN":"全体选民变得更年轻了。"},{"word":"elective","structure":"elect + -ive (tending to)","meaning":"chosen by vote; optional","meaningCN":"选举产生的；选修的","example":"She took an elective course in law.","exampleCN":"她选修了一门法律课。"}],"latinEntries":[{"word":"legere","structure":"legere, legi, lectum (verb, third conjugation)","meaning":"to gather, choose, read","meaningCN":"收集；选择；读"},{"word":"eligere","structure":"eligere, elegi, electum (verb, third conjugation)","meaning":"to pick out","meaningCN":"挑出"},{"word":"electio","structure":"electio, electionis (f., third declension)","meaning":"a choosing","meaningCN":"选择"},{"word":"elector","structure":"elector, electoris (m., third declension)","meaning":"a chooser","meaningCN":"选择者"}],"derivatives":[{"word":"elect","pos":"v./adj.","zh":"选举；当选未就职的"},{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electoral","pos":"adj.","zh":"选举的"},{"word":"electorate","pos":"n.","zh":"全体选民"},{"word":"elective","pos":"adj./n.","zh":"选举产生的；选修课"},{"word":"electioneer","pos":"v.","zh":"从事竞选活动"}]}},{"word":"electoral","ipa_uk":"/ɪˈlektərəl/","ipa_us":"/ɪˈlektərəl/","definition_zh":"选举的；选举人的；与选民有关的","definition_en":"relating to elections, to electors or to the system by which votes are counted","core_image":"一张被划成许多格子的地图，每格上写着数字，数字加起来等于一个总数","scene":"墙上挂着一张被划成许多格子的地图，每格都写着数字。The electoral system gives small districts more weight than their population.","sceneCN":"句中这个词指与选举制度有关的（第 3 个义项：关于选票如何计算的制度安排）；句意为这套选举制度让小选区获得超过其人口比例的权重。图中可辨识物件：分格地图、数字牌、计票表、选区边界线、投票箱。","pos":[{"tag":"adj.","zh":"选举的；与选举有关的"},{"tag":"adj.","zh":"选举人的；与选民有关的"}],"collocations":[{"phrase":"electoral system","zh":"选举制度"},{"phrase":"electoral college","zh":"选举人团"},{"phrase":"electoral district","zh":"选区"},{"phrase":"electoral fraud","zh":"选举舞弊"},{"phrase":"electoral roll","zh":"选民名册"},{"phrase":"electoral votes","zh":"选举人票"}],"forms":[{"label":"原级","form":"electoral"},{"label":"副词","form":"electorally"},{"label":"名词（选民）","form":"elector"},{"label":"名词（全体选民）","form":"electorate"},{"label":"名词（选举）","form":"election"}],"derivatives":[{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electorate","pos":"n.","zh":"全体选民"},{"word":"election","pos":"n.","zh":"选举"},{"word":"electorally","pos":"adv.","zh":"在选举方面"},{"word":"elect","pos":"v.","zh":"选举"},{"word":"elective","pos":"adj.","zh":"选举产生的"}],"senses":[{"no":"01","title":"Relating to elections","titleCN":"与选举有关的","definition":"concerning the process or event of voting people into office","definitionCN":"与把人员投票选入公职的程序或活动有关的","example":"Electoral reform dominated the party's manifesto.","exampleCN":"选举改革主导了该党的宣言。","why":"The adjective is elector plus -al, so it began as 'of the elector' and widened to the whole process.","whyCN":"这个形容词是 elector 加 -al，最初指「选民的」，后扩展到整个程序。"},{"no":"02","title":"Relating to voters","titleCN":"与选民有关的","definition":"concerning the people who have the right to vote","definitionCN":"与拥有投票权的人有关的","example":"The electoral roll was checked for duplicate names.","exampleCN":"选民名册被核查是否有重名。","why":"An election exists only if there are electors, so the adjective often points at them directly.","whyCN":"只有存在选民才有选举，因此这个形容词常常直接指向他们。"},{"no":"03","title":"Of a voting system","titleCN":"选举制度的","definition":"describing the rules that convert votes into seats, such as first-past-the-post or proportional representation","definitionCN":"描述把选票换算成席位的规则，如简单多数制或比例代表制","example":"The electoral system gives small districts more weight than their population.","exampleCN":"这套选举制度让小选区获得超过其人口比例的权重。","why":"How votes become seats is a separate machinery, and the adjective names that machinery.","whyCN":"选票如何变成席位是一套独立的机器，这个形容词命名那套机器。"},{"no":"04","title":"Of districts and boundaries","titleCN":"选区与边界的","definition":"relating to the geographic units that return members and the lines drawn around them","definitionCN":"与推举议员的地理单位及其划界有关的","example":"The electoral boundary ran along the river.","exampleCN":"选区边界沿河而行。","why":"Votes are counted by area in most systems, so the adjective attaches to maps.","whyCN":"多数制度按地域计票，因此这个形容词附着在地图上。"},{"no":"05","title":"Of fraud and malpractice","titleCN":"选举舞弊与违规的","definition":"used of illegal interference with voting, such as bribery or ballot tampering","definitionCN":"用于指对投票的非法干预，如贿选或篡改选票","example":"The court annulled the result for electoral fraud.","exampleCN":"法院因选举舞弊宣布结果无效。","why":"A process that distributes power attracts attempts to bend it, and the adjective marks those attempts.","whyCN":"分配权力的程序会招来扭曲它的企图，这个形容词标记这类企图。"},{"no":"06","title":"Of electoral votes","titleCN":"选举人票的","definition":"relating to the votes cast by electors in an indirect system such as the American college","definitionCN":"与间接制度（如美国选举人团）中选举人所投票数有关","example":"He won the electoral vote but lost the popular vote.","exampleCN":"他赢下了选举人票，却输掉了普选票。","why":"In an indirect system, the elector is the voter, and the adjective distinguishes that layer from the public vote.","whyCN":"在间接制度里，选举人就是投票者，这个形容词把这一层与公众投票区分开。"},{"no":"07","title":"Of a German prince-elector","titleCN":"德意志选帝侯的（历史）","definition":"historical use for the dignity or territory of a prince who had the right to elect the emperor","definitionCN":"历史用法，指有权选举皇帝的诸侯所拥有的尊位或领地","example":"The electoral dignity passed to the Bavarian branch.","exampleCN":"选帝侯尊位传给了巴伐利亚一支。","why":"The Holy Roman Empire had a small college of electors, and English borrowed the adjective for their status.","whyCN":"神圣罗马帝国有一个小规模的选举人团，英语借用了这个形容词来指其地位。"},{"no":"08","title":"Choosing by a small body","titleCN":"由小团体选择（引申）","definition":"extended use for a selection made by a limited group rather than a mass vote","definitionCN":"引申用法，指由有限团体而非大众投票作出的选择","example":"The club's electoral procedure involved only nine members.","exampleCN":"这个俱乐部的选举程序只涉及九名成员。","why":"The word keeps the idea of a defined body of choosers, which applies at any scale.","whyCN":"这个词保留了「由一群确定的选者来选」的意思，这在任何尺度上都适用。"}],"etymology":{"intro":{"en":"Electoral is elector plus -al. Elector came into English in the mid-fifteenth century from Latin elector 'chooser', built on eligere 'to pick out'. The German electoral dignity is a sixteenth-century borrowing.","cn":"electoral 是 elector 加 -al。elector 于十五世纪中期从拉丁 elector「选择者」进入英语，由 eligere「挑出」构成。德意志选帝侯尊位是十六世纪的借用。"},"items":[{"era":"LATIN LEGERE","en":"Legere meant 'to gather, pick, read', and from it came eligere 'to pick out'. The reading branch gives legible and lecture, which are not political.","cn":"legere 意为「收集、挑选、读」，由它产生 eligere「挑出」。其中「读」的一支给出 legible 与 lecture，与政治无关。"},{"era":"LATIN ELECTOR","en":"Elector was the agent noun for a chooser, formed with -or from the past-participle stem of eligere.","cn":"elector 是「选择者」的施事名词，由 eligere 的过去分词词干加 -or 构成。"},{"era":"ENGLISH 1450","en":"English elector first meant one who elects or has the right of choice, and later a member of an electoral college.","cn":"英语 elector 先指选举者或拥有选择权的人，后指选举人团的成员。"},{"era":"THE SUFFIX -AL","en":"The ending -al came from Latin -alis and marks relation, so electoral means 'of an elector' before it means 'of an election'.","cn":"词尾 -al 来自拉丁 -alis，标记关系，因此 electoral 先表示「选民的」，后表示「选举的」。"},{"era":"GERMAN DIGNITY","en":"In the Holy Roman Empire a small college of princes held the right to elect the emperor, and English used electoral for their title and territory.","cn":"在神圣罗马帝国，一小群诸侯拥有选举皇帝的权利，英语用 electoral 指他们的头衔与领地。"},{"era":"MODERN USE","en":"The modern senses of systems, boundaries and fraud belong to the nineteenth and twentieth centuries, when mass electorates and seat-counting rules became central.","cn":"制度、边界与舞弊等现代义属于十九与二十世纪，那时大众选民与席位换算规则成为核心。"}]},"similar":{"note":{"en":"Group one holds the election family, whose members differ by ending and are often swapped; group two holds adjectives about the machinery of representation.","cn":"第一组是 election 词族，成员差别在词尾，常被互换；第二组是关于代表制机器的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"elector","ipa":"/ɪˈlektə/","tag":"a person","definition":"A person with the right to vote, or a member of an electoral college; it names a person, not a quality.","definitionCN":"指有投票权的人，或选举人团成员；它命名人，不命名性质。"},{"word":"electorate","ipa":"/ɪˈlektərət/","tag":"the whole body","definition":"All the voters taken together; the adjective describes them, the noun collects them.","definitionCN":"指全体选民合起来；形容词描述他们，名词收集他们。"},{"word":"election","ipa":"/ɪˈlekʃən/","tag":"the event","definition":"The process or event of voting; the adjective is what relates something to that event.","definitionCN":"指投票的程序或活动；形容词表示某物与该活动相关。"},{"word":"elective","ipa":"/ɪˈlektɪv/","tag":"chosen or optional","definition":"Filled by election, or a course a student chooses; it describes a post or a subject, not the system.","definitionCN":"指由选举产生的，或学生自选的课程；描述职位或科目，不描述制度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"parliamentary","ipa":"/ˌpɑːləˈmentəri/","tag":"of the assembly","definition":"Relating to a parliament; elections produce its members, but parliamentary describes the chamber's own rules and model.","definitionCN":"指与议会有关的；选举产生其成员，但 parliamentary 描述议院自身的规则与模式。"},{"word":"constituency","ipa":"/kənˈstɪtjuənsi/","tag":"the district as a noun","definition":"The body of voters in a district, or the district itself; electoral describes it as an adjective.","definitionCN":"指某选区的选民群体，或该选区本身；electoral 是它的形容词说法。"},{"word":"voting","ipa":"/ˈvəʊtɪŋ/","tag":"the act","definition":"The act or practice of casting votes; it is the plain activity, while electoral refers to the organised system.","definitionCN":"指投票的行为或做法；是朴素的活动，而 electoral 指有组织的制度。"},{"word":"political","ipa":"/pəˈlɪtɪkəl/","tag":"the wider field","definition":"Relating to government and power generally; electoral is the narrower adjective for the vote alone.","definitionCN":"泛指与政府和权力有关的；electoral 是只就投票而言的更窄形容词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffix, the real root and the real institutional phrases.","cn":"正常联想：真实词尾、真实词根与真实的机构搭配。"},"normal":[{"en":"elector plus -al 'relating to': everything that belongs to the people who choose.","cn":"elector 加 -al「与……有关」：一切属于那些作选择的人的事物。"},{"en":"The family runs elect, election, elector, electorate, electoral and elective.","cn":"同族词包括 elect、election、elector、electorate、electoral 与 elective。"},{"en":"Fixed phrases mark the machinery: electoral system, electoral college, electoral fraud.","cn":"固定搭配标出机器：选举制度、选举人团、选举舞弊。"},{"en":"The root eligere means 'pick out', which is what a vote does.","cn":"词根 eligere 意为「挑出」，这正是投票所做的事。"},{"en":"The German electoral princes show that the word is older than mass democracy.","cn":"德意志选帝侯说明这个词比大众民主更老。"}],"abstract":[{"en":"Picture a map cut into unequal squares, each square given a number larger than its size.","cn":"想象一张地图被切成大小不等的方格，每格的数字都大于它的面积。"},{"en":"Picture a ledger where names are crossed out and re-entered every few years.","cn":"想象一本账簿，每隔几年就把名字划掉再重写。"},{"en":"Picture a small room of nine people choosing for a whole city.","cn":"想象一间九个人的小屋子替整座城市作选择。"}]},"examples":[{"en":"The electoral college meets in December.","cn":"选举人团在十二月开会。"},{"en":"Electoral boundaries were redrawn before the vote.","cn":"投票前选区边界被重新划定。"},{"en":"The government promised electoral reform within a year.","cn":"政府承诺一年内进行选举改革。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「伊-莱克-特-柔」——把「伊」人「莱克」（挑）出来，再按「特」定的「柔」软格子分票 → 选举的","word":"electoral"},"root":"elector + -al；elector 来自拉丁 elector「选择者」← eligere「挑出」= ex- + legere「选择」。","sensesIntro":{"en":"Eight senses all describe the same machinery from different angles: the event, the voters, the seat-counting rules, the map, the fraud, the indirect vote, the historical prince-elector and any small choosing body.","cn":"八个义项从不同角度描述同一套机器：那场活动、那些选民、席位换算规则、地图、舞弊、间接投票、历史上的选帝侯、以及任何小规模的选者团体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a map cut into squares, each carrying a number larger than its size.","cn":"核心意象：被切成方格的地图，每格的数字都大于它的面积。"},"chain":["OF ELECTORS","OF ELECTIONS","SEAT-COUNTING RULES","THE MAP","FRAUD","INDIRECT VOTE"],"branches":[{"senses":"01 · 02","en":"EVENT AND PEOPLE: an election and its electors are two sides of one adjective.","cn":"活动与人：选举与其选民是同一形容词的两面。"},{"senses":"03 · 04","en":"RULES AND MAP: a system needs boundaries before it can count anything.","cn":"规则与地图：制度要先有边界，才能计票。"},{"senses":"05 · 06","en":"BENDING AND LAYERING: fraud attacks the count, while indirect votes add a layer above the public.","cn":"扭曲与分层：舞弊攻击计票，间接投票则在公众之上加一层。"},{"senses":"07","en":"THE ELECTORAL PRINCE: a tiny college choosing an emperor shows the word's oldest reach.","cn":"选帝侯：一个替皇帝作选择的小团体，显示这个词最老的延伸。"},{"senses":"08","en":"THE SMALL ROOM: any limited body of choosers can use the adjective.","cn":"小屋子：任何有限的选者团体都能用这个形容词。"}]},"affixes":{"intro":{"en":"Electoral adds a Latin relational ending to a Latin person-noun, so the word is best read from its two pieces.","cn":"electoral 在拉丁人物名词上加了一个拉丁关系词尾，因此最好从两个构件来读。"},"latinIntro":{"en":"Legere gives eligere and elector; -or marks the person, and -al marks the relation.","cn":"legere 给出 eligere 与 elector；-or 标记人，-al 标记关系。"},"items":[{"word":"legere","structure":"legere, legi, lectum (verb, third conjugation)","meaning":"to gather, choose, read","meaningCN":"收集；选择；读","example":"The root has two visible branches.","exampleCN":"这个词根有两支可见的分支。"},{"word":"eligere","structure":"ex- + legere","meaning":"to pick out","meaningCN":"挑出","example":"The voters pick out one candidate.","exampleCN":"选民挑出一名候选人。"},{"word":"elector","structure":"elect + -or (person)","meaning":"one who chooses","meaningCN":"作选择的人","example":"Each elector casts one vote.","exampleCN":"每位选举人投一票。"},{"word":"electoral","structure":"elector + -al (relating to)","meaning":"relating to electors or elections","meaningCN":"与选举人或选举有关的","example":"The electoral map was redrawn.","exampleCN":"选举地图被重画。"},{"word":"electorate","structure":"elector + -ate (body)","meaning":"the body of voters","meaningCN":"全体选民","example":"The electorate doubled in size.","exampleCN":"选民人数翻了一番。"},{"word":"election","structure":"electio through French","meaning":"a choosing by vote","meaningCN":"投票选举","example":"The election drew a large turnout.","exampleCN":"这场选举投票率很高。"},{"word":"elective","structure":"elect + -ive (tending to)","meaning":"chosen by vote; optional","meaningCN":"选举产生的；选修的","example":"The post is elective.","exampleCN":"该职位由选举产生。"},{"word":"electorally","structure":"electoral + -ly (adverb)","meaning":"in electoral terms","meaningCN":"从选举角度看","example":"The region is electorally decisive.","exampleCN":"该地区在选举上具有决定性。"},{"word":"-al","structure":"-al (English adjective suffix, from Latin -alis)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending also builds senatorial.","exampleCN":"这个词尾还构成 senatorial。"}],"latinEntries":[{"word":"legere","structure":"legere, legi, lectum (verb, third conjugation)","meaning":"to choose, gather, read","meaningCN":"选择；收集；读"},{"word":"eligere","structure":"eligere, elegi, electum (verb, third conjugation)","meaning":"to pick out","meaningCN":"挑出"},{"word":"elector","structure":"elector, electoris (m., third declension)","meaning":"a chooser","meaningCN":"选择者"},{"word":"electio","structure":"electio, electionis (f., third declension)","meaning":"a choosing","meaningCN":"选择"}],"derivatives":[{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electorate","pos":"n.","zh":"全体选民"},{"word":"election","pos":"n.","zh":"选举"},{"word":"electorally","pos":"adv.","zh":"在选举方面"},{"word":"elect","pos":"v.","zh":"选举"},{"word":"elective","pos":"adj.","zh":"选举产生的"}]}},{"word":"electorate","ipa_uk":"/ɪˈlektərət/","ipa_us":"/ɪˈlektərət/","definition_zh":"全体选民；选民群体；（历史）选帝侯的职位与领地","definition_en":"the body of people entitled to vote in an election; historically, the office or territory of a prince-elector","core_image":"一本摊开的名册，每行一个名字，写满整页，页边压着一只封口的投票箱","scene":"登记处的长桌上摊开一本厚名册，每一页写满名字，工作人员逐行核对。The electorate grew by nearly a million after the voting age was lowered.","sceneCN":"句中这个词指依法享有投票权的全体选民（第 1 个义项：一国或一地区内有权投票的全体选民）；句意为投票年龄下调后，全体选民增加了近一百万人。图中可辨识物件：厚名册、台灯、核对章、卡片盒、封口的投票箱。","pos":[{"tag":"n.","zh":"全体选民；选民群体"},{"tag":"n.","zh":"（历史）选帝侯的职位与领地"}],"collocations":[{"phrase":"the electorate at large","zh":"全体选民"},{"phrase":"a majority of the electorate","zh":"多数选民"},{"phrase":"appeal to the electorate","zh":"争取选民"},{"phrase":"the registered electorate","zh":"登记选民"},{"phrase":"expand the electorate","zh":"扩大选民范围"},{"phrase":"the mood of the electorate","zh":"选民情绪"}],"forms":[{"label":"复数","form":"electorates"},{"label":"名词（单个选民）","form":"elector"},{"label":"形容词","form":"electoral"},{"label":"名词（选举）","form":"election"},{"label":"动词","form":"elect"},{"label":"形容词（可选择的）","form":"elective"}],"derivatives":[{"word":"elect","pos":"v.","zh":"选举；选出"},{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electoral","pos":"adj.","zh":"选举的；与选举有关的"},{"word":"election","pos":"n.","zh":"选举；当选"},{"word":"elective","pos":"adj./n.","zh":"选举产生的；选修课"},{"word":"electioneer","pos":"v.","zh":"从事竞选活动"}],"senses":[{"no":"01","title":"The body of voters","titleCN":"全体选民","definition":"all the people in a country or area who have the right to vote in elections","definitionCN":"一国或一地区内依法享有投票权的全体人","example":"The electorate grew by nearly a million after the voting age was lowered.","exampleCN":"投票年龄下调后，全体选民增加了近一百万人。","why":"The suffix marks a collective body, so the word names voters as one mass rather than as individuals.","whyCN":"这个词尾标记集合体，因此该词把选民当作一个整体，而不是一个个个人。"},{"no":"02","title":"The voters of a district","titleCN":"某选区或某场选举的选民","definition":"the voters belonging to a particular constituency or to one election","definitionCN":"属于某一选区或某一场选举的选民","example":"The electorate in that district is older than the national average.","exampleCN":"该选区的选民年龄高于全国平均水平。","why":"A single election has its own electorate, because who may vote is fixed by place and by poll.","whyCN":"一场选举有自己的选民，因为谁可投票由地点与场次决定。"},{"no":"03","title":"Voters as a political force","titleCN":"作为政治力量的选民群体","definition":"the voters viewed as a bloc that campaigns try to win over","definitionCN":"被视作竞选各方争取的一个整体选民群体","example":"No party can ignore an electorate this volatile.","exampleCN":"没有哪个政党能忽视如此易变的选民群体。","why":"Once voters act together, they are spoken of as a force rather than as a list of names.","whyCN":"一旦选民共同行动，他们就被说成一股力量，而非一串名字。"},{"no":"04","title":"The polling public","titleCN":"民调与选情中的选民","definition":"the section of the public whose preferences opinion polls report","definitionCN":"民意调查所报道其偏好的那部分公众","example":"Polls show the electorate split almost evenly.","exampleCN":"民调显示选民几乎平分秋色。","why":"Polling reduces a whole country to a measurable public that can be described in percentages.","whyCN":"民调把整个国家化约成一个可以用百分比描述的可测公众。"},{"no":"05","title":"A prince-elector's office","titleCN":"选帝侯的职位（历史）","definition":"historically, the rank and office of a prince entitled to choose the Holy Roman Emperor","definitionCN":"历史上，有权选举神圣罗马帝国皇帝的诸侯所拥有的位阶与职位","example":"He held the electorate for thirty years.","exampleCN":"他持有选帝侯之位三十年。","why":"The German princes who chose the emperor were called electors, and their office took the same collective suffix.","whyCN":"选皇帝的德意志诸侯被称为选帝侯，其职位用了同一个表集合的词尾。"},{"no":"06","title":"An elector's territory","titleCN":"选帝侯的领地（历史）","definition":"the territory ruled by a prince-elector","definitionCN":"由选帝侯统治的领地","example":"The electorate stretched along both banks of the river.","exampleCN":"这片选帝侯领地沿河两岸延伸。","why":"Because the office came with land, the same noun could name the lands on a map.","whyCN":"由于职位附带土地，同一个名词也能指地图上的那片领地。"},{"no":"07","title":"Any body of choosers","titleCN":"任何组织中拥有选择权的全体成员","definition":"the members of any organisation who have the right to choose its officers","definitionCN":"任何组织中拥有选出负责人之权利的成员全体","example":"The shareholders form an electorate of their own.","exampleCN":"股东们构成了自己的选民群体。","why":"The pattern extends to clubs, companies and unions, wherever a group chooses its officers.","whyCN":"这个模式延伸到俱乐部、公司与工会，只要一个群体会选出自己的负责人。"},{"no":"08","title":"The franchise as a legal whole","titleCN":"作为法律整体的选举权","definition":"the total voting power of a population considered as one legal capacity","definitionCN":"把全体人口的投票权视为一项法律上的能力","example":"A constitutional amendment widened the electorate.","exampleCN":"一项宪法修正案扩大了选民范围。","why":"Law treats the right to vote as one capacity held by many persons at once.","whyCN":"法律把投票权视为由许多人同时持有的一项能力。"}],"etymology":{"intro":{"en":"Electorate joins the Latin agent noun elector 'chooser' to the suffix -ate, from Latin -atus, which names an office, a status or a collective body. English took the word in the seventeenth century, first for the German princes who chose the emperor, and only much later for ordinary voters.","cn":"electorate 把拉丁施事名词 elector「选择者」接到后缀上，该后缀出自拉丁 -atus，用来命名职位、身份或集合体。英语在十七世纪吸收这个词，最初指选皇帝的德意志诸侯，很久以后才指普通选民。"},"items":[{"era":"LATIN ELIGERE","en":"Eligere 'to pick out' is ex- 'out' plus legere 'to choose, gather', the verb behind elect, election and elector alike.","cn":"eligere「挑出」由 ex-「出」与 legere「选择、收集」构成，是 elect、election 与 elector 共同的来源动词。"},{"era":"LATIN ELECTOR","en":"Elector was a plain agent noun meaning 'one who chooses' long before it became a title.","cn":"elector 原本只是普通的施事名词，意为「选择者」，远在它成为头衔之前就存在。"},{"era":"MEDIEVAL ELECTOR","en":"In the Holy Roman Empire the title elector was fixed on the princes who chose the emperor, a usage recorded from the thirteenth century onward.","cn":"在神圣罗马帝国，选帝侯这一头衔固定给选举皇帝的诸侯，这一用法自十三世纪起见于记载。"},{"era":"THE SUFFIX -ATE","en":"Latin -atus, carried into English through French -at, forms nouns of office, rank or collective body, as in electorate, episcopate and directorate.","cn":"拉丁 -atus 经法语 -at 进入英语，构成表职位、位阶或集合体的名词，如 electorate、episcopate 与 directorate 中的词尾。"},{"era":"ENGLISH 1670","en":"English electorate is recorded in the 1670s for the German electors as a body, and for the office and lands held by one of them.","cn":"英语 electorate 在十七世纪七十年代见于记载，指作为整体的德意志选帝侯，也指其中一位所持的职位与领地。"},{"era":"MODERN VOTERS 1879","en":"The everyday sense, the body of voters in a country, is recorded by 1879, when mass suffrage made the word a fixture of political reporting.","cn":"指一国全体选民的日常义项到 1879 年已见于记载，那时大众选举权使这个词成为政治报道的常客。"}]},"similar":{"note":{"en":"Group one holds words built on the same choosing root that differ in scope; group two holds the plain words for the right to vote and for the people who hold it.","cn":"第一组是同出「选择」词根但范围不同的词；第二组是投票权本身以及持有投票权者的朴素说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"elector","ipa":"/ɪˈlektə/","tag":"the single voter","definition":"One person who votes; electorate is the whole body that contains such persons.","definitionCN":"指投票的单个个人；electorate 是包含这些人的整个群体。"},{"word":"electoral","ipa":"/ɪˈlektərəl/","tag":"the adjective","definition":"Relating to elections or electors; it describes a system, while electorate names the people.","definitionCN":"指与选举或选民有关的；它描述制度，而 electorate 指人。"},{"word":"election","ipa":"/ɪˈlekʃən/","tag":"the event","definition":"The vote itself; the electorate is the people who take part in it.","definitionCN":"指投票这件事本身；electorate 是参与其中的那些人。"},{"word":"elite","ipa":"/eɪˈliːt/","tag":"the chosen few","definition":"From the same choosing root, but it names a small selected group, not a voting public.","definitionCN":"同出「选择」词根，但指被挑出的小群精英，不是投票公众。"}]},{"heading":"NEAR MEANING","entries":[{"word":"voters","ipa":"/ˈvəʊtəz/","tag":"the plain plural","definition":"The ordinary plural for people who vote; electorate is the collective singular for the same people.","definitionCN":"指投票者的普通复数；electorate 是同一群人的集合单数。"},{"word":"constituency","ipa":"/kənˈstɪtjuənsi/","tag":"the district body","definition":"The voters of one district, or that district itself; an electorate may be national or local.","definitionCN":"指某一选区的选民，或该选区本身；electorate 可以是全国的，也可以是地方的。"},{"word":"franchise","ipa":"/ˈfræntʃaɪz/","tag":"the right itself","definition":"The legal right to vote; the electorate is the people who hold that right.","definitionCN":"指投票的法律权利；electorate 是持有这项权利的人。"},{"word":"suffrage","ipa":"/ˈsʌfrɪdʒ/","tag":"the right to vote","definition":"Often used of the extension of voting rights; electorate focuses on the body of holders.","definitionCN":"常用于指投票权的扩展；electorate 着眼于持有权利的人群。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real choosing root, the real office suffix and the real political phrases.","cn":"正常联想：真实的「选择」词根、真实的职位后缀与真实的政治搭配。"},"normal":[{"en":"elector 'chooser' plus a suffix of office: the body of choosers taken as one.","cn":"elector「选择者」加上表职位的词尾：把选择者合为一个整体。"},{"en":"The family runs elect, election, elector, electoral, electorate and elective.","cn":"同族词包括 elect、election、elector、electoral、electorate 与 elective。"},{"en":"Fixed phrases mark the collective: the electorate at large, a majority of the electorate.","cn":"固定搭配标出集合用法：全体选民、多数选民。"},{"en":"The root legere also gives legible and lecture, which concern reading, not voting.","cn":"词根 legere 还给出 legible 与 lecture，它们关乎阅读，不关乎投票。"},{"en":"Lex 'law' is a different root: legislation and electorate are not close relatives.","cn":"lex「法律」是另一个词根：legislation 与 electorate 并非近亲。"}],"abstract":[{"en":"Picture one sheet of paper so long that every name in the country fits on it.","cn":"想象一张长到能把全国每个名字都写下的纸。"},{"en":"Picture a crowd that is counted as a single person when a government changes hands.","cn":"想象一群人，在政府更替时被当作一个人来计数。"},{"en":"Picture a gate that opens only for those whose names are already written inside.","cn":"想象一扇只为名字已写在门内者打开的门。"}]},"examples":[{"en":"The electorate grew by nearly a million after the voting age was lowered.","cn":"投票年龄下调后，全体选民增加了近一百万人。"},{"en":"Candidates spent the last week appealing to an undecided electorate.","cn":"候选人用最后一周争取尚未拿定主意的选民。"},{"en":"The electorate of Saxony was one of the most powerful in the old empire.","cn":"萨克森选帝侯领曾是旧帝国中最有权势的领地之一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「伊-莱克-特-瑞特」——把人一个个「挑」出来（莱克），汇成一整片写满名字的名册 → 全体选民","word":"electorate"},"root":"拉丁 elector「选择者」← eligere「挑出」= ex-（出）+ legere「选择、收集」；词尾为拉丁 -atus 演变来的名词后缀，表职位、身份或集合体。","sensesIntro":{"en":"Eight senses move from the whole body of voters to a district's voters, a political bloc, the polling public, the old princely office and its lands, any body of choosers, and the franchise as one legal capacity.","cn":"八个义项从全体选民出发，依次是某选区的选民、作为政治力量的选民群体、民调中的选民、旧时的选帝侯职位及其领地、任何组织中有选择权的全体成员，以及作为一项法律能力的选举权。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long open register, one name per line, filling every page, with a sealed box at its edge.","cn":"核心意象：一本摊开的长名册，每行一个名字，写满每一页，页边放着一只封口的箱子。"},"chain":["BODY OF VOTERS","DISTRICT VOTERS","VOTERS AS A BLOC","POLLING PUBLIC","PRINCE-ELECTOR'S OFFICE","LANDS OF AN ELECTOR"],"branches":[{"senses":"01 · 03","en":"THE MASS AND THE FORCE: a list of names becomes a bloc once its members act together.","cn":"整体与力量：一份名单在成员共同行动时变成一股力量。"},{"senses":"02 · 04","en":"PLACE AND SAMPLE: one district's voters and a poll's public are the same body seen at different scales.","cn":"地点与样本：一个选区的选民与民调中的公众，是同一群体在不同尺度上的样子。"},{"senses":"05 · 06","en":"OFFICE AND LAND: the German title came with territory, so one noun named both.","cn":"职位与土地：德意志的选帝侯头衔附带领地，于是一个名词兼指两者。"},{"senses":"07","en":"ANY CHOOSING BODY: clubs and companies copy the pattern whenever members elect officers.","cn":"任何有选择权的群体：只要成员选举负责人，俱乐部与公司就复制了这个模式。"},{"senses":"08","en":"ONE CAPACITY, MANY HOLDERS: law treats the vote as a single right shared by a whole population.","cn":"一种能力，众多持有者：法律把投票权视为全体人口共有的一项权利。"}]},"affixes":{"intro":{"en":"Electorate is an agent noun plus a suffix of office and collective status: the choosers are made into one body.","cn":"electorate 是一个施事名词加上表职位与集合身份的后缀：选择者被聚合成一个整体。"},"latinIntro":{"en":"Eligere supplies elector 'one who chooses'; Latin -atus, carried through French, turns that person into a body or an office.","cn":"eligere 提供 elector「选择者」；经法语传来的拉丁 -atus 把这个人变成一群体或一项职位。"},"items":[{"word":"eligere","structure":"eligere, elegi, electum (verb, third conjugation)","meaning":"to pick out","meaningCN":"挑出","example":"Latin eligere supplies the whole family of choosing words.","exampleCN":"拉丁 eligere 提供了整个「选择」词族。"},{"word":"elector","structure":"elector, electoris (m., third declension)","meaning":"a chooser","meaningCN":"选择者","example":"In Rome an elector was simply one who chose.","exampleCN":"在罗马，elector 只表示作选择的人。"},{"word":"-atus","structure":"Latin -atus, -atis (m., fourth declension; suffix of office)","meaning":"office, rank or collective body","meaningCN":"职位、位阶或集合体","example":"The suffix turns one person into an office or a body of persons.","exampleCN":"这个词尾把单个人变成一项职位或一群人。"},{"word":"-ate","structure":"English -ate, through French -at, from Latin -atus","meaning":"noun ending for a body or an office","meaningCN":"表集合体或职位的名词词尾","example":"English keeps the ending in electorate, episcopate and directorate.","exampleCN":"英语在 electorate、episcopate 与 directorate 中保留了这一词尾。"},{"word":"elect","structure":"electus, past participle of eligere","meaning":"to choose by vote","meaningCN":"以投票选出","example":"Voters elect a mayor every four years.","exampleCN":"选民每四年选一次市长。"},{"word":"election","structure":"electio + -tion through French","meaning":"the act or event of voting","meaningCN":"选举的行为或活动","example":"The election was decided by one district.","exampleCN":"这场选举由一个选区决定。"},{"word":"elector","structure":"elector, agent noun of eligere","meaning":"one who votes","meaningCN":"投票者；选民","example":"Each elector signs the register.","exampleCN":"每位选民在名册上签名。"},{"word":"electoral","structure":"elector + -al (relating to)","meaning":"relating to elections","meaningCN":"与选举有关的","example":"The electoral map was redrawn.","exampleCN":"选举版图被重新划定。"},{"word":"electorate","structure":"elector + -ate (body or office)","meaning":"the body of voters","meaningCN":"全体选民","example":"The electorate doubled in a decade.","exampleCN":"十年间全体选民翻了一倍。"},{"word":"elective","structure":"elect + -ive (tending to)","meaning":"chosen by vote; optional","meaningCN":"选举产生的；选修的","example":"She took an elective course in statistics.","exampleCN":"她选修了一门统计学课程。"}],"latinEntries":[{"word":"eligere","structure":"eligere, elegi, electum (verb, third conjugation)","meaning":"to pick out","meaningCN":"挑出"},{"word":"elector","structure":"elector, electoris (m., third declension)","meaning":"a chooser","meaningCN":"选择者"},{"word":"electio","structure":"electio, electionis (f., third declension)","meaning":"a choosing","meaningCN":"选择"},{"word":"-atus","structure":"Latin -atus, -atis (m., fourth declension)","meaning":"suffix of office or collective body","meaningCN":"表职位或集合体的后缀"}],"derivatives":[{"word":"elect","pos":"v.","zh":"选举；选出"},{"word":"elector","pos":"n.","zh":"选民；选举人"},{"word":"electoral","pos":"adj.","zh":"选举的"},{"word":"election","pos":"n.","zh":"选举"},{"word":"elective","pos":"adj./n.","zh":"选举产生的；选修课"},{"word":"electioneer","pos":"v.","zh":"从事竞选活动"}]}}]);
